/*
Requires-to-ensures contract entailment engine, inductive transition proving,
ranking ranges, and arithmetic and structural algebra judgments
(`proof_contracts::contract_entailment`).
*/
pub(crate) use specification_calls::applied_bindings::PredicateMachineBinding;

pub(crate) mod arithmetic_judgment {
    use super::{
        BTreeMap, BigInt, BinaryOperator, ExpressionHandle, ExpressionNode, Machine, RESULT_BINDER,
        SymbolHandle, proof_nat_cast,
    };
    use crate::CheckingInput;
    use crate::frozen_program::expression_table;
    use crate::proof_integer_expression;
    use std::sync::Arc;
    use typed_trees::expression::TableCastExpression;
    use typed_trees::expression::TableMatchExpression;
    use typed_trees::expression::UnaryOperator;
    use typed_trees::types::TypeReferenceHandle;
    pub(crate) mod application_formation {
        use super::{Engine, IntegerApplicationInput, Polynomial};

        pub(crate) mod calls {
            use super::{
                ApplicationDecisions, Engine, IntegerApplicationInput, Polynomial, dispatch,
                formed_type, formed_value,
            };
            use crate::frozen_program::expression_table;
            use crate::proof_contracts::contract_entailment::specification_calls::{
                SelectedCallContract, owner_contracts, owner_parameters, owner_return_type,
                owner_symbol, requirements_are_acyclic, selected_call_contract,
            };
            use numerics::bignum::BigInt;
            use typed_trees::domain::ProofFact;
            use typed_trees::expression::ExpressionHandle;
            use typed_trees::signature::SignatureContractKind;

            pub(crate) fn form(
                engine: &mut Engine<'_>,
                program: &dyn crate::CheckingInput,
                expression: ExpressionHandle,
                depth: usize,
                decisions: &mut ApplicationDecisions,
            ) -> Option<Polynomial> {
                let call = expression_table(program).call_node(expression)?;
                if super::super::super::struct_trace_owner(program, engine.source_owner) {
                    eprintln!(
                        "STRUCT declaration-call begin expression={expression:?} owner={:?} owned={} reads={}",
                        engine.source_owner,
                        engine.owned_arguments.len(),
                        engine.formal_read_arguments.len()
                    );
                }
                let owner = selected_call_contract(program, engine.source_owner, call)?;
                let parameters = owner_parameters(program, &owner);
                let arguments = expression_table(program).expression_handles(call.arguments);
                if parameters.len() != arguments.len()
                    || !requirements_are_acyclic(program, &owner, &mut Vec::new(), &mut Vec::new())
                {
                    return None;
                }
                let input_types = parameters
                    .iter()
                    .zip(arguments)
                    .map(|(parameter, argument)| {
                        engine.call_input_type(*argument, parameter.type_reference)
                    })
                    .collect::<Option<Vec<_>>>()?;
                let actuals = parameters
                    .iter()
                    .zip(arguments)
                    .zip(&input_types)
                    .map(|((parameter, argument), required_type)| {
                        let input = if program
                            .primitive_type_reference(parameter.type_reference)
                            .is_some()
                        {
                            IntegerApplicationInput::Scalar(formed_value(
                                engine,
                                program,
                                *argument,
                                depth + 1,
                                decisions,
                            )?)
                        } else {
                            engine.captured_record_call_input(*argument, parameters, arguments)?
                        };
                        if !crate::has_anonymous_numeric_results(program, *argument) {
                            let actual_type = match &input {
                                IntegerApplicationInput::Record { type_reference, .. } => {
                                    *type_reference
                                }
                                IntegerApplicationInput::Scalar(_) => {
                                    engine.source_result_type(*argument)?
                                }
                            };
                            if !crate::declared_input_type_matches(
                                program,
                                actual_type,
                                *required_type,
                            ) {
                                return None;
                            }
                        }
                        Some((*argument, input))
                    })
                    .collect::<Option<Vec<_>>>()?;
                if super::super::super::struct_trace_owner(program, engine.source_owner) {
                    eprintln!(
                        "STRUCT declaration-call inputs expression={expression:?} actuals={actuals:?}"
                    );
                }
                with_arguments(
                    engine,
                    owner_symbol(&owner),
                    parameters,
                    &actuals,
                    |engine| {
                        for ((parameter, (_, input)), required_type) in
                            parameters.iter().zip(&actuals).zip(&input_types)
                        {
                            match input {
                                IntegerApplicationInput::Scalar(value) => {
                                    formed_type(engine, program, parameter.type_reference, value)
                                        .then_some(())?;
                                }
                                IntegerApplicationInput::Record {
                                    type_reference,
                                    snapshot,
                                    ..
                                } => {
                                    let snapshot = snapshot.as_ref()?;
                                    if !crate::declared_input_type_matches(
                                        program,
                                        snapshot.actual_type(),
                                        *type_reference,
                                    ) || !crate::declared_input_type_matches(
                                        program,
                                        *type_reference,
                                        *required_type,
                                    ) {
                                        return None;
                                    }
                                }
                            }
                        }
                        for contract in owner_contracts(program, &owner)
                            .filter(|contract| contract.kind == SignatureContractKind::Requires)
                        {
                            if contract.binding.is_some() {
                                return None;
                            }
                            for fact in program.proof_facts.span_or_empty(contract.facts) {
                                let ProofFact::Expression(requirement) = fact else {
                                    return None;
                                };
                                dispatch::require_condition(engine, *requirement, depth + 1)?;
                            }
                        }
                        Some(())
                    },
                )?;
                if super::super::super::struct_trace() {
                    eprintln!("STRUCT declaration-call requires expression={expression:?}");
                }
                let value = engine.selected_call_value(
                    engine.source_owner,
                    expression,
                    owner_symbol(&owner),
                    actuals.iter().map(|(_, value)| value.clone()).collect(),
                )?;
                let result_type = owner_return_type(&owner);
                let primitive = program.primitive_type_reference(result_type)?;
                let (minimum, maximum) = primitive.integer_bounds()?;
                engine
                    .bounds
                    .push((value.clone(), BigInt::from_i128(minimum)));
                engine
                    .bounds
                    .push((value.neg(), BigInt::from_i128(maximum).negate()));
                engine.refresh_difference_bounds();
                if !engine.complete_formed_call(expression, &actuals, &value) {
                    return None;
                }
                if super::super::super::struct_trace() {
                    eprintln!("STRUCT declaration-call guarantees expression={expression:?}");
                }
                with_arguments(
                    engine,
                    owner_symbol(&owner),
                    parameters,
                    &actuals,
                    |engine| formed_type(engine, program, result_type, &value).then_some(()),
                )?;
                let SelectedCallContract::Concrete(machine, state) = owner else {
                    return None;
                };
                let decision = checked_trees::CheckedDeclarationCall {
                    expression,
                    authored_target: call.target_symbol,
                    arguments: call.arguments,
                    checked_arguments: arena::HandleSpan::empty(),
                    target_machine: machine.symbol,
                    target_state: state.symbol,
                    target_contract: None,
                };
                if !decisions.calls.contains(&decision) {
                    decisions.calls.push(decision);
                }
                Some(value)
            }

            fn with_arguments<Output>(
                engine: &mut Engine<'_>,
                owner: symbols::SymbolHandle,
                parameters: &[typed_trees::signature::StateParameter],
                actuals: &[(ExpressionHandle, IntegerApplicationInput)],
                query: impl FnOnce(&mut Engine<'_>) -> Option<Output>,
            ) -> Option<Output> {
                let scalar = parameters
                    .iter()
                    .zip(actuals)
                    .filter_map(|(formal, (_, input))| match input {
                        IntegerApplicationInput::Scalar(value) => {
                            Some((formal.symbol, value.clone()))
                        }
                        _ => None,
                    })
                    .collect::<Vec<_>>();
                engine.with_formal_arguments(owner, &scalar, |engine| {
                    for (formal, (_, input)) in parameters.iter().zip(actuals) {
                        if let IntegerApplicationInput::Record {
                            snapshot, reads, ..
                        } = input
                        {
                            engine.owned_arguments.push((
                                crate::ScopedArithmeticBinder::Symbol(formal.symbol),
                                snapshot.clone()?,
                            ));
                            engine.formal_read_arguments.extend(reads.iter().map(
                                |(read, value)| {
                                    let mut read = read.clone();
                                    read.coordinate.parameter = formal.symbol;
                                    (read, value.clone())
                                },
                            ));
                        }
                    }
                    query(engine)
                })
            }
        }
        pub(crate) mod dispatch {
            use super::super::conditional_values::{Comparison, ConditionalValueArm};
            use super::{ApplicationDecisions, Engine, Polynomial, formed_value};
            use crate::frozen_program::expression_table;
            use typed_trees::expression::{
                BinaryOperator, ExpressionHandle, ExpressionNode, MatchPattern,
                TableMatchExpression, UnaryOperator,
            };
            use typed_trees::types::PrimitiveType;

            #[derive(Clone)]
            pub(crate) struct Path<'program> {
                engine: Engine<'program>,
                conditions: Vec<Comparison>,
            }

            impl Path<'_> {
                fn assume(mut self, comparison: Comparison) -> Option<Self> {
                    let comparison = (
                        comparison.0,
                        self.engine.substituted(&comparison.1),
                        self.engine.substituted(&comparison.2),
                    );
                    if self
                        .engine
                        .integer_comparisons_unsatisfiable(vec![comparison.clone()])
                    {
                        return None;
                    }
                    self.conditions.push(comparison);
                    Some(self)
                }
            }

            #[derive(Clone)]
            pub(crate) enum Subject {
                Integer(Polynomial),
                Boolean(bool),
            }

            fn has_boolean_carrier(engine: &Engine<'_>, expression: ExpressionHandle) -> bool {
                matches!(
                    expression_table(engine.program).expression(expression),
                    ExpressionNode::Boolean(_)
                ) || engine
                    .source_result_type(expression)
                    .and_then(|reference| engine.program.primitive_type_reference(reference))
                    == Some(PrimitiveType::Bool)
            }

            pub(crate) fn require_condition(
                engine: &Engine<'_>,
                expression: ExpressionHandle,
                depth: usize,
            ) -> Option<()> {
                engine.charge_conditional_work()?;
                let paths = condition_paths(
                    Path {
                        engine: engine.clone(),
                        conditions: Vec::new(),
                    },
                    expression,
                    depth,
                    &mut ApplicationDecisions::default(),
                )?;
                paths.iter().all(|(holds, _)| *holds).then_some(())
            }

            pub(crate) fn form(
                engine: &mut Engine<'_>,
                expression: ExpressionHandle,
                dispatch: &TableMatchExpression,
                depth: usize,
                decisions: &mut ApplicationDecisions,
            ) -> Option<Polynomial> {
                engine.charge_conditional_work()?;
                let program = engine.program;
                let path = Path {
                    engine: engine.clone(),
                    conditions: Vec::new(),
                };
                let boolean = has_boolean_carrier(engine, dispatch.subject);
                if crate::proof_contracts::contract_entailment::struct_trace() {
                    eprintln!(
                        "STRUCT declaration-dispatch begin expression={expression:?} boolean={boolean} subject={:?} type={:?}",
                        expression_table(program).expression(dispatch.subject),
                        engine.source_result_type(dispatch.subject)
                    );
                }
                let mut remaining = if boolean {
                    condition_paths(path, dispatch.subject, depth + 1, decisions)?
                        .into_iter()
                        .map(|(value, path)| (path, Subject::Boolean(value)))
                        .collect::<Vec<_>>()
                } else {
                    let mut path = path;
                    let value = formed_value(
                        &mut path.engine,
                        program,
                        dispatch.subject,
                        depth + 1,
                        decisions,
                    )?;
                    vec![(path, Subject::Integer(value))]
                };
                let mut values = Vec::new();
                for (ordinal, arm) in expression_table(program)
                    .match_arms(dispatch.arms)
                    .iter()
                    .enumerate()
                {
                    let source_arm = arena::Handle::from_parts(
                        dispatch
                            .arms
                            .start()
                            .arena_index()
                            .checked_add(u32::try_from(ordinal).ok()?)?,
                        dispatch.arms.start().generation(),
                    );
                    let mut selected = Vec::new();
                    let mut failed = Vec::new();
                    for (path, subject) in remaining {
                        path.engine.charge_conditional_work()?;
                        match arm.pattern {
                            MatchPattern::Wildcard => selected.push(path),
                            MatchPattern::Destructure(pattern) => {
                                for (matched, path) in
                                    condition_paths(path, pattern.condition, depth + 1, decisions)?
                                {
                                    if matched {
                                        selected.push(path);
                                    } else {
                                        failed.push((path, subject.clone()));
                                    }
                                }
                            }
                            MatchPattern::Value(pattern) => {
                                let operands = [dispatch.subject, pattern]
                                    .map(|operand| path.engine.source_result_type(operand));
                                if !typed_trees::operator::has_builtin_spelled_expression_meaning(
                                    program,
                                    path.engine.source_owner,
                                    expression,
                                    language_core::OperatorSpelling::Equal,
                                    &operands,
                                ) {
                                    return None;
                                }
                                match subject {
                                    Subject::Boolean(value) => {
                                        for (pattern, path) in
                                            condition_paths(path, pattern, depth + 1, decisions)?
                                        {
                                            if value == pattern {
                                                selected.push(path);
                                            } else {
                                                failed.push((path, Subject::Boolean(value)));
                                            }
                                        }
                                    }
                                    Subject::Integer(value) => {
                                        let mut path = path;
                                        let pattern = formed_value(
                                            &mut path.engine,
                                            program,
                                            pattern,
                                            depth + 1,
                                            decisions,
                                        )?;
                                        if let Some(matched) = path.clone().assume((
                                            BinaryOperator::Equal,
                                            value.clone(),
                                            pattern.clone(),
                                        )) {
                                            selected.push(matched);
                                        }
                                        if let Some(path) = path.assume((
                                            BinaryOperator::NotEqual,
                                            value.clone(),
                                            pattern,
                                        )) {
                                            failed.push((path, Subject::Integer(value)));
                                        }
                                    }
                                }
                            }
                        }
                    }
                    if crate::proof_contracts::contract_entailment::struct_trace() {
                        eprintln!(
                            "STRUCT declaration-dispatch arm value={:?} selected={} remaining={}",
                            arm.value,
                            selected.len(),
                            failed.len()
                        );
                    }
                    for mut path in selected {
                        let value = formed_value(
                            &mut path.engine,
                            program,
                            arm.value,
                            depth + 1,
                            decisions,
                        )
                        .or_else(|| {
                            if crate::proof_contracts::contract_entailment::struct_trace() {
                                eprintln!(
                                    "STRUCT declaration-dispatch arm-formation-declined value={:?}",
                                    arm.value
                                );
                            }
                            None
                        })?;
                        let decision = checked_trees::CheckedDeclarationDispatchArm {
                            expression,
                            source_arm,
                        };
                        if !decisions.dispatches.contains(&decision) {
                            decisions.dispatches.push(decision);
                        }
                        let value = path.engine.substituted(&value);
                        engine.retain_operation_definitions(&path.engine)?;
                        values.push(ConditionalValueArm {
                            conditions: path.conditions,
                            value,
                        });
                    }
                    remaining = failed;
                }
                if !remaining.is_empty() {
                    return None;
                }
                engine.conditional_value(values)
            }

            fn condition_paths<'program>(
                mut path: Path<'program>,
                expression: ExpressionHandle,
                depth: usize,
                decisions: &mut ApplicationDecisions,
            ) -> Option<Vec<(bool, Path<'program>)>> {
                if depth >= 128 {
                    return None;
                }
                path.engine.charge_conditional_work()?;
                let program = path.engine.program;
                match expression_table(program).expression(expression) {
                    ExpressionNode::Boolean(value) => Some(vec![(*value, path)]),
                    ExpressionNode::Atomic(atomic) => {
                        condition_paths(path, atomic.value, depth + 1, decisions)
                    }
                    ExpressionNode::Unary(unary) if unary.operator == UnaryOperator::LogicalNot => {
                        Some(
                            condition_paths(path, unary.operand, depth + 1, decisions)?
                                .into_iter()
                                .map(|(value, path)| (!value, path))
                                .collect(),
                        )
                    }
                    ExpressionNode::Binary(binary)
                        if path.engine.selected_binary_meaning(expression, binary) =>
                    {
                        let boolean_relation = matches!(
                            binary.operator,
                            BinaryOperator::Equal | BinaryOperator::NotEqual
                        ) && [binary.left, binary.right]
                            .into_iter()
                            .all(|operand| has_boolean_carrier(&path.engine, operand));
                        if matches!(binary.operator, BinaryOperator::And | BinaryOperator::Or)
                            || boolean_relation
                        {
                            let mut cases = Vec::new();
                            for (left, path) in
                                condition_paths(path, binary.left, depth + 1, decisions)?
                            {
                                if (binary.operator == BinaryOperator::And && !left)
                                    || (binary.operator == BinaryOperator::Or && left)
                                {
                                    cases.push((left, path));
                                } else {
                                    let mut right_cases =
                                        condition_paths(path, binary.right, depth + 1, decisions)?;
                                    for (right, _) in &mut right_cases {
                                        *right = match binary.operator {
                                            BinaryOperator::And | BinaryOperator::Or => *right,
                                            BinaryOperator::Equal => left == *right,
                                            BinaryOperator::NotEqual => left != *right,
                                            _ => return None,
                                        };
                                    }
                                    cases.append(&mut right_cases);
                                }
                            }
                            return Some(cases);
                        }
                        let complement = binary.operator.complement()?;
                        let left = formed_value(
                            &mut path.engine,
                            program,
                            binary.left,
                            depth + 1,
                            decisions,
                        )?;
                        let right = formed_value(
                            &mut path.engine,
                            program,
                            binary.right,
                            depth + 1,
                            decisions,
                        )?;
                        let mut cases = Vec::new();
                        if let Some(selected) =
                            path.clone()
                                .assume((binary.operator, left.clone(), right.clone()))
                        {
                            cases.push((true, selected));
                        }
                        if let Some(selected) = path.assume((complement, left, right)) {
                            cases.push((false, selected));
                        }
                        Some(cases)
                    }
                    _ => {
                        if crate::proof_contracts::contract_entailment::struct_trace() {
                            eprintln!(
                                "STRUCT declaration-dispatch condition-declined expression={expression:?} node={:?}",
                                expression_table(program).expression(expression)
                            );
                        }
                        None
                    }
                }
            }
        }

        #[derive(Default)]
        pub(crate) struct ApplicationDecisions {
            casts: Vec<crate::ExactIntegerCastFact>,
            calls: Vec<checked_trees::CheckedDeclarationCall>,
            dispatches: Vec<checked_trees::CheckedDeclarationDispatchArm>,
        }
        use crate::frozen_program::expression_table;
        use numerics::arithmetic::ArithmeticDomain;
        use typed_trees::expression::{ExpressionHandle, ExpressionNode, UnaryOperator};
        use typed_trees::types::PrimitiveType;

        #[derive(Debug, Clone, PartialEq, Eq)]
        pub struct IntegerApplicationFormation {
            owner: symbols::SymbolHandle,
            body: ExpressionHandle,
            casts: Vec<crate::ExactIntegerCastFact>,
            calls: Vec<checked_trees::CheckedDeclarationCall>,
            dispatches: Vec<checked_trees::CheckedDeclarationDispatchArm>,
        }

        impl IntegerApplicationFormation {
            pub fn owner(&self) -> symbols::SymbolHandle {
                self.owner
            }

            pub fn body(&self) -> ExpressionHandle {
                self.body
            }

            pub fn casts(&self) -> &[crate::ExactIntegerCastFact] {
                &self.casts
            }

            pub fn calls(&self) -> &[checked_trees::CheckedDeclarationCall] {
                &self.calls
            }

            pub fn dispatches(&self) -> &[checked_trees::CheckedDeclarationDispatchArm] {
                &self.dispatches
            }

            pub(crate) fn from_retained(
                owner: symbols::SymbolHandle,
                body: ExpressionHandle,
                casts: Vec<crate::ExactIntegerCastFact>,
                calls: Vec<checked_trees::CheckedDeclarationCall>,
                dispatches: Vec<checked_trees::CheckedDeclarationDispatchArm>,
            ) -> Option<Self> {
                if !owner.is_valid() || !body.is_valid() {
                    return None;
                }
                for cast in &casts {
                    let (source_min, source_max) = cast.source_type.integer_bounds()?;
                    let (target_min, target_max) = cast.target_type.integer_bounds()?;
                    if !cast.expression.is_valid()
                        || cast.minimum > cast.maximum
                        || cast.minimum
                            < super::super::BigInt::from_i128(source_min.max(target_min))
                        || cast.maximum
                            > super::super::BigInt::from_i128(source_max.min(target_max))
                    {
                        return None;
                    }
                }
                if calls.iter().any(|call| {
                    !call.expression.is_valid()
                        || !call.target_machine.is_valid()
                        || !call.target_state.is_valid()
                }) {
                    return None;
                }
                if dispatches
                    .iter()
                    .any(|arm| !arm.expression.is_valid() || !arm.source_arm.is_valid())
                {
                    return None;
                }
                Some(Self {
                    owner,
                    body,
                    casts,
                    calls,
                    dispatches,
                })
            }
        }

        pub(crate) struct FormedIntegerApplication {
            pub value: Polynomial,
            pub formation: Option<IntegerApplicationFormation>,
        }

        impl Engine<'_> {
            pub(crate) fn form_integer_expression(
                &mut self,
                owner: symbols::SymbolHandle,
                body: ExpressionHandle,
            ) -> Option<FormedIntegerApplication> {
                let program = self.program;
                let mut admitted = self.clone();
                admitted.source_owner = owner;
                let anonymous = super::super::proof_integer::anonymous_integer_value(program, body);
                let result_type = if anonymous.is_some() {
                    None
                } else {
                    let reference = admitted.source_result_type(body)?;
                    program
                        .primitive_type_reference(reference)?
                        .integer_bounds()?;
                    Some(reference)
                };
                let mut decisions = ApplicationDecisions::default();
                let value = formed_value(&mut admitted, program, body, 0, &mut decisions)?;
                if result_type.is_some_and(|reference| {
                    !formed_type(&mut admitted, program, reference, &value)
                }) || admitted.requires_unsatisfiable
                {
                    return None;
                }
                let formation = Some(IntegerApplicationFormation {
                    owner,
                    body,
                    casts: decisions.casts,
                    calls: decisions.calls,
                    dispatches: decisions.dispatches,
                });
                *self = admitted;
                Some(FormedIntegerApplication { value, formation })
            }

            pub(crate) fn form_declared_integer_application(
                &mut self,
                measure: symbols::SymbolHandle,
                input: impl Into<IntegerApplicationInput>,
            ) -> Option<FormedIntegerApplication> {
                let program = self.program;
                let declaration = program
                    .measures()
                    .iter()
                    .find(|definition| definition.symbol == measure)?;
                let formal = declaration.parameter.as_ref()?;
                if !formal.symbol.is_valid() || program.symbols.get(formal.symbol).parent != measure
                {
                    return None;
                }
                let [body] = expression_table(program).expression_handles(declaration.body) else {
                    return None;
                };
                let primitive = program.primitive_type_reference(declaration.return_type)?;
                let (minimum, maximum) = primitive.integer_bounds()?;
                let input = input.into();
                if super::super::struct_trace() {
                    eprintln!("STRUCT declaration-application measure={measure:?} input={input:?}");
                }
                let shape =
                    super::super::ranking_range::declared_input_shape(program, declaration)?;
                let (arguments, reads) = match &input {
                    IntegerApplicationInput::Scalar(value) => {
                        program
                            .primitive_type_reference(formal.type_reference)?
                            .integer_bounds()?;
                        (vec![(formal.symbol, value.clone())], Vec::new())
                    }
                    IntegerApplicationInput::Record {
                        type_reference,
                        reads,
                        ..
                    } => {
                        if program
                            .primitive_type_reference(formal.type_reference)
                            .is_some()
                            || !super::super::ranking_range::declared_input_type_matches(
                                program,
                                *type_reference,
                                formal.type_reference,
                            )
                        {
                            return None;
                        }
                        if reads.len() != shape.reads.len()
                            || shape.reads.iter().any(|read| {
                                reads.iter().filter(|(bound, _)| *bound == *read).count() != 1
                            })
                        {
                            return None;
                        }
                        (Vec::new(), reads.clone())
                    }
                };
                let mut admitted = self.clone();
                let mut decisions = ApplicationDecisions::default();
                let value = admitted.with_formal_arguments(measure, &arguments, |engine| {
                    engine.formal_read_arguments = reads;
                    if let IntegerApplicationInput::Record {
                        snapshot: Some(snapshot),
                        ..
                    } = &input
                    {
                        engine.owned_arguments.push((
                            crate::ScopedArithmeticBinder::Symbol(formal.symbol),
                            snapshot.clone(),
                        ));
                    }
                    match &input {
                        IntegerApplicationInput::Scalar(value) => {
                            if !formed_type(engine, program, formal.type_reference, value) {
                                return None;
                            }
                        }
                        IntegerApplicationInput::Record { .. } => {
                            for read in &shape.reads {
                                let value = engine.declared_read_value(read)?;
                                if !formed_type(engine, program, read.type_reference, &value) {
                                    return None;
                                }
                            }
                        }
                    }
                    if !crate::value_custody::literals::has_anonymous_numeric_results(
                        program, *body,
                    ) {
                        let actual_type = engine.source_result_type(*body)?;
                        if program.primitive_type_reference(actual_type) != Some(primitive)
                            || program.arithmetic_domain_for_type_reference(actual_type)
                                != program
                                    .arithmetic_domain_for_type_reference(declaration.return_type)
                        {
                            return None;
                        }
                    }
                    let value = formed_value(engine, program, *body, 0, &mut decisions)?;
                    formed_type(engine, program, declaration.return_type, &value).then_some(value)
                })?;
                for bound in [
                    (value.clone(), super::super::BigInt::from_i128(minimum)),
                    (
                        value.neg(),
                        super::super::BigInt::from_i128(maximum).negate(),
                    ),
                ] {
                    if !admitted.bounds.contains(&bound) {
                        admitted.bounds.push(bound);
                    }
                }
                admitted.refresh_difference_bounds();
                let formation =
                    (!admitted.requires_unsatisfiable).then_some(IntegerApplicationFormation {
                        owner: measure,
                        body: *body,
                        casts: decisions.casts,
                        calls: decisions.calls,
                        dispatches: decisions.dispatches,
                    });
                *self = admitted;
                Some(FormedIntegerApplication { value, formation })
            }
        }

        fn formed_value(
            engine: &mut Engine<'_>,
            program: &dyn crate::CheckingInput,
            expression: ExpressionHandle,
            depth: usize,
            decisions: &mut ApplicationDecisions,
        ) -> Option<Polynomial> {
            if depth >= 128 {
                return None;
            }
            if let Some(value) = engine.formal_coordinate_value(expression) {
                return Some(value);
            }
            if matches!(
                expression_table(program).expression(expression),
                ExpressionNode::Member(_) | ExpressionNode::Indexed(_)
            ) && let Some(value) = engine.strict_occurrence_value(expression)
            {
                return Some(value);
            }
            if super::super::proof_integer::anonymous_integer_value(program, expression).is_some() {
                return engine.normalize(expression);
            }
            match expression_table(program).expression(expression) {
                ExpressionNode::Atomic(atomic) => {
                    formed_value(engine, program, atomic.value, depth + 1, decisions)
                }
                ExpressionNode::Unary(unary) if unary.operator == UnaryOperator::BitwiseNot => {
                    let operand =
                        formed_value(engine, program, unary.operand, depth + 1, decisions)?;
                    let reference = engine.source_result_type(expression)?;
                    let primitive = program.primitive_type_reference(reference)?;
                    engine.admit_integer_complement(primitive, &operand)
                }
                ExpressionNode::Cast(cast)
                    if !cast.form.is_recast() && cast.semantic_domain.is_empty() =>
                {
                    let value = formed_value(engine, program, cast.value, depth + 1, decisions)?;
                    if !formed_type(engine, program, cast.target_type, &value) {
                        return None;
                    }
                    let target = program.primitive_type_reference(cast.target_type)?;
                    let source = if super::super::proof_integer::anonymous_integer_value(
                        program, cast.value,
                    )
                    .is_some()
                    {
                        Some(target)
                    } else {
                        engine
                            .source_result_type(cast.value)
                            .and_then(|reference| program.primitive_type_reference(reference))
                    };
                    if let Some(source) = source
                        && let (Some((source_min, source_max)), Some((target_min, target_max))) =
                            (source.integer_bounds(), target.integer_bounds())
                    {
                        let fact = crate::ExactIntegerCastFact {
                            expression,
                            source_type: source,
                            target_type: target,
                            minimum: super::super::BigInt::from_i128(source_min.max(target_min)),
                            maximum: super::super::BigInt::from_i128(source_max.min(target_max)),
                        };
                        if !decisions.casts.contains(&fact) {
                            decisions.casts.push(fact);
                        }
                    }
                    Some(value)
                }
                ExpressionNode::Match(dispatch) => {
                    dispatch::form(engine, expression, dispatch, depth, decisions)
                }
                ExpressionNode::Call(_) => {
                    calls::form(engine, program, expression, depth, decisions)
                }
                ExpressionNode::Binary(binary) => {
                    if !engine.selected_binary_meaning(expression, binary) {
                        return None;
                    }
                    let left = formed_value(engine, program, binary.left, depth + 1, decisions)?;
                    let right = formed_value(engine, program, binary.right, depth + 1, decisions)?;
                    let references = [binary.left, binary.right]
                        .map(|operand| engine.source_result_type(operand));
                    let primitives = references.map(|reference| {
                        reference.and_then(|r| program.primitive_type_reference(r))
                    });
                    let left_primitive = primitives[0].or(primitives[1])?;
                    let right_primitive = primitives[1].unwrap_or(left_primitive);
                    let policies = references.map(|reference| {
                        reference.map(|r| program.arithmetic_domain_for_type_reference(r))
                    });
                    let left_policy = policies[0]
                        .or(policies[1])
                        .unwrap_or(ArithmeticDomain::Exact);
                    let right_policy = policies[1].unwrap_or(left_policy);
                    engine.admit_selected_integer_operation(
                        binary.operator,
                        [
                            (left_primitive, left_policy),
                            (right_primitive, right_policy),
                        ],
                        &left,
                        &right,
                        None,
                    )
                }
                _ => {
                    let mut has_children = false;
                    crate::queries::expression_traversal::executable_children(
                        program,
                        expression_table(program).expression(expression),
                        |_| has_children = true,
                    );
                    if has_children {
                        return None;
                    }
                    engine.normalize(expression)
                }
            }
        }

        fn formed_type(
            engine: &mut Engine<'_>,
            program: &dyn crate::CheckingInput,
            mut reference: typed_trees::types::TypeReferenceHandle,
            value: &Polynomial,
        ) -> bool {
            use typed_trees::types::{TypeConstraintNode, TypeReferenceNode};
            while let TypeReferenceNode::Constrained {
                base_type,
                constraints,
            } = program.type_reference_table.type_reference(reference)
            {
                for constraint in program.type_reference_table.constraints(*constraints) {
                    if matches!(constraint, TypeConstraintNode::ArithmeticDomain(_)) {
                        continue;
                    }
                    return false;
                }
                reference = *base_type;
            }
            let TypeReferenceNode::Named { symbol, .. } =
                program.type_reference_table.type_reference(reference)
            else {
                return false;
            };
            program
                .symbols
                .builtin_type_atom(*symbol)
                .and_then(PrimitiveType::from_builtin_atom)
                .is_some_and(|primitive| engine.integer_value_lands(primitive, value))
        }
    }
    pub(crate) mod application_inputs {
        use super::Polynomial;
        use typed_trees::types::TypeReferenceHandle;

        #[derive(Debug, Clone, PartialEq, Eq)]
        pub(crate) enum IntegerApplicationInput {
            Scalar(Polynomial),
            Record {
                type_reference: TypeReferenceHandle,
                snapshot: Option<crate::CapturedOwnedSnapshot>,
                reads: Vec<(crate::DeclaredInputRead, Polynomial)>,
            },
        }

        impl From<Polynomial> for IntegerApplicationInput {
            fn from(value: Polynomial) -> Self {
                Self::Scalar(value)
            }
        }

        impl From<&Polynomial> for IntegerApplicationInput {
            fn from(value: &Polynomial) -> Self {
                Self::Scalar(value.clone())
            }
        }

        impl From<&IntegerApplicationInput> for IntegerApplicationInput {
            fn from(value: &IntegerApplicationInput) -> Self {
                value.clone()
            }
        }

        impl IntegerApplicationInput {
            pub(crate) fn scoped_bindings(
                &self,
                formal: symbols::SymbolHandle,
                mut scalar: impl FnMut(&Polynomial) -> Option<crate::ScopedArithmeticValue>,
            ) -> Option<Vec<crate::ScopedArithmeticBinding>> {
                use crate::{
                    ScopedArithmeticBinder as Binder, ScopedArithmeticBinding as Binding,
                    ScopedArithmeticValue as Value,
                };
                match self {
                    Self::Scalar(value) => Some(vec![Binding {
                        binder: Binder::Symbol(formal),
                        value: scalar(value)?,
                    }]),
                    Self::Record {
                        snapshot, reads, ..
                    } => {
                        let mut bindings = vec![Binding {
                            binder: Binder::Symbol(formal),
                            value: Value::OwnedSnapshot(snapshot.clone()?),
                        }];
                        for (read, value) in reads {
                            let mut read = read.clone();
                            read.coordinate.parameter = formal;
                            bindings.push(Binding {
                                binder: Binder::DeclaredRead(read),
                                value: scalar(value)?,
                            });
                        }
                        Some(bindings)
                    }
                }
            }
            pub(crate) fn captured(
                engine: &super::Engine<'_>,
                measure: symbols::SymbolHandle,
                input_type: TypeReferenceHandle,
            ) -> Option<Self> {
                let declaration = engine
                    .program
                    .measures()
                    .iter()
                    .find(|declaration| declaration.symbol == measure)?;
                let shape =
                    super::super::ranking_range::declared_input_shape(engine.program, declaration)?;
                if !super::super::ranking_range::declared_input_type_matches(
                    engine.program,
                    input_type,
                    shape.type_reference,
                ) {
                    return None;
                }
                if engine
                    .program
                    .primitive_type_reference(shape.type_reference)
                    .is_some()
                {
                    return Some(Self::Scalar(engine.strict_symbol_value(shape.parameter)?));
                }
                let reads = shape
                    .reads
                    .iter()
                    .map(|read| Some((read.clone(), engine.declared_read_value(read)?)))
                    .collect::<Option<Vec<_>>>()?;
                Some(Self::Record {
                    type_reference: input_type,
                    snapshot: engine
                        .owned_arguments
                        .iter()
                        .find_map(|(binder, snapshot)| {
                            (*binder == crate::ScopedArithmeticBinder::Symbol(shape.parameter))
                                .then(|| snapshot.clone())
                        }),
                    reads,
                })
            }

            pub(crate) fn visit_values(&self, mut visit: impl FnMut(&Polynomial)) {
                match self {
                    Self::Scalar(value) => visit(value),
                    Self::Record { reads, .. } => reads.iter().for_each(|(_, value)| visit(value)),
                }
            }

            pub(crate) fn mapped(
                &self,
                mut map: impl FnMut(&Polynomial) -> Option<Polynomial>,
            ) -> Option<Self> {
                Some(match self {
                    Self::Scalar(value) => Self::Scalar(map(value)?),
                    Self::Record {
                        type_reference,
                        snapshot,
                        reads,
                    } => Self::Record {
                        type_reference: *type_reference,
                        snapshot: snapshot.clone(),
                        reads: reads
                            .iter()
                            .map(|(source, value)| Some((source.clone(), map(value)?)))
                            .collect::<Option<Vec<_>>>()?,
                    },
                })
            }
        }

        impl super::Engine<'_> {
            pub(crate) fn call_input_type(
                &self,
                expression: typed_trees::expression::ExpressionHandle,
                required: TypeReferenceHandle,
            ) -> Option<TypeReferenceHandle> {
                use language_semantics::ReferenceAccess;
                use typed_trees::expression::ExpressionNode;

                let borrowed = match self.program.expression_table.expression(expression) {
                    ExpressionNode::Borrow(borrow) => Some(borrow.access),
                    _ => None,
                };
                match crate::reference_shell(self.program, required) {
                    Some(shell) => {
                        if shell.access != ReferenceAccess::Shared
                            || !matches!(
                                self.program.type_reference_table.type_reference(required),
                                typed_trees::types::TypeReferenceNode::Reference { .. }
                            )
                        {
                            return None;
                        }
                        let supplied = borrowed.or_else(|| {
                            crate::reference_shell(
                                self.program,
                                self.source_result_type(expression)?,
                            )
                            .map(|shell| shell.access)
                        })?;
                        (supplied == ReferenceAccess::Shared).then_some(shell.referee)
                    }
                    None => borrowed.is_none().then_some(required),
                }
            }

            pub(crate) fn captured_record_call_input(
                &self,
                expression: typed_trees::expression::ExpressionHandle,
                parameters: &[typed_trees::signature::StateParameter],
                arguments: &[typed_trees::expression::ExpressionHandle],
            ) -> Option<IntegerApplicationInput> {
                let observed = match self.program.expression_table.expression(expression) {
                    typed_trees::expression::ExpressionNode::Borrow(borrow)
                        if borrow.access == language_semantics::ReferenceAccess::Shared =>
                    {
                        borrow.target
                    }
                    typed_trees::expression::ExpressionNode::Borrow(_) => return None,
                    _ => expression,
                };
                let place = crate::canonical_place_from_expression(self.program, observed)?;
                let root = place.root.as_symbol()?;
                let (_, snapshot) = self
                    .owned_arguments
                    .iter()
                    .find(|(binder, _)| *binder == crate::ScopedArithmeticBinder::Symbol(root))?;
                let snapshot = snapshot.project(self.program, &place.segments)?;
                let actual_type =
                    crate::value_custody::expression_types::readable_observation_type_reference(
                        self.program,
                        self.source_result_type(observed)?,
                    )?;
                if !super::super::ranking_range::declared_input_type_matches(
                    self.program,
                    snapshot.actual_type(),
                    actual_type,
                ) {
                    return None;
                }
                let reads = self
                    .formal_read_arguments
                    .iter()
                    .filter_map(|(read, value)| {
                        (read.coordinate.parameter == root).then_some(())?;
                        let path = read
                            .coordinate
                            .path
                            .strip_prefix(place.segments.as_slice())?;
                        (!read
                            .coordinate
                            .path
                            .iter()
                            .any(|step| matches!(step, facts::PlaceSegment::Index { .. }))
                            || parameters.iter().zip(arguments).all(|(formal, actual)| {
                                read.selector_arguments.iter().any(|(bound, supplied)| {
                                    *bound == formal.symbol && supplied == actual
                                })
                            }))
                        .then_some(())?;
                        let mut read = read.clone();
                        read.coordinate.path = path.to_vec();
                        Some((read, value.clone()))
                    })
                    .collect();
                Some(IntegerApplicationInput::Record {
                    type_reference: actual_type,
                    snapshot: Some(snapshot),
                    reads,
                })
            }
        }
    }
    pub use application_formation::IntegerApplicationFormation;
    pub(crate) use application_inputs::IntegerApplicationInput;
    #[cfg(test)]
    pub(crate) mod denotation_tests {
        use super::{BigInt, Engine, Polynomial};
        use crate::proof_contracts::contract_entailment::inductive_judgment::apply_argument_map;
        use std::collections::BTreeMap;

        #[test]
        fn opaque_rank_dependencies_survive_two_symbolic_arrivals() {
            let program = typed_trees::TypedTrees::default();
            let constant = |value| Polynomial::constant(BigInt::from_i64(value));
            let atom = |name: &str| Polynomial::atom(name.to_owned());
            let mut source = Engine::for_explicit_bindings(&program);
            let remainder = source
                .integer_remainder(atom("input"), atom("divisor"), true)
                .unwrap();
            let rank = source.integer_quotient(remainder, constant(2)).unwrap();
            let captured = source.capture_integer_denotation(&rank).unwrap();

            let mut arrival = Engine::for_explicit_bindings(&program);
            let first = arrival
                .instantiate_integer_denotation(
                    &captured,
                    &BTreeMap::from([
                        ("input".to_owned(), atom("first-input")),
                        ("divisor".to_owned(), atom("first-divisor")),
                    ]),
                )
                .unwrap();
            let mut arguments = BTreeMap::from([
                ("first-input".to_owned(), atom("second-input")),
                ("first-divisor".to_owned(), atom("second-divisor")),
            ]);
            arrival.extend_argument_map_over_opaque_terms(&mut arguments);
            let second = apply_argument_map(&first, &arguments).unwrap();
            let saved = arrival.capture_integer_denotation(&second).unwrap();
            assert_eq!(saved.leaf_atoms(), &["second-divisor", "second-input"]);

            for (input, divisor, expected) in [
                (17, 5, 1),
                (-17, 5, -1),
                (17, -5, 1),
                (-17, -5, -1),
                (35, 6, 2),
            ] {
                let mut replay = Engine::for_explicit_bindings(&program);
                let value = replay
                    .instantiate_integer_denotation(
                        &saved,
                        &BTreeMap::from([
                            ("second-input".to_owned(), constant(input)),
                            ("second-divisor".to_owned(), constant(divisor)),
                        ]),
                    )
                    .unwrap();
                let difference = value.sub(&constant(expected));
                assert!(replay.prove_at_least(&difference, &BigInt::zero()));
                assert!(replay.prove_at_least(&difference.neg(), &BigInt::zero()));
            }
            let mut incomplete = Engine::for_explicit_bindings(&program);
            assert!(
                incomplete
                    .instantiate_integer_denotation(
                        &saved,
                        &BTreeMap::from([("second-input".to_owned(), constant(17))]),
                    )
                    .is_none()
            );
        }
    }
    pub(crate) mod denotations {
        use super::super::inductive_judgment::apply_argument_map;
        use super::{Engine, OpaqueTerm, Polynomial};
        use std::collections::{BTreeMap, BTreeSet};

        #[derive(Debug, Clone, PartialEq, Eq)]
        pub struct IntegerDenotation {
            value: Polynomial,
            operations: Vec<(String, OpaqueTerm)>,
            leaves: Vec<String>,
        }

        impl IntegerDenotation {
            pub(crate) fn leaf_atoms(&self) -> &[String] {
                &self.leaves
            }
        }

        impl OpaqueTerm {
            pub(crate) fn visit_operands(&self, mut visit: impl FnMut(&Polynomial)) {
                match self {
                    Self::DeclarationApplication { input, .. } => input.visit_values(visit),
                    Self::Conditional { arms } => {
                        arms.iter().for_each(|arm| arm.visit_operands(&mut visit))
                    }
                    Self::Call { arguments, .. } => arguments
                        .iter()
                        .for_each(|input| input.visit_values(&mut visit)),
                    Self::IntegerPolicy { value, .. } => visit(value),
                    Self::Remainder {
                        operand, modulus, ..
                    } => {
                        visit(operand);
                        visit(modulus);
                    }
                    Self::Quotient { dividend, divisor } => {
                        visit(dividend);
                        visit(divisor);
                    }
                    Self::ShiftLeft { value, count, .. }
                    | Self::ShiftRight { value, count, .. } => {
                        visit(value);
                        visit(count);
                    }
                    Self::Bitwise { left, right, .. } => {
                        visit(left);
                        visit(right);
                    }
                }
            }
        }

        impl Engine<'_> {
            pub(crate) fn capture_integer_denotation(
                &self,
                value: &Polynomial,
            ) -> Option<IntegerDenotation> {
                let value = self.substituted(value);
                let mut required: BTreeSet<String> = value
                    .terms
                    .keys()
                    .flat_map(|monomial| monomial.keys().cloned())
                    .collect();
                let mut operations = Vec::new();
                for (atom, operation) in self.opaque_terms.iter().rev() {
                    if !required.remove(atom) {
                        continue;
                    }
                    operation.visit_operands(|operand| {
                        required.extend(
                            operand
                                .terms
                                .keys()
                                .flat_map(|monomial| monomial.keys().cloned()),
                        );
                    });
                    operations.push((atom.clone(), operation.clone()));
                }
                if required
                    .iter()
                    .any(|atom| self.opaque_terms.iter().any(|(name, _)| name == atom))
                {
                    return None;
                }
                operations.reverse();
                Some(IntegerDenotation {
                    value,
                    operations,
                    leaves: required.into_iter().collect(),
                })
            }

            pub(crate) fn instantiate_integer_denotation(
                &mut self,
                denotation: &IntegerDenotation,
                leaves: &BTreeMap<String, Polynomial>,
            ) -> Option<Polynomial> {
                let mut substitutions = leaves.clone();
                for (atom, operation) in &denotation.operations {
                    let value = self.mapped_opaque_value(operation, &substitutions)?;
                    substitutions.insert(atom.clone(), value);
                }
                apply_argument_map(&denotation.value, &substitutions)
            }

            pub(crate) fn extend_argument_map_over_opaque_terms(
                &mut self,
                substitutions: &mut BTreeMap<String, Polynomial>,
            ) {
                for index in 0..self.opaque_terms.len() {
                    let (atom, operation) = self.opaque_terms[index].clone();
                    if let Some(value) = self.mapped_opaque_value(&operation, substitutions) {
                        substitutions.insert(atom, value);
                    }
                }
            }

            fn mapped_opaque_value(
                &mut self,
                operation: &OpaqueTerm,
                substitutions: &BTreeMap<String, Polynomial>,
            ) -> Option<Polynomial> {
                let mapped = |value: &Polynomial| apply_argument_map(value, substitutions);
                match operation {
                    OpaqueTerm::DeclarationApplication { measure, input } => {
                        self.declared_application_value(*measure, input.mapped(mapped)?)
                    }
                    OpaqueTerm::Conditional { arms } => self.conditional_value(
                        arms.iter()
                            .map(|arm| arm.mapped(mapped))
                            .collect::<Option<Vec<_>>>()?,
                    ),
                    OpaqueTerm::Call {
                        owner,
                        expression,
                        target,
                        arguments,
                    } => self.selected_call_value(
                        *owner,
                        *expression,
                        *target,
                        arguments
                            .iter()
                            .map(|input| input.mapped(&mapped))
                            .collect::<Option<Vec<_>>>()?,
                    ),
                    OpaqueTerm::IntegerPolicy {
                        primitive,
                        domain,
                        value,
                    } => self.integer_policy_value(*primitive, *domain, mapped(value)?),
                    OpaqueTerm::Remainder {
                        operand,
                        modulus,
                        tight_interval,
                    } => {
                        self.integer_remainder(mapped(operand)?, mapped(modulus)?, *tight_interval)
                    }
                    OpaqueTerm::Quotient { dividend, divisor } => {
                        self.integer_quotient(mapped(dividend)?, mapped(divisor)?)
                    }
                    OpaqueTerm::ShiftLeft {
                        value,
                        count,
                        count_bits,
                    } => self.integer_shift_left(mapped(value)?, mapped(count)?, *count_bits),
                    OpaqueTerm::ShiftRight {
                        value,
                        count,
                        count_bits,
                    } => self.integer_shift_right(mapped(value)?, mapped(count)?, *count_bits),
                    OpaqueTerm::Bitwise {
                        operator,
                        left,
                        right,
                        bits,
                        signed,
                    } => self.integer_bitwise(
                        *operator,
                        mapped(left)?,
                        mapped(right)?,
                        *bits,
                        *signed,
                    ),
                }
            }
        }
    }
    #[cfg(test)]
    pub(crate) mod difference_constraint_tests {
        use super::{BigInt, BinaryOperator, Engine, Polynomial};

        #[test]
        fn difference_constraints_match_bounded_integer_models() {
            let program = typed_trees::TypedTrees::default();
            let x = Polynomial::atom("x".to_owned());
            let y = Polynomial::atom("y".to_owned());
            let constant = |value| Polynomial::constant(BigInt::from_i64(value));
            let polynomial = |left, right| {
                x.checked_mul(&constant(left))
                    .unwrap()
                    .add(&y.checked_mul(&constant(right)).unwrap())
            };
            let clauses = [(1, 0), (-1, 0), (0, 1), (0, -1), (1, -1), (-1, 1)]
                .into_iter()
                .flat_map(|(left, right)| [-1, 0, 1, 3].map(|minimum| (left, right, minimum)))
                .collect::<Vec<_>>();
            for first in &clauses {
                for second in &clauses {
                    let mut comparisons = vec![
                        (BinaryOperator::GreaterOrEqual, x.clone(), constant(-2)),
                        (BinaryOperator::LessOrEqual, x.clone(), constant(2)),
                        (BinaryOperator::GreaterOrEqual, y.clone(), constant(-2)),
                        (BinaryOperator::LessOrEqual, y.clone(), constant(2)),
                    ];
                    for &(left, right, minimum) in [first, second] {
                        comparisons.push((
                            BinaryOperator::GreaterOrEqual,
                            polynomial(left, right),
                            constant(minimum),
                        ));
                    }
                    let has_model = (-2..=2).any(|x| {
                        (-2..=2).any(|y| {
                            [first, second]
                                .iter()
                                .all(|&&(left, right, minimum)| left * x + right * y >= minimum)
                        })
                    });
                    let mut engine = Engine::for_explicit_bindings(&program);
                    assert_eq!(
                        engine.integer_comparisons_unsatisfiable(comparisons),
                        !has_model,
                        "{first:?}, {second:?}",
                    );
                }
            }
        }

        #[test]
        fn polynomial_and_opaque_bounds_keep_general_contradiction_search() {
            let program = typed_trees::TypedTrees::default();
            let constant = |value| Polynomial::constant(BigInt::from_i64(value));
            let x = Polynomial::atom("x".to_owned());
            let mut scaled = Engine::for_explicit_bindings(&program);
            assert!(scaled.integer_comparisons_unsatisfiable(vec![
                (
                    BinaryOperator::GreaterOrEqual,
                    x.checked_mul(&constant(2)).unwrap(),
                    constant(6),
                ),
                (BinaryOperator::LessOrEqual, x, constant(2)),
            ]));

            let mut opaque = Engine::for_explicit_bindings(&program);
            opaque.opaque_terms.push((
                "quotient".to_owned(),
                super::OpaqueTerm::Quotient {
                    dividend: constant(10),
                    divisor: constant(2),
                },
            ));
            assert!(opaque.integer_comparisons_unsatisfiable(vec![(
                BinaryOperator::LessOrEqual,
                Polynomial::atom("quotient".to_owned()),
                constant(4),
            )]));
            // Preparation changes query work, never the visible arithmetic premises.
            let x = Polynomial::atom("x".to_owned());
            let square = x.checked_mul(&x).unwrap();
            let mut engine = Engine::for_explicit_bindings(&program);
            engine.bounds = vec![
                (x.clone(), BigInt::zero()),
                (square.clone(), BigInt::from_i64(3)),
            ];
            engine.refresh_difference_bounds();
            let cases = [
                (constant(2), 1, true),
                (x, 0, true),
                (square.clone(), 2, true),
                (square, 4, false),
                (Polynomial::atom("unrelated".to_owned()), 1, false),
            ];
            let mut deferred = super::LowerBoundQueries::direct(&engine);
            for (position, (goal, minimum, expected)) in cases.iter().enumerate() {
                let minimum = BigInt::from_i64(*minimum);
                let direct =
                    super::LowerBoundQueries::direct(&engine).prove_at_least(goal, &minimum);
                let prepared = engine.lower_bound_queries().prove_at_least(goal, &minimum);
                assert_eq!(direct, *expected);
                assert_eq!(prepared, direct);
                assert_eq!(
                    deferred.prove_with_deferred_preparation(goal, &minimum),
                    direct
                );
                assert_eq!(deferred.prepared_exact_bounds().is_empty(), position < 2);
            }

            let mut conditional = Engine::for_explicit_bindings(&program);
            let selected = conditional
                .conditional_value(vec![
                    super::ConditionalValueArm {
                        conditions: vec![],
                        value: constant(0),
                    },
                    super::ConditionalValueArm {
                        conditions: vec![],
                        value: constant(2),
                    },
                ])
                .unwrap();
            // Each mode gets its own allowance: cloning an engine intentionally shares
            // the original counter, so using that shared counter would hide double work.
            let agreement = |engine: &Engine<'_>, goal: &Polynomial, minimum, allowance| {
                let mut outcomes = Vec::new();
                for mode in 0..3 {
                    let mut candidate = engine.clone();
                    candidate.conditional_work_remaining =
                        std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(allowance));
                    let minimum = BigInt::from_i64(minimum);
                    let answer = match mode {
                        0 => super::LowerBoundQueries::direct(&candidate)
                            .prove_at_least(goal, &minimum),
                        1 => candidate
                            .lower_bound_queries()
                            .prove_at_least(goal, &minimum),
                        _ => super::LowerBoundQueries::direct(&candidate)
                            .prove_with_deferred_preparation(goal, &minimum),
                    };
                    outcomes.push((
                        answer,
                        candidate
                            .conditional_work_remaining
                            .load(std::sync::atomic::Ordering::Relaxed),
                    ));
                }
                assert!(outcomes.iter().all(|outcome| *outcome == outcomes[0]));
                let mut reference = engine.clone();
                reference.conditional_work_remaining =
                    std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(allowance));
                if let Some(answer) =
                    reference.conditional_lower_bound(goal, &BigInt::from_i64(minimum))
                {
                    assert_eq!(
                        outcomes[0],
                        (
                            answer,
                            reference
                                .conditional_work_remaining
                                .load(std::sync::atomic::Ordering::Relaxed,)
                        )
                    );
                } else {
                    assert_eq!(outcomes[0].1, allowance);
                }
                outcomes[0]
            };
            assert!(agreement(&conditional, &selected, 0, 1000).0);
            assert!(!agreement(&conditional, &selected, 1, 1000).0);
            assert!(
                !agreement(
                    &conditional,
                    &Polynomial::atom("unrelated".to_owned()),
                    1,
                    1000
                )
                .0
            );
            // Exhausted conditional work is definitive false, even when a matrix bound
            // alone would prove the goal. It must not turn into an unresolved prefix.
            conditional
                .bounds
                .push((selected.clone(), BigInt::from_i64(1)));
            conditional.refresh_difference_bounds();
            let (atom, _, _) = selected.as_single_atom().unwrap();
            assert_eq!(
                conditional.matrix_bound(&atom, super::ZERO_ATOM),
                Some(BigInt::from_i64(1))
            );
            assert_eq!(agreement(&conditional, &selected, 1, 0), (false, 0));
        }
    }
    pub(crate) mod difference_matrix {
        use super::super::BigInt;
        use super::{Engine, Polynomial, SUBSTITUTION_ROUNDS, ZERO_ATOM};
        use crate::proof_contracts::arithmetic_domains::BigIntInterval as Interval;

        pub(crate) use crate::proof_contracts::arithmetic_domains::DifferenceBounds;

        impl<'program> Engine<'program> {
            pub(crate) fn proves_nonzero(&self, polynomial: &Polynomial) -> bool {
                let one = BigInt::from_i64(1);
                self.is_known_nonzero(polynomial)
                    || self.prove_at_least(polynomial, &one)
                    || self.prove_at_least(&polynomial.neg(), &one)
            }

            pub(crate) fn is_known_nonzero(&self, difference: &Polynomial) -> bool {
                let opposite = difference.neg();
                self.nonzero_differences.iter().any(|known| {
                    let known = self.substituted(known);
                    known == *difference || known == opposite
                })
            }

            pub(crate) fn prove_at_least(&self, polynomial: &Polynomial, bound: &BigInt) -> bool {
                super::LowerBoundQueries::direct(self).prove_at_least(polynomial, bound)
            }

            pub(crate) fn bounds_are_inconsistent(&self) -> bool {
                let queries = self.lower_bound_queries();
                let exact = queries.prepared_exact_bounds();
                for (bound_position, (polynomial, bound)) in exact.iter().enumerate() {
                    let complement = polynomial.neg();
                    let complement_bound = BigInt::from_i64(1).sub(bound);
                    if queries.prove_base_lower_bound(&complement, &complement_bound) {
                        return true;
                    }
                    for (stored_position, (stored, stored_bound)) in exact.iter().enumerate() {
                        if (stored_position >= bound_position
                            && queries.prove_base_lower_bound(
                                &complement.sub(stored),
                                &complement_bound.sub(stored_bound),
                            ))
                            || queries.prove_scaled_lower_bound(
                                &complement,
                                &complement_bound,
                                stored,
                                stored_bound,
                            )
                        {
                            return true;
                        }
                    }
                }
                false
            }

            pub(crate) fn polynomial_interval(&self, polynomial: &Polynomial) -> Interval {
                super::LowerBoundQueries::direct(self).polynomial_interval(polynomial)
            }

            pub(crate) fn atom_interval(&self, atom: &str) -> Interval {
                if let Some(interval) = self.arithmetic_intervals.get(atom) {
                    return interval.clone();
                }
                let mut low = self.matrix_bound(atom, ZERO_ATOM);
                if self
                    .unsigned_atoms
                    .iter()
                    .any(|candidate| candidate == atom)
                {
                    low = Some(low.map_or_else(BigInt::zero, |bound| bound.max(BigInt::zero())));
                }
                Interval {
                    low,
                    high: self
                        .matrix_bound(ZERO_ATOM, atom)
                        .map(|bound| bound.negate()),
                }
            }

            pub(crate) fn matrix_bound(&self, from: &str, to: &str) -> Option<BigInt> {
                if from == to {
                    return Some(BigInt::zero());
                }
                self.matrix_bound_indices(self.matrix.position(from)?, self.matrix.position(to)?)
            }

            fn matrix_bound_indices(&self, from: usize, to: usize) -> Option<BigInt> {
                self.matrix.bound_indices(from, to, ZERO_ATOM)
            }

            pub(crate) fn refresh_difference_bounds(&mut self) {
                if self.seed_matrix() || self.requires_unsatisfiable {
                    self.close_matrix();
                }
            }

            fn difference_seeds(&self) -> Vec<(String, String, BigInt)> {
                let mut seeds = Vec::new();
                for atom in &self.unsigned_atoms {
                    seeds.push((atom.clone(), ZERO_ATOM.to_owned(), BigInt::zero()));
                }
                for (atom, interval) in &self.arithmetic_intervals {
                    if let Some(low) = &interval.low {
                        seeds.push((atom.clone(), ZERO_ATOM.to_owned(), low.clone()));
                    }
                    if let Some(high) = &interval.high {
                        seeds.push((ZERO_ATOM.to_owned(), atom.clone(), high.negate()));
                    }
                }
                for (polynomial, bound) in &self.bounds {
                    if let Some((positive, negative, constant)) = polynomial.as_atom_difference() {
                        seeds.push((positive, negative, bound.sub(&constant)));
                    }
                    if let Some((atom, sign, constant)) = polynomial.as_single_atom() {
                        let edge = bound.sub(&constant);
                        if sign == 1 {
                            seeds.push((atom, ZERO_ATOM.to_owned(), edge));
                        } else {
                            seeds.push((ZERO_ATOM.to_owned(), atom, edge));
                        }
                    }
                }
                seeds
            }

            fn seed_matrix(&mut self) -> bool {
                let mut changed = false;
                for (from, to, bound) in self.difference_seeds() {
                    changed |= self.matrix.record(&from, &to, bound);
                }
                changed
            }

            pub(crate) fn close_matrix(&mut self) {
                self.requires_unsatisfiable |= self.matrix.close(ZERO_ATOM);
            }

            pub(crate) fn harvest_substitution(&mut self, left: &Polynomial, right: &Polynomial) {
                let left = self.substituted(left);
                let right = self.substituted(right);
                for (candidate, replacement) in [(&left, &right), (&right, &left)] {
                    if let Some((atom, 1, constant)) = candidate.as_single_atom()
                        && constant.is_zero()
                    {
                        let occurs = replacement
                            .terms
                            .keys()
                            .any(|monomial| monomial.contains_key(&atom));
                        if !occurs && !self.substitutions.contains_key(&atom) {
                            self.substitutions.insert(atom, replacement.clone());
                            return;
                        }
                    }
                }
            }

            pub(crate) fn substituted(&self, polynomial: &Polynomial) -> Polynomial {
                let mut current = polynomial.clone();
                for _ in 0..SUBSTITUTION_ROUNDS {
                    let mut changed = false;
                    let mut next = Polynomial::default();
                    let mut overflowed = false;
                    for (monomial, coefficient) in &current.terms {
                        let mut piece = Polynomial::constant(coefficient.clone());
                        for (atom, power) in monomial {
                            let base = match self.substitutions.get(atom) {
                                Some(replacement) => {
                                    changed = true;
                                    replacement.clone()
                                }
                                None => Polynomial::atom(atom.clone()),
                            };
                            for _ in 0..*power {
                                match piece.checked_mul(&base) {
                                    Some(product) => piece = product,
                                    None => {
                                        overflowed = true;
                                        break;
                                    }
                                }
                            }
                            if overflowed {
                                break;
                            }
                        }
                        if overflowed {
                            break;
                        }
                        next = next.add(&piece);
                    }
                    if overflowed {
                        return current;
                    }
                    current = next;
                    if !changed {
                        break;
                    }
                }
                current
            }
        }

        #[cfg(test)]
        mod tests {
            use super::*;

            #[test]
            fn completed_wrapping_alias_repeated_equation_retains_one_normal_form() {
                let program = typed_trees::TypedTrees::default();
                let mut engine = Engine::for_explicit_bindings(&program);
                let completed = Polynomial::atom("completed".to_owned());
                let denotation = Polynomial::atom("denotation".to_owned());
                engine.harvest_substitution(&completed, &denotation);
                engine.harvest_substitution(&completed, &denotation);
                assert_eq!(
                    engine.substituted(&completed),
                    engine.substituted(&denotation)
                );
            }
        }
    }
    pub use denotations::IntegerDenotation;
    pub(crate) mod integer_operations {
        use super::{BigInt, BinaryOperator, Engine, Polynomial};
        use numerics::arithmetic::ArithmeticDomain;
        use typed_trees::operator::builtin_integer_result_carrier;
        use typed_trees::types::PrimitiveType;

        impl Engine<'_> {
            pub(crate) fn integer_complement_corner(primitive: PrimitiveType) -> Option<BigInt> {
                if !primitive.is_fixed_integer() {
                    return None;
                }
                let (_, maximum) = primitive.integer_bounds()?;
                Some(if primitive.is_signed_integer() {
                    BigInt::from_i64(-1)
                } else {
                    BigInt::from_i128(maximum)
                })
            }

            pub(crate) fn integer_complement_value(
                primitive: PrimitiveType,
                operand: &Polynomial,
            ) -> Option<Polynomial> {
                let corner = Self::integer_complement_corner(primitive)?;
                Some(Polynomial::constant(corner).sub(operand))
            }

            pub(crate) fn admit_integer_complement(
                &self,
                primitive: PrimitiveType,
                operand: &Polynomial,
            ) -> Option<Polynomial> {
                if !self.integer_value_lands(primitive, operand) {
                    return None;
                }
                let value = Self::integer_complement_value(primitive, &self.substituted(operand))?;
                self.integer_value_lands(primitive, &value).then_some(value)
            }

            pub(crate) fn selected_bitwise_value(
                &mut self,
                expression: typed_trees::expression::ExpressionHandle,
                binary: &typed_trees::expression::TableBinaryExpression,
            ) -> Option<Polynomial> {
                let reference = self.source_result_type(expression)?;
                let primitive = self.program.primitive_type_reference(reference)?;
                let bits = crate::proof_contracts::arithmetic_domains::integer_bit_width(primitive)?
                    as u32;
                let left = self.normalize(binary.left)?;
                let right = self.normalize(binary.right)?;
                self.integer_bitwise(
                    binary.operator,
                    left,
                    right,
                    bits,
                    primitive.is_signed_integer(),
                )
            }

            pub(crate) fn selected_exact_shift_value(
                &mut self,
                expression: typed_trees::expression::ExpressionHandle,
                binary: &typed_trees::expression::TableBinaryExpression,
            ) -> Option<Polynomial> {
                let value_type = self.source_result_type(binary.left)?;
                let result_type = self.source_result_type(expression)?;
                let primitive = self.program.primitive_type_reference(value_type)?;
                if !primitive.is_fixed_integer()
                    || self.program.primitive_type_reference(result_type) != Some(primitive)
                    || self
                        .program
                        .arithmetic_domain_for_type_reference(value_type)
                        != ArithmeticDomain::Exact
                    || self
                        .program
                        .arithmetic_domain_for_type_reference(result_type)
                        != ArithmeticDomain::Exact
                {
                    return None;
                }
                let bits = crate::proof_contracts::arithmetic_domains::integer_bit_width(primitive)?
                    as u32;
                let value = self.normalize(binary.left)?;
                let count = self.normalize(binary.right)?;
                match binary.operator {
                    BinaryOperator::ShiftLeft => self.integer_shift_left(value, count, bits),
                    BinaryOperator::ShiftRight => self.integer_shift_right(value, count, bits),
                    _ => None,
                }
            }

            pub(crate) fn integer_operation_meaning(
                operator: BinaryOperator,
                meaning: [(PrimitiveType, ArithmeticDomain); 2],
            ) -> bool {
                let [(left, left_policy), (right, right_policy)] = meaning;
                if builtin_integer_result_carrier(operator, [left, right]).is_none() {
                    return false;
                }
                let preserves_formed_value =
                    |policy| matches!(policy, ArithmeticDomain::Exact | ArithmeticDomain::Trapping);
                match operator {
                    BinaryOperator::ShiftLeft | BinaryOperator::ShiftRight => {
                        preserves_formed_value(left_policy)
                    }
                    BinaryOperator::BitwiseAnd
                    | BinaryOperator::BitwiseOr
                    | BinaryOperator::BitwiseXor => true,
                    BinaryOperator::Add
                    | BinaryOperator::Subtract
                    | BinaryOperator::Multiply
                    | BinaryOperator::Divide
                    | BinaryOperator::Modulo => {
                        preserves_formed_value(left_policy) && preserves_formed_value(right_policy)
                    }
                    _ => false,
                }
            }

            pub(crate) fn integer_operation_policy(
                operator: BinaryOperator,
                meaning: [(PrimitiveType, ArithmeticDomain); 2],
            ) -> Option<ArithmeticDomain> {
                let [(_, left), (_, right)] = meaning;
                match operator {
                    BinaryOperator::ShiftLeft | BinaryOperator::ShiftRight => Some(left),
                    BinaryOperator::BitwiseAnd
                    | BinaryOperator::BitwiseOr
                    | BinaryOperator::BitwiseXor => Some(left.combine(right)),
                    BinaryOperator::Add
                    | BinaryOperator::Subtract
                    | BinaryOperator::Multiply
                    | BinaryOperator::Divide
                    | BinaryOperator::Modulo
                        if left == ArithmeticDomain::Exact
                            || right == ArithmeticDomain::Exact
                            || left == right =>
                    {
                        Some(left.combine(right))
                    }
                    _ => None,
                }
            }

            pub(crate) fn integer_policy_operation_meaning(
                operator: BinaryOperator,
                meaning: [(PrimitiveType, ArithmeticDomain); 2],
            ) -> Option<(PrimitiveType, ArithmeticDomain)> {
                let [(left, _), (right, _)] = meaning;
                let policy = Self::integer_operation_policy(operator, meaning)?;
                if !matches!(
                    policy,
                    ArithmeticDomain::Wrapping | ArithmeticDomain::Saturating
                ) || !matches!(
                    operator,
                    BinaryOperator::Add | BinaryOperator::Subtract | BinaryOperator::Multiply
                ) {
                    return None;
                }
                let primitive = builtin_integer_result_carrier(operator, [left, right])
                    .filter(|primitive| primitive.is_fixed_integer())?;
                Some((primitive, policy))
            }

            pub(crate) fn selected_integer_binary_value(
                &mut self,
                operator: BinaryOperator,
                meaning: [(PrimitiveType, ArithmeticDomain); 2],
                left: Polynomial,
                right: Polynomial,
            ) -> Option<Polynomial> {
                if !Self::integer_operation_meaning(operator, meaning) {
                    return None;
                }
                let primitive = meaning[0].0;
                match operator {
                    BinaryOperator::ShiftLeft
                    | BinaryOperator::ShiftRight
                    | BinaryOperator::BitwiseAnd
                    | BinaryOperator::BitwiseOr
                    | BinaryOperator::BitwiseXor => {
                        let bits = crate::proof_contracts::arithmetic_domains::integer_bit_width(
                            primitive,
                        )? as u32;
                        match operator {
                            BinaryOperator::ShiftLeft => self.integer_shift_left(left, right, bits),
                            BinaryOperator::ShiftRight => {
                                self.integer_shift_right(left, right, bits)
                            }
                            _ => self.integer_bitwise(
                                operator,
                                left,
                                right,
                                bits,
                                primitive.is_signed_integer(),
                            ),
                        }
                    }
                    _ => self.integer_binary_value(operator, left, right),
                }
            }

            pub(crate) fn integer_binary_value(
                &mut self,
                operator: BinaryOperator,
                left: Polynomial,
                right: Polynomial,
            ) -> Option<Polynomial> {
                match operator {
                    BinaryOperator::Add => Some(left.add(&right)),
                    BinaryOperator::Subtract => Some(left.sub(&right)),
                    BinaryOperator::Multiply => left.checked_mul(&right),
                    BinaryOperator::Divide => self.integer_quotient(left, right),
                    BinaryOperator::Modulo => self.integer_remainder(left, right, true),
                    _ => None,
                }
            }

            pub(crate) fn integer_value_lands(
                &self,
                primitive: PrimitiveType,
                value: &Polynomial,
            ) -> bool {
                let queries = super::LowerBoundQueries::direct(self);
                self.integer_value_lands_with_queries(&queries, primitive, value)
            }

            pub(crate) fn integer_value_lands_with_queries(
                &self,
                queries: &super::LowerBoundQueries<'_, '_>,
                primitive: PrimitiveType,
                value: &Polynomial,
            ) -> bool {
                if primitive == PrimitiveType::Addr {
                    let Some(bound) = self.address_model_bound_value() else {
                        return false;
                    };
                    return queries.prove_at_least(&self.substituted(value), &BigInt::zero())
                        && queries.prove_at_least(
                            &self.substituted(&bound.sub(value)),
                            &BigInt::from_i64(1),
                        );
                }
                let Some((minimum, maximum)) = primitive.integer_bounds() else {
                    return false;
                };
                queries.prove_at_least(
                    &self
                        .substituted(&value.sub(&Polynomial::constant(BigInt::from_i128(minimum)))),
                    &BigInt::zero(),
                ) && queries.prove_at_least(
                    &self.substituted(&Polynomial::constant(BigInt::from_i128(maximum)).sub(value)),
                    &BigInt::zero(),
                )
            }

            pub(crate) fn linear_integer_operation_lands_with_queries(
                &self,
                queries: &super::LowerBoundQueries<'_, '_>,
                operator: BinaryOperator,
                primitives: [PrimitiveType; 2],
                left: &Polynomial,
                right: &Polynomial,
                value: &Polynomial,
            ) -> bool {
                let [primitive, right_primitive] = primitives;
                let Some(result) = builtin_integer_result_carrier(operator, primitives) else {
                    return false;
                };
                self.integer_value_lands_with_queries(queries, primitive, left)
                    && self.integer_value_lands_with_queries(queries, right_primitive, right)
                    && self.integer_value_lands_with_queries(queries, result, value)
            }

            fn integer_operation_inputs_land(
                &self,
                operator: BinaryOperator,
                primitives: [PrimitiveType; 2],
                policy: ArithmeticDomain,
                left: &Polynomial,
                right: &Polynomial,
            ) -> bool {
                let [primitive, right_primitive] = primitives;
                if builtin_integer_result_carrier(operator, primitives).is_none()
                    || !self.integer_value_lands(primitive, left)
                    || !self.integer_value_lands(right_primitive, right)
                {
                    return false;
                }
                if matches!(
                    operator,
                    BinaryOperator::ShiftLeft | BinaryOperator::ShiftRight
                ) && policy != ArithmeticDomain::Wrapping
                {
                    let Some(bits) =
                        crate::proof_contracts::arithmetic_domains::integer_bit_width(primitive)
                    else {
                        return false;
                    };
                    if !self.prove_at_least(&self.substituted(right), &BigInt::zero())
                        || !self.prove_at_least(
                            &self.substituted(
                                &Polynomial::constant(BigInt::from_i64(bits)).sub(right),
                            ),
                            &BigInt::from_i64(1),
                        )
                    {
                        return false;
                    }
                }
                if matches!(operator, BinaryOperator::Divide | BinaryOperator::Modulo) {
                    let divisor = self.substituted(right);
                    let positive = self.prove_at_least(&divisor, &BigInt::from_i64(1));
                    let negative = Polynomial::default().sub(&divisor);
                    if !positive && !self.prove_at_least(&negative, &BigInt::from_i64(1)) {
                        return false;
                    }
                    let Some((minimum, _)) = primitive.integer_bounds() else {
                        return false;
                    };
                    if minimum < 0
                        && matches!(policy, ArithmeticDomain::Exact | ArithmeticDomain::Trapping)
                        && !positive
                        && !self.prove_at_least(&negative, &BigInt::from_i64(2))
                        && !self.prove_at_least(
                            &self.substituted(
                                &left.sub(&Polynomial::constant(BigInt::from_i128(minimum))),
                            ),
                            &BigInt::from_i64(1),
                        )
                    {
                        return false;
                    }
                }
                true
            }

            pub(crate) fn admit_selected_integer_operation(
                &mut self,
                operator: BinaryOperator,
                meaning: [(PrimitiveType, ArithmeticDomain); 2],
                left: &Polynomial,
                right: &Polynomial,
                binding: Option<&Polynomial>,
            ) -> Option<Polynomial> {
                let primitives = meaning.map(|(primitive, _)| primitive);
                let policy = Self::integer_operation_policy(operator, meaning)?;
                if !self.integer_operation_inputs_land(operator, primitives, policy, left, right) {
                    return None;
                }
                let result = builtin_integer_result_carrier(operator, primitives)?;
                let mut admitted = self.clone();
                let left_value = admitted.substituted(left);
                let mut right_value = admitted.substituted(right);
                if policy == ArithmeticDomain::Wrapping
                    && matches!(
                        operator,
                        BinaryOperator::ShiftLeft | BinaryOperator::ShiftRight
                    )
                {
                    let width =
                        crate::proof_contracts::arithmetic_domains::integer_bit_width(result)?;
                    let count_bits = crate::proof_contracts::arithmetic_domains::integer_bit_width(
                        primitives[1],
                    )? as u32;
                    right_value = admitted.integer_bitwise(
                        BinaryOperator::BitwiseAnd,
                        right_value,
                        Polynomial::constant(BigInt::from_i64(width - 1)),
                        count_bits,
                        primitives[1].is_signed_integer(),
                    )?;
                }
                let effective_right = right_value.clone();
                let value = if Self::integer_operation_meaning(operator, meaning) {
                    admitted.selected_integer_binary_value(
                        operator,
                        meaning,
                        left_value,
                        right_value,
                    )?
                } else {
                    if !matches!(
                        policy,
                        ArithmeticDomain::Wrapping | ArithmeticDomain::Saturating
                    ) {
                        return None;
                    }
                    let candidate = match operator {
                        BinaryOperator::ShiftLeft | BinaryOperator::ShiftRight => {
                            let bits =
                                crate::proof_contracts::arithmetic_domains::integer_bit_width(
                                    result,
                                )? as u32;
                            if operator == BinaryOperator::ShiftLeft {
                                admitted.integer_shift_left(left_value, right_value, bits)?
                            } else {
                                admitted.integer_shift_right(left_value, right_value, bits)?
                            }
                        }
                        _ => admitted.integer_binary_value(operator, left_value, right_value)?,
                    };
                    admitted.integer_policy_value(result, policy, candidate)?
                };
                if operator == BinaryOperator::Multiply
                    && Self::integer_operation_meaning(operator, meaning)
                {
                    admitted.install_exact_product_interval(left, right, &value);
                }
                if !admitted.integer_value_lands(result, &value) {
                    return None;
                }
                admitted.install_integer_operation_bounds(operator, left, &effective_right, &value);
                if operator == BinaryOperator::Modulo {
                    admitted.install_fixed_quotient_remainder(left, &effective_right, &value);
                }
                if let Some(binding) = binding
                    && !admitted.install_hypotheses(vec![(
                        BinaryOperator::Equal,
                        binding.clone(),
                        value.clone(),
                    )])
                {
                    return None;
                }
                *self = admitted;
                Some(value)
            }

            fn install_fixed_quotient_remainder(
                &mut self,
                dividend: &Polynomial,
                divisor: &Polynomial,
                remainder: &Polynomial,
            ) -> bool {
                let interval = self.quotient_interval(dividend, divisor);
                let (Some(minimum), Some(maximum)) = (interval.low, interval.high) else {
                    return false;
                };
                if minimum != maximum {
                    return false;
                }
                let Some(product) = self
                    .substituted(divisor)
                    .checked_mul(&Polynomial::constant(minimum))
                else {
                    return false;
                };
                let value = self.substituted(dividend).sub(&product);
                let difference = self.substituted(remainder).sub(&value);
                if self.prove_at_least(&difference, &BigInt::zero())
                    && self.prove_at_least(&difference.neg(), &BigInt::zero())
                {
                    return false;
                }
                self.install_hypotheses(vec![(BinaryOperator::Equal, remainder.clone(), value)])
            }

            pub(crate) fn install_integer_operation_bounds(
                &mut self,
                operator: BinaryOperator,
                left: &Polynomial,
                right: &Polynomial,
                value: &Polynomial,
            ) -> bool {
                if !matches!(
                    operator,
                    BinaryOperator::Divide | BinaryOperator::ShiftRight | BinaryOperator::Modulo
                ) {
                    return false;
                }
                let dividend = self.substituted(left);
                let divisor = self.substituted(right);
                let result = self.substituted(value);
                let consequence = match operator {
                    BinaryOperator::Modulo => divisor.sub(&result),
                    _ => dividend.sub(&result),
                };
                // These rules establish a difference of at least zero or one.
                // Once the stronger bound is present, rechecking its conditions
                // cannot strengthen it. A zero bound must still be reconsidered.
                let strongest_minimum = BigInt::from_i64(1);
                if self.bounds.iter().any(|(existing, minimum)| {
                    *existing == consequence && minimum >= &strongest_minimum
                }) {
                    return false;
                }
                let consequence = {
                    // These few queries share unchanged premises. Defer the full
                    // bound index until a simple query cannot resolve, then release
                    // the borrowed view before installing any consequence.
                    let mut queries = super::LowerBoundQueries::direct(self);
                    match operator {
                        BinaryOperator::Divide
                            if queries
                                .prove_with_deferred_preparation(&dividend, &BigInt::zero())
                                && queries.prove_with_deferred_preparation(
                                    &divisor,
                                    &BigInt::from_i64(1),
                                ) =>
                        {
                            let strict = queries
                                .prove_with_deferred_preparation(&dividend, &BigInt::from_i64(1))
                                && queries.prove_with_deferred_preparation(
                                    &divisor,
                                    &BigInt::from_i64(2),
                                );
                            Some((consequence, BigInt::from_i64(i64::from(strict))))
                        }
                        BinaryOperator::ShiftRight
                            if queries.prove_with_deferred_preparation(
                                &dividend,
                                &BigInt::from_i64(1),
                            ) && queries.prove_with_deferred_preparation(
                                &divisor,
                                &BigInt::from_i64(1),
                            ) =>
                        {
                            Some((consequence, BigInt::from_i64(1)))
                        }
                        BinaryOperator::Modulo
                            if queries
                                .prove_with_deferred_preparation(&dividend, &BigInt::zero())
                                && queries.prove_with_deferred_preparation(
                                    &divisor,
                                    &BigInt::from_i64(1),
                                ) =>
                        {
                            Some((consequence, BigInt::from_i64(1)))
                        }
                        _ => None,
                    }
                };
                if let Some(bound) = consequence
                    && !self.bounds.contains(&bound)
                {
                    self.bounds.push(bound);
                    self.refresh_difference_bounds();
                    return true;
                }
                false
            }
        }
        #[cfg(test)]
        mod admission_tests {
            use super::*;

            fn constant(value: i64) -> Polynomial {
                Polynomial::constant(BigInt::from_i64(value))
            }

            #[test]
            fn established_operation_bounds_do_not_repeat_their_proof() {
                use std::sync::atomic::Ordering;

                let program = typed_trees::TypedTrees::default();
                for operator in [
                    BinaryOperator::Divide,
                    BinaryOperator::Modulo,
                    BinaryOperator::ShiftRight,
                ] {
                    let mut engine = Engine::for_explicit_bindings(&program);
                    let dividend = engine
                        .conditional_value(vec![
                            super::super::ConditionalValueArm {
                                conditions: vec![],
                                value: constant(4),
                            },
                            super::super::ConditionalValueArm {
                                conditions: vec![],
                                value: constant(8),
                            },
                        ])
                        .unwrap();
                    let divisor = constant(2);
                    let result = Polynomial::atom("result".to_owned());
                    assert!(
                        engine.install_integer_operation_bounds(
                            operator, &dividend, &divisor, &result,
                        )
                    );
                    let bounds = engine.bounds.clone();
                    let remaining = engine.conditional_work_remaining.load(Ordering::Relaxed);
                    for _ in 0..4 {
                        assert!(!engine.install_integer_operation_bounds(
                            operator, &dividend, &divisor, &result,
                        ));
                    }
                    assert_eq!(engine.bounds, bounds);
                    assert_eq!(
                        engine.conditional_work_remaining.load(Ordering::Relaxed),
                        remaining,
                        "an established consequence needs no repeated conditional proof",
                    );
                    let other_result = Polynomial::atom("other_result".to_owned());
                    assert!(engine.install_integer_operation_bounds(
                        operator,
                        &dividend,
                        &divisor,
                        &other_result,
                    ));
                }

                let mut engine = Engine::for_explicit_bindings(&program);
                let dividend = Polynomial::atom("dividend".to_owned());
                let divisor = Polynomial::atom("divisor".to_owned());
                let result = Polynomial::atom("result".to_owned());
                assert!(!engine.install_integer_operation_bounds(
                    BinaryOperator::Divide,
                    &dividend,
                    &divisor,
                    &result,
                ));
                assert!(engine.install_hypotheses(vec![
                    (
                        BinaryOperator::GreaterOrEqual,
                        dividend.clone(),
                        constant(0)
                    ),
                    (BinaryOperator::GreaterOrEqual, divisor.clone(), constant(1)),
                ]));
                assert!(engine.install_integer_operation_bounds(
                    BinaryOperator::Divide,
                    &dividend,
                    &divisor,
                    &result,
                ));
                let difference = dividend.sub(&result);
                assert!(
                    engine
                        .bounds
                        .contains(&(difference.clone(), BigInt::zero()))
                );
                assert!(
                    !engine
                        .bounds
                        .contains(&(difference.clone(), BigInt::from_i64(1)))
                );
                assert!(engine.install_hypotheses(vec![
                    (
                        BinaryOperator::GreaterOrEqual,
                        dividend.clone(),
                        constant(1)
                    ),
                    (BinaryOperator::GreaterOrEqual, divisor.clone(), constant(2)),
                ]));
                assert!(engine.install_integer_operation_bounds(
                    BinaryOperator::Divide,
                    &dividend,
                    &divisor,
                    &result,
                ));
                assert!(engine.bounds.contains(&(difference, BigInt::from_i64(1))));
            }

            #[test]
            fn exact_peers_preserve_combined_finite_policy() {
                let program = typed_trees::TypedTrees::default();
                for (policy, expected) in [
                    (ArithmeticDomain::Wrapping, 4),
                    (ArithmeticDomain::Saturating, 255),
                ] {
                    for policies in [
                        [ArithmeticDomain::Exact, policy],
                        [policy, ArithmeticDomain::Exact],
                    ] {
                        let mut engine = Engine::for_explicit_bindings(&program);
                        let result = engine
                            .admit_selected_integer_operation(
                                BinaryOperator::Add,
                                policies.map(|policy| (PrimitiveType::U8, policy)),
                                &constant(250),
                                &constant(10),
                                None,
                            )
                            .expect("Exact is neutral in the selected finite policy");
                        assert_eq!(result.constant_value(), Some(BigInt::from_i64(expected)));
                    }
                }
                assert_eq!(
                    Engine::integer_operation_policy(
                        BinaryOperator::Add,
                        [
                            (PrimitiveType::U8, ArithmeticDomain::Wrapping),
                            (PrimitiveType::U8, ArithmeticDomain::Saturating)
                        ],
                    ),
                    None
                );
            }

            #[test]
            fn signed_quotient_overflow_follows_selected_policy() {
                let program = typed_trees::TypedTrees::default();
                for (policy, quotient) in [
                    (ArithmeticDomain::Exact, None),
                    (ArithmeticDomain::Trapping, None),
                    (ArithmeticDomain::Wrapping, Some(-128)),
                    (ArithmeticDomain::Saturating, Some(127)),
                ] {
                    for (operator, expected) in [
                        (BinaryOperator::Divide, quotient),
                        (BinaryOperator::Modulo, quotient.map(|_| 0)),
                    ] {
                        let mut engine = Engine::for_explicit_bindings(&program);
                        let result = engine.admit_selected_integer_operation(
                            operator,
                            [(PrimitiveType::I8, policy); 2],
                            &constant(-128),
                            &constant(-1),
                            None,
                        );
                        assert_eq!(
                            result.and_then(|value| value.constant_value()),
                            expected.map(BigInt::from_i64)
                        );
                    }
                    let mut engine = Engine::for_explicit_bindings(&program);
                    let before = engine.integer_projection_registrations();
                    assert!(
                        engine
                            .admit_selected_integer_operation(
                                BinaryOperator::Modulo,
                                [(PrimitiveType::I8, policy); 2],
                                &constant(7),
                                &constant(0),
                                None,
                            )
                            .is_none()
                    );
                    assert_eq!(before, engine.integer_projection_registrations());
                }
            }

            #[test]
            fn wrapping_shifts_reduce_signed_counts_without_false_descent() {
                let program = typed_trees::TypedTrees::default();
                for (operator, value, count, expected) in [
                    (BinaryOperator::ShiftLeft, 1, 8, 1),
                    (BinaryOperator::ShiftLeft, 1, -1, 128),
                    (BinaryOperator::ShiftRight, 7, 8, 7),
                ] {
                    let mut engine = Engine::for_explicit_bindings(&program);
                    let result = engine
                        .admit_selected_integer_operation(
                            operator,
                            [
                                (PrimitiveType::U8, ArithmeticDomain::Wrapping),
                                (PrimitiveType::I8, ArithmeticDomain::Exact),
                            ],
                            &constant(value),
                            &constant(count),
                            None,
                        )
                        .expect("wrapping count has a defined Euclidean reduction");
                    assert_eq!(result.constant_value(), Some(BigInt::from_i64(expected)));
                    if operator == BinaryOperator::ShiftRight {
                        assert!(
                            !engine.prove_at_least(
                                &constant(value).sub(&result),
                                &BigInt::from_i64(1)
                            )
                        );
                    }
                }
                for policy in [
                    ArithmeticDomain::Exact,
                    ArithmeticDomain::Trapping,
                    ArithmeticDomain::Saturating,
                ] {
                    let mut engine = Engine::for_explicit_bindings(&program);
                    assert!(
                        engine
                            .admit_selected_integer_operation(
                                BinaryOperator::ShiftLeft,
                                [
                                    (PrimitiveType::U8, policy),
                                    (PrimitiveType::I8, ArithmeticDomain::Wrapping)
                                ],
                                &constant(1),
                                &constant(8),
                                None,
                            )
                            .is_none()
                    );
                }
            }
        }
    }
    pub(crate) mod integer_policy {
        use super::{BigInt, Engine, OpaqueTerm, Polynomial};
        use crate::proof_contracts::arithmetic_domains::BigIntInterval as Interval;
        use numerics::arithmetic::ArithmeticDomain;
        use typed_trees::types::PrimitiveType;

        impl Engine<'_> {
            pub(crate) fn integer_policy_value(
                &mut self,
                primitive: PrimitiveType,
                domain: ArithmeticDomain,
                value: Polynomial,
            ) -> Option<Polynomial> {
                if !primitive.is_fixed_integer()
                    || !matches!(
                        domain,
                        ArithmeticDomain::Wrapping | ArithmeticDomain::Saturating
                    )
                {
                    return None;
                }
                let value = self.substituted(&value);
                if self.integer_value_lands(primitive, &value) {
                    return Some(value);
                }
                let (minimum, maximum) =
                    super::super::ranking_range::integer_carrier_bounds(primitive)?;
                let value = if domain == ArithmeticDomain::Wrapping {
                    self.wrapping_residue(
                        primitive,
                        value,
                        &maximum.sub(&minimum).add(&BigInt::from_i64(1)),
                    )?
                } else {
                    value
                };
                if let Some(value) = value.constant_value() {
                    return Some(Polynomial::constant(complete_integer_policy(
                        domain, &value, &minimum, &maximum,
                    )?));
                }
                let atom = format!("\0integer-policy:{primitive:?}:{domain:?}:{value:?}");
                let interval = self.integer_policy_interval(primitive, domain, &value);
                self.register_opaque_term(
                    atom.clone(),
                    OpaqueTerm::IntegerPolicy {
                        primitive,
                        domain,
                        value,
                    },
                );
                self.arithmetic_intervals.insert(atom.clone(), interval);
                Some(Polynomial::atom(atom))
            }

            fn wrapping_residue(
                &self,
                primitive: PrimitiveType,
                value: Polynomial,
                modulus: &BigInt,
            ) -> Option<Polynomial> {
                let mut substitutions = super::BTreeMap::new();
                for monomial in value.terms.keys() {
                    for atom in monomial.keys() {
                        let replacement = self
                            .opaque_terms
                            .iter()
                            .find_map(|(known, term)| {
                                if known != atom {
                                    return None;
                                }
                                match term {
                                    OpaqueTerm::IntegerPolicy {
                                        primitive: source,
                                        domain: ArithmeticDomain::Wrapping,
                                        value,
                                    } if *source == primitive => Some(value.clone()),
                                    _ => None,
                                }
                            })
                            .unwrap_or_else(|| Polynomial::atom(atom.clone()));
                        substitutions.insert(atom.clone(), replacement);
                    }
                }
                let mut value =
                    super::super::inductive_judgment::apply_argument_map(&value, &substitutions)?;
                for coefficient in value.terms.values_mut() {
                    let (_, remainder) = coefficient.div_rem(modulus)?;
                    *coefficient = if remainder.is_negative() {
                        remainder.add(modulus)
                    } else {
                        remainder
                    };
                }
                value.terms.retain(|_, coefficient| !coefficient.is_zero());
                Some(value)
            }

            pub(crate) fn integer_policy_interval(
                &self,
                primitive: PrimitiveType,
                domain: ArithmeticDomain,
                value: &Polynomial,
            ) -> Interval {
                let Some((minimum, maximum)) =
                    super::super::ranking_range::integer_carrier_bounds(primitive)
                else {
                    return Interval::unbounded();
                };
                let value = self.substituted(value);
                if let Some(value) = value.constant_value()
                    && let Some(value) = complete_integer_policy(domain, &value, &minimum, &maximum)
                {
                    return Interval::constant(value);
                }
                if domain == ArithmeticDomain::Saturating {
                    let interval = self.polynomial_interval(&value);
                    return Interval {
                        low: Some(interval.low.map_or_else(
                            || minimum.clone(),
                            |value| value.max(minimum.clone()).min(maximum.clone()),
                        )),
                        high: Some(interval.high.map_or_else(
                            || maximum.clone(),
                            |value| value.max(minimum).min(maximum.clone()),
                        )),
                    };
                }
                let interval = self.polynomial_interval(&value);
                if let (Some(low), Some(high)) = (interval.low, interval.high)
                    && let (Some(wrapped_low), Some(wrapped_high)) = (
                        complete_integer_policy(domain, &low, &minimum, &maximum),
                        complete_integer_policy(domain, &high, &minimum, &maximum),
                    )
                    && high.sub(&low) == wrapped_high.sub(&wrapped_low)
                {
                    return Interval {
                        low: Some(wrapped_low),
                        high: Some(wrapped_high),
                    };
                }
                Interval {
                    low: Some(minimum),
                    high: Some(maximum),
                }
            }
        }

        fn complete_integer_policy(
            domain: ArithmeticDomain,
            value: &BigInt,
            minimum: &BigInt,
            maximum: &BigInt,
        ) -> Option<BigInt> {
            match domain {
                ArithmeticDomain::Wrapping => {
                    let modulus = maximum.sub(minimum).add(&BigInt::from_i64(1));
                    let (_, remainder) = value.sub(minimum).div_rem(&modulus)?;
                    let residue = if remainder.is_negative() {
                        remainder.add(&modulus)
                    } else {
                        remainder
                    };
                    Some(minimum.add(&residue))
                }
                ArithmeticDomain::Saturating => {
                    Some(value.clone().max(minimum.clone()).min(maximum.clone()))
                }
                _ => None,
            }
        }
    }
    pub(crate) mod intervals {
        use super::super::BigInt;
        use super::{BinaryOperator, Engine, OpaqueTerm, Polynomial};
        use crate::proof_contracts::arithmetic_domains::{
            BigIntInterval as Interval, bitwise_carrier_bounds, floor_shift_right,
        };

        impl<'program> Engine<'program> {
            pub(crate) fn install_exact_product_interval(
                &mut self,
                left: &Polynomial,
                right: &Polynomial,
                value: &Polynomial,
            ) {
                let interval = self
                    .polynomial_interval(&self.substituted(left))
                    .multiply(&self.polynomial_interval(&self.substituted(right)));
                for bound in interval
                    .low
                    .map(|low| (value.clone(), low))
                    .into_iter()
                    .chain(interval.high.map(|high| (value.neg(), high.negate())))
                {
                    if !self.bounds.contains(&bound) {
                        self.bounds.push(bound);
                    }
                }
                self.refresh_difference_bounds();
            }

            pub(crate) fn remainder_interval(
                &self,
                operand: &Polynomial,
                modulus: &Polynomial,
                tight_interval: bool,
            ) -> Interval {
                let modulus = self.substituted(modulus);
                if let Some(constant) = modulus.constant_value() {
                    if constant.is_zero() {
                        return Interval::unbounded();
                    }
                    return self.constant_remainder_interval(operand, &constant, tight_interval);
                }
                let operand_interval = self.polynomial_interval(&self.substituted(operand));
                let divisor_interval = self.polynomial_interval(&modulus);
                operand_interval.remainder(&divisor_interval)
            }

            pub(crate) fn constant_remainder_interval(
                &self,
                operand: &Polynomial,
                modulus: &BigInt,
                tight_interval: bool,
            ) -> Interval {
                self.polynomial_interval(&self.substituted(operand))
                    .constant_remainder(modulus, tight_interval)
            }

            pub(crate) fn quotient_interval(
                &self,
                dividend: &Polynomial,
                divisor: &Polynomial,
            ) -> Interval {
                let dividend_interval = self.polynomial_interval(&self.substituted(dividend));
                let divisor = self.substituted(divisor);
                if let Some(divisor) = divisor.constant_value() {
                    return Self::constant_quotient_interval(dividend_interval, &divisor);
                }
                let divisor_interval = self.polynomial_interval(&divisor);
                Self::bounded_quotient_interval(&dividend_interval, &divisor_interval)
            }

            pub(crate) fn constant_quotient_interval(
                dividend: Interval,
                divisor: &BigInt,
            ) -> Interval {
                dividend.divide(&Interval::constant(divisor.clone()))
            }

            pub(crate) fn bounded_quotient_interval(
                dividend: &Interval,
                divisor: &Interval,
            ) -> Interval {
                dividend.divide(divisor)
            }

            fn shift_count_bits(
                &self,
                value: &Polynomial,
                count: &Polynomial,
                count_bits: u32,
            ) -> Option<(Interval, u64, u64)> {
                let value_interval = self.polynomial_interval(&self.substituted(value));
                let count_interval = self.polynomial_interval(&self.substituted(count));
                let maximum_count = BigInt::from_u64(u64::from(count_bits - 1));
                let low_count = count_interval
                    .low
                    .unwrap_or_else(BigInt::zero)
                    .max(BigInt::zero());
                let high_count = count_interval
                    .high
                    .unwrap_or_else(|| maximum_count.clone())
                    .min(maximum_count);
                if low_count > high_count {
                    return None;
                }
                let (Some(low_bits), Some(high_bits)) = (low_count.to_u64(), high_count.to_u64())
                else {
                    return None;
                };
                Some((value_interval, low_bits, high_bits))
            }

            pub(crate) fn shift_left_interval(
                &self,
                value: &Polynomial,
                count: &Polynomial,
                count_bits: u32,
            ) -> Interval {
                let Some((value_interval, low_bits, high_bits)) =
                    self.shift_count_bits(value, count, count_bits)
                else {
                    return Interval::unbounded();
                };
                value_interval.multiply(&Interval {
                    low: Some(BigInt::from_i64(1).shl_bits(low_bits as usize)),
                    high: Some(BigInt::from_i64(1).shl_bits(high_bits as usize)),
                })
            }

            pub(crate) fn shift_right_interval(
                &self,
                value: &Polynomial,
                count: &Polynomial,
                count_bits: u32,
            ) -> Interval {
                let Some((value_interval, low_bits, high_bits)) =
                    self.shift_count_bits(value, count, count_bits)
                else {
                    return Interval::unbounded();
                };
                value_interval.shift_right(low_bits, high_bits)
            }

            pub(crate) fn integer_remainder(
                &mut self,
                operand: Polynomial,
                modulus: Polynomial,
                tight_interval: bool,
            ) -> Option<Polynomial> {
                if modulus
                    .constant_value()
                    .is_some_and(|value| value.is_zero())
                {
                    return None;
                }
                if let Some(divisor) = modulus.constant_value()
                    && operand.terms.values().all(|coefficient| {
                        coefficient
                            .div_rem(&divisor)
                            .is_some_and(|(_, remainder)| remainder.is_zero())
                    })
                {
                    return Some(Polynomial::constant(BigInt::zero()));
                }
                let interval = self.remainder_interval(&operand, &modulus, tight_interval);
                let atom = format!("\0integer-remainder:{operand:?}%{modulus:?}");
                self.register_opaque_term(
                    atom.clone(),
                    OpaqueTerm::Remainder {
                        operand,
                        modulus,
                        tight_interval,
                    },
                );
                self.arithmetic_intervals.insert(atom.clone(), interval);
                Some(Polynomial::atom(atom))
            }

            pub(crate) fn integer_quotient(
                &mut self,
                dividend: Polynomial,
                divisor: Polynomial,
            ) -> Option<Polynomial> {
                if divisor
                    .constant_value()
                    .is_some_and(|value| value.is_zero())
                {
                    return None;
                }
                if let (Some(dividend), Some(divisor)) =
                    (dividend.constant_value(), divisor.constant_value())
                {
                    return Some(Polynomial::constant(dividend.div_rem(&divisor)?.0));
                }
                let interval = self.quotient_interval(&dividend, &divisor);
                let atom = format!("\0integer-quotient:{dividend:?}/{divisor:?}");
                self.register_opaque_term(atom.clone(), OpaqueTerm::Quotient { dividend, divisor });
                self.arithmetic_intervals.insert(atom.clone(), interval);
                Some(Polynomial::atom(atom))
            }

            pub(crate) fn integer_shift_left(
                &mut self,
                value: Polynomial,
                count: Polynomial,
                count_bits: u32,
            ) -> Option<Polynomial> {
                self.integer_shift(
                    value,
                    count,
                    count_bits,
                    |value, count| Some(value.shl_bits(count as usize)),
                    Self::shift_left_interval,
                    "left",
                    "<<",
                    |value, count, count_bits| OpaqueTerm::ShiftLeft {
                        value,
                        count,
                        count_bits,
                    },
                )
            }

            #[allow(clippy::too_many_arguments)]
            fn integer_shift(
                &mut self,
                value: Polynomial,
                count: Polynomial,
                count_bits: u32,
                constant: impl Fn(&BigInt, u64) -> Option<BigInt>,
                interval: fn(&Self, &Polynomial, &Polynomial, u32) -> Interval,
                direction: &str,
                operator: &str,
                term: impl Fn(Polynomial, Polynomial, u32) -> OpaqueTerm,
            ) -> Option<Polynomial> {
                if let Some(count) = count.constant_value() {
                    let in_range = count
                        .to_u64()
                        .is_some_and(|bits| bits < u64::from(count_bits));
                    if !in_range {
                        return None;
                    }
                    if let Some(value) = value.constant_value() {
                        return constant(&value, count.to_u64()?).map(Polynomial::constant);
                    }
                }
                let interval = interval(self, &value, &count, count_bits);
                let atom = format!("\0integer-shift-{direction}:{value:?}{operator}{count:?}");
                self.register_opaque_term(atom.clone(), term(value, count, count_bits));
                self.arithmetic_intervals.insert(atom.clone(), interval);
                Some(Polynomial::atom(atom))
            }

            pub(crate) fn integer_shift_right(
                &mut self,
                value: Polynomial,
                count: Polynomial,
                count_bits: u32,
            ) -> Option<Polynomial> {
                self.integer_shift(
                    value,
                    count,
                    count_bits,
                    floor_shift_right,
                    Self::shift_right_interval,
                    "right",
                    ">>",
                    |value, count, count_bits| OpaqueTerm::ShiftRight {
                        value,
                        count,
                        count_bits,
                    },
                )
            }

            pub(crate) fn integer_bitwise(
                &mut self,
                operator: BinaryOperator,
                left: Polynomial,
                right: Polynomial,
                bits: u32,
                signed: bool,
            ) -> Option<Polynomial> {
                let mask = Self::carrier_mask(bits)?;
                let left = self.substituted(&left);
                let right = self.substituted(&right);
                if left == right {
                    return match operator {
                        BinaryOperator::BitwiseAnd | BinaryOperator::BitwiseOr => Some(left),
                        BinaryOperator::BitwiseXor => Some(Polynomial::constant(BigInt::zero())),
                        _ => None,
                    };
                }
                let (lz, lo) = self.known_integer_bits(&left, bits, signed, 0);
                let (rz, ro) = self.known_integer_bits(&right, bits, signed, 0);
                let (zero, one) = Self::combine_known_bits(operator, (lz, lo), (rz, ro))?;
                if zero | one == mask {
                    let value = BigInt::from_u64(one);
                    let value = if signed && one & (1 << (bits - 1)) != 0 {
                        value.sub(&BigInt::from_u64(mask).add(&BigInt::from_i64(1)))
                    } else {
                        value
                    };
                    return Some(Polynomial::constant(value));
                }
                let interval = self.bitwise_interval(operator, &left, &right, bits, signed);
                let atom =
                    format!("\0integer-bitwise:{operator:?}:{bits}:{signed}:{left:?}:{right:?}");
                self.register_opaque_term(
                    atom.clone(),
                    OpaqueTerm::Bitwise {
                        operator,
                        left,
                        right,
                        bits,
                        signed,
                    },
                );
                self.arithmetic_intervals.insert(atom.clone(), interval);
                Some(Polynomial::atom(atom))
            }

            fn carrier_mask(bits: u32) -> Option<u64> {
                match bits {
                    1..=63 => Some((1u64 << bits) - 1),
                    64 => Some(u64::MAX),
                    _ => None,
                }
            }

            fn combine_known_bits(
                operator: BinaryOperator,
                (az, ao): (u64, u64),
                (bz, bo): (u64, u64),
            ) -> Option<(u64, u64)> {
                Some(match operator {
                    BinaryOperator::BitwiseAnd => (az | bz, ao & bo),
                    BinaryOperator::BitwiseOr => (az & bz, ao | bo),
                    BinaryOperator::BitwiseXor => ((az & bz) | (ao & bo), (az & bo) | (ao & bz)),
                    _ => return None,
                })
            }

            fn known_integer_bits(
                &self,
                value: &Polynomial,
                bits: u32,
                signed: bool,
                depth: usize,
            ) -> (u64, u64) {
                let Some(mask) = Self::carrier_mask(bits) else {
                    return (0, 0);
                };
                if depth >= 64 {
                    return (0, 0);
                }
                let value = self.substituted(value);
                let known_value =
                    value
                        .constant_value()
                        .or_else(|| match self.polynomial_interval(&value) {
                            Interval {
                                low: Some(low),
                                high: Some(high),
                            } if low == high => Some(low),
                            _ => None,
                        });
                if let Some(value) = known_value {
                    let (minimum, maximum) = bitwise_carrier_bounds(bits, signed);
                    if value < minimum || value > maximum {
                        return (0, 0);
                    }
                    let value = if value < BigInt::zero() {
                        value.add(&BigInt::from_u64(mask).add(&BigInt::from_i64(1)))
                    } else {
                        value
                    };
                    return value
                        .to_u64()
                        .map(|value| ((!value) & mask, value & mask))
                        .unwrap_or((0, 0));
                }
                let Some((atom, 1, constant)) = value.as_single_atom() else {
                    return (0, 0);
                };
                if !constant.is_zero() {
                    return (0, 0);
                }
                let Some((
                    _,
                    OpaqueTerm::Bitwise {
                        operator,
                        left,
                        right,
                        bits: term_bits,
                        signed: term_signed,
                    },
                )) = self.opaque_terms.iter().find(|(name, _)| *name == atom)
                else {
                    return (0, 0);
                };
                if *term_bits != bits || *term_signed != signed {
                    return (0, 0);
                }
                Self::combine_known_bits(
                    *operator,
                    self.known_integer_bits(left, bits, signed, depth + 1),
                    self.known_integer_bits(right, bits, signed, depth + 1),
                )
                .unwrap_or((0, 0))
            }

            pub(crate) fn bitwise_interval(
                &self,
                operator: BinaryOperator,
                left: &Polynomial,
                right: &Polynomial,
                bits: u32,
                signed: bool,
            ) -> Interval {
                if operator == BinaryOperator::BitwiseAnd {
                    self.bitwise_and_interval(left, right, bits, signed)
                } else {
                    let (minimum, maximum) = bitwise_carrier_bounds(bits, signed);
                    Interval {
                        low: Some(minimum),
                        high: Some(maximum),
                    }
                }
            }

            pub(crate) fn bitwise_and_interval(
                &self,
                left: &Polynomial,
                right: &Polynomial,
                bits: u32,
                signed: bool,
            ) -> Interval {
                self.polynomial_interval(&self.substituted(left))
                    .bitwise_and(
                        &self.polynomial_interval(&self.substituted(right)),
                        bits,
                        signed,
                    )
            }
        }
    }
    pub(crate) mod lower_bound_queries {
        use super::{BigInt, Engine, Interval, Polynomial, ZERO_ATOM};
        use std::collections::BTreeMap;

        #[derive(Clone)]
        pub(crate) struct PreparedLowerBoundIndex {
            exact_indices: Vec<u32>,
            intervals: Vec<(String, Interval)>,
            proportional: Vec<u32>,
        }

        impl PreparedLowerBoundIndex {
            pub(crate) fn new(engine: &Engine<'_>) -> Self {
                let mut exact: Vec<u32> = (0..engine.bounds.len() as u32).collect();
                exact.sort_by(|&left, &right| {
                    engine.bounds[left as usize]
                        .0
                        .terms
                        .cmp(&engine.bounds[right as usize].0.terms)
                });
                let mut strongest: Vec<u32> = Vec::with_capacity(exact.len());
                for idx in exact {
                    let (value, bound) = &engine.bounds[idx as usize];
                    if let Some(&previous_idx) = strongest.last()
                        && engine.bounds[previous_idx as usize].0 == *value
                    {
                        if *bound > engine.bounds[previous_idx as usize].1
                            && let Some(last) = strongest.last_mut()
                        {
                            *last = idx;
                        }
                    } else {
                        strongest.push(idx);
                    }
                }
                let mut proportional: Vec<u32> = (0..strongest.len() as u32).collect();
                proportional.sort_by(|&left, &right| {
                    nonconstant_monomials_cmp(
                        &engine.bounds[strongest[left as usize] as usize].0,
                        &engine.bounds[strongest[right as usize] as usize].0,
                    )
                });
                let mut atoms: Vec<&str> = engine
                    .parameter_atoms
                    .iter()
                    .map(String::as_str)
                    .chain(engine.unsigned_atoms.iter().map(String::as_str))
                    .chain(engine.matrix.atom_names())
                    .chain(engine.arithmetic_intervals.keys().map(String::as_str))
                    .chain(engine.bounds.iter().flat_map(|(value, _)| {
                        value
                            .terms
                            .keys()
                            .flat_map(|monomial| monomial.keys().map(String::as_str))
                    }))
                    .chain(std::iter::once(ZERO_ATOM))
                    .collect();
                atoms.sort_unstable();
                atoms.dedup();
                let intervals = atoms
                    .into_iter()
                    .map(|atom| (atom.to_owned(), engine.atom_interval(atom)))
                    .collect();
                Self {
                    exact_indices: strongest,
                    intervals,
                    proportional,
                }
            }
        }

        pub(crate) enum PreparedBoundsRef<'a> {
            Owned(PreparedLowerBoundIndex),
            Borrowed(&'a PreparedLowerBoundIndex),
        }

        pub(crate) struct LowerBoundQueries<'engine, 'program> {
            engine: &'engine Engine<'program>,
            prepared: Option<PreparedBoundsRef<'engine>>,
        }

        impl<'engine, 'program> LowerBoundQueries<'engine, 'program> {
            pub(crate) fn direct(engine: &'engine Engine<'program>) -> Self {
                Self {
                    engine,
                    prepared: None,
                }
            }

            pub(crate) fn prepared(engine: &'engine Engine<'program>) -> Self {
                Self {
                    engine,
                    prepared: Some(PreparedBoundsRef::Owned(PreparedLowerBoundIndex::new(
                        engine,
                    ))),
                }
            }

            pub(crate) fn from_prepared_index(
                engine: &'engine Engine<'program>,
                index: &'engine PreparedLowerBoundIndex,
            ) -> Self {
                Self {
                    engine,
                    prepared: Some(PreparedBoundsRef::Borrowed(index)),
                }
            }

            fn prepared_index(&self) -> Option<&PreparedLowerBoundIndex> {
                match &self.prepared {
                    Some(PreparedBoundsRef::Owned(index)) => Some(index),
                    Some(PreparedBoundsRef::Borrowed(index)) => Some(index),
                    None => None,
                }
            }

            pub(crate) fn engine(&self) -> &Engine<'program> {
                self.engine
            }

            pub(crate) fn prepared_exact_bounds(
                &self,
            ) -> Vec<(&'engine Polynomial, &'engine BigInt)> {
                self.prepared_index().map_or_else(Vec::new, |prepared| {
                    prepared
                        .exact_indices
                        .iter()
                        .map(|&idx| {
                            let (poly, bound) = &self.engine.bounds[idx as usize];
                            (poly, bound)
                        })
                        .collect()
                })
            }

            fn exact_bound_at_least(&self, value: &Polynomial, bound: &BigInt) -> bool {
                if let Some(prepared) = self.prepared_index() {
                    prepared
                        .exact_indices
                        .binary_search_by(|&idx| {
                            self.engine.bounds[idx as usize].0.terms.cmp(&value.terms)
                        })
                        .is_ok_and(|position| {
                            &self.engine.bounds[prepared.exact_indices[position] as usize].1
                                >= bound
                        })
                } else {
                    self.engine
                        .bounds
                        .iter()
                        .any(|(stored, stored_bound)| stored == value && stored_bound >= bound)
                }
            }

            fn atom_interval(&self, atom: &str) -> Interval {
                if let Some(prepared) = self.prepared_index()
                    && let Ok(position) = prepared
                        .intervals
                        .binary_search_by_key(&atom, |(stored, _)| stored.as_str())
                {
                    return prepared.intervals[position].1.clone();
                }
                self.engine.atom_interval(atom)
            }

            pub(crate) fn prove_at_least(&self, polynomial: &Polynomial, bound: &BigInt) -> bool {
                if let Some(proved) = self.simple_lower_bound(polynomial, bound) {
                    return proved;
                }
                self.prove_after_simple_prefix(polynomial, bound)
            }

            /// Short batches need no full premise index when existing conditions
            /// and bounds answer every question. Prepare only when unresolved,
            /// within this immutable engine borrow; retain no query verdict.
            pub(crate) fn prove_with_deferred_preparation(
                &mut self,
                polynomial: &Polynomial,
                bound: &BigInt,
            ) -> bool {
                if let Some(proved) = self.simple_lower_bound(polynomial, bound) {
                    return proved;
                }
                if self.prepared.is_none() {
                    self.prepared = Some(PreparedBoundsRef::Owned(PreparedLowerBoundIndex::new(
                        self.engine,
                    )));
                }
                self.prove_after_simple_prefix(polynomial, bound)
            }

            fn simple_lower_bound(&self, polynomial: &Polynomial, bound: &BigInt) -> Option<bool> {
                // Conditional dependencies own a shared work allowance and may return a
                // definitive false. Probe exactly once, before any other proof route.
                if let Some(proved) = self.engine.conditional_lower_bound(polynomial, bound) {
                    return Some(proved);
                }
                self.prove_local_lower_bound(polynomial, bound)
                    .then_some(true)
            }

            fn prove_after_simple_prefix(&self, polynomial: &Polynomial, bound: &BigInt) -> bool {
                if self.prove_base_lower_bound(polynomial, bound) {
                    return true;
                }
                let proves_from_bound = |stored: &Polynomial, stored_bound: &BigInt| {
                    self.prove_base_lower_bound(&polynomial.sub(stored), &bound.sub(stored_bound))
                        || self.prove_scaled_lower_bound(polynomial, bound, stored, stored_bound)
                };
                if let Some(prepared) = self.prepared_index() {
                    prepared.exact_indices.iter().any(|&idx| {
                        let (stored, stored_bound) = &self.engine.bounds[idx as usize];
                        proves_from_bound(stored, stored_bound)
                    })
                } else {
                    self.engine
                        .bounds
                        .iter()
                        .any(|(stored, stored_bound)| proves_from_bound(stored, stored_bound))
                }
            }

            pub(crate) fn prove_base_lower_bound(
                &self,
                polynomial: &Polynomial,
                bound: &BigInt,
            ) -> bool {
                if self.prove_local_lower_bound(polynomial, bound) {
                    return true;
                }
                if self.exact_bound_at_least(polynomial, bound) {
                    return true;
                }
                let proportional = |stored: &Polynomial, stored_bound: &BigInt| {
                    self.prove_proportional_lower_bound(polynomial, bound, stored, stored_bound)
                };
                let established = if let Some(prepared) = self.prepared_index() {
                    let first = prepared.proportional.partition_point(|&position| {
                        let (stored, _) =
                            &self.engine.bounds[prepared.exact_indices[position as usize] as usize];
                        nonconstant_monomials_cmp(stored, polynomial).is_lt()
                    });
                    prepared.proportional[first..]
                        .iter()
                        .map(|&position| {
                            &self.engine.bounds[prepared.exact_indices[position as usize] as usize]
                        })
                        .take_while(|(stored, _)| {
                            nonconstant_monomials_cmp(stored, polynomial).is_eq()
                        })
                        .any(|(stored, bound)| proportional(stored, bound))
                } else {
                    self.engine
                        .bounds
                        .iter()
                        .any(|(stored, bound)| proportional(stored, bound))
                };
                if established {
                    return true;
                }
                if let Some(low) = self.polynomial_interval(polynomial).low
                    && low >= *bound
                {
                    return true;
                }
                if self
                    .affine_difference_lower_bound(polynomial)
                    .is_some_and(|low| low >= *bound)
                {
                    return true;
                }
                if polynomial.terms.keys().all(|monomial| {
                    monomial.is_empty()
                        || (monomial.len() == 1 && monomial.values().next() == Some(&1))
                }) {
                    return false;
                }
                self.horner_interval(polynomial, 0)
                    .low
                    .is_some_and(|low| low >= *bound)
            }

            fn prove_local_lower_bound(&self, polynomial: &Polynomial, bound: &BigInt) -> bool {
                // This is the constant case of the independent interval enclosure.
                // Failure stays unresolved: other premises may still prove the goal.
                if polynomial
                    .constant_value()
                    .is_some_and(|constant| constant >= *bound)
                {
                    return true;
                }
                if let Some((positive, negative, constant)) = polynomial.as_atom_difference()
                    && let Some(best) = self.engine.matrix_bound(&positive, &negative)
                    && best.add(&constant) >= *bound
                {
                    return true;
                }
                if let Some((atom, sign, constant)) = polynomial.as_single_atom() {
                    let other = if sign == 1 {
                        self.engine.matrix_bound(&atom, ZERO_ATOM)
                    } else {
                        self.engine.matrix_bound(ZERO_ATOM, &atom)
                    };
                    if let Some(best) = other
                        && best.add(&constant) >= *bound
                    {
                        return true;
                    }
                }
                false
            }

            fn affine_difference_lower_bound(&self, polynomial: &Polynomial) -> Option<BigInt> {
                let mut constant = BigInt::zero();
                let mut positive = Vec::new();
                let mut negative = Vec::new();
                for (monomial, coefficient) in &polynomial.terms {
                    if monomial.is_empty() {
                        constant = coefficient.clone();
                        continue;
                    }
                    let mut factors = monomial.iter();
                    let (atom, power) = factors.next()?;
                    if *power != 1 || factors.next().is_some() {
                        return None;
                    }
                    let interval = self.atom_interval(atom);
                    if coefficient.is_negative() {
                        negative.push((
                            atom,
                            coefficient.abs(),
                            interval.high.map(|high| high.negate()),
                        ));
                    } else {
                        positive.push((atom, coefficient.clone(), interval.low));
                    }
                }
                if positive.len() + negative.len() < 3 || positive.len() + negative.len() > 128 {
                    return None;
                }
                let mut edges = Vec::new();
                for (positive_position, (positive_atom, _, positive_low)) in
                    positive.iter().enumerate()
                {
                    for (negative_position, (negative_atom, _, negative_low)) in
                        negative.iter().enumerate()
                    {
                        let Some(edge_bound) =
                            self.engine.matrix_bound(positive_atom, negative_atom)
                        else {
                            continue;
                        };
                        let unbounded = usize::from(positive_low.is_none())
                            + usize::from(negative_low.is_none());
                        let improvement = match (positive_low, negative_low) {
                            (Some(left), Some(right)) => edge_bound.sub(&left.add(right)),
                            _ => edge_bound.clone(),
                        };
                        edges.push((
                            unbounded,
                            improvement,
                            positive_position,
                            negative_position,
                            edge_bound,
                        ));
                    }
                }
                edges
                    .sort_by(|left, right| right.0.cmp(&left.0).then_with(|| right.1.cmp(&left.1)));
                for (_, _, positive_position, negative_position, edge_bound) in edges {
                    let positive_mass = &mut positive[positive_position].1;
                    let negative_mass = &mut negative[negative_position].1;
                    let mass = positive_mass.clone().min(negative_mass.clone());
                    constant = constant.add(&mass.mul(&edge_bound));
                    *positive_mass = positive_mass.sub(&mass);
                    *negative_mass = negative_mass.sub(&mass);
                }
                for (_, mass, lower_bound) in positive.into_iter().chain(negative) {
                    if !mass.is_zero() {
                        constant = constant.add(&mass.mul(&lower_bound?));
                    }
                }
                Some(constant)
            }

            pub(crate) fn polynomial_interval(&self, polynomial: &Polynomial) -> Interval {
                let mut total = Interval::constant(BigInt::zero());
                for (monomial, coefficient) in &polynomial.terms {
                    let mut product = Interval::constant(BigInt::from_i64(1));
                    for (atom, power) in monomial {
                        let base = self.atom_interval(atom);
                        product = product.multiply(&base.correlated_power(*power));
                    }
                    total = total.add(&product.scale(coefficient));
                }
                if let Some((positive, negative, constant)) = polynomial.as_atom_difference() {
                    if let Some(low) = self.engine.matrix_bound(&positive, &negative) {
                        let low = low.add(&constant);
                        total.low = Some(total.low.map_or(low.clone(), |old| old.max(low)));
                    }
                    if let Some(high) = self.engine.matrix_bound(&negative, &positive) {
                        let high = constant.sub(&high);
                        total.high = Some(total.high.map_or(high.clone(), |old| old.min(high)));
                    }
                }
                total
            }

            pub(crate) fn prove_proportional_lower_bound(
                &self,
                goal: &Polynomial,
                bound: &BigInt,
                stored: &Polynomial,
                stored_bound: &BigInt,
            ) -> bool {
                let Some((goal_coefficient, stored_coefficient)) =
                    positive_coefficient_pairs(goal, stored).next()
                else {
                    return false;
                };
                let goal_scale = stored_coefficient.abs();
                let stored_scale = goal_coefficient.abs();
                for (monomial, coefficient) in &goal.terms {
                    if monomial.is_empty() {
                        continue;
                    }
                    let Some(other) = stored.terms.get(monomial) else {
                        return false;
                    };
                    if coefficient.mul(&goal_scale) != other.mul(&stored_scale) {
                        return false;
                    }
                }
                if stored
                    .terms
                    .keys()
                    .any(|monomial| !monomial.is_empty() && !goal.terms.contains_key(monomial))
                {
                    return false;
                }
                let constant = BTreeMap::new();
                let goal_constant = goal.terms.get(&constant).cloned().unwrap_or_default();
                let stored_constant = stored.terms.get(&constant).cloned().unwrap_or_default();
                let offset = goal_constant
                    .mul(&goal_scale)
                    .sub(&stored_constant.mul(&stored_scale));
                stored_bound.mul(&stored_scale).add(&offset) >= bound.mul(&goal_scale)
            }

            pub(crate) fn prove_scaled_lower_bound(
                &self,
                goal: &Polynomial,
                bound: &BigInt,
                stored: &Polynomial,
                stored_bound: &BigInt,
            ) -> bool {
                let Some((goal_coefficient, stored_coefficient)) =
                    positive_coefficient_pairs(goal, stored)
                        .find(|(goal, stored)| goal.abs() != stored.abs())
                else {
                    return false;
                };
                let goal_scale = stored_coefficient.abs();
                let stored_scale = goal_coefficient.abs();
                let Some(scaled_goal) = goal.checked_mul(&Polynomial::constant(goal_scale.clone()))
                else {
                    return false;
                };
                let Some(scaled_stored) =
                    stored.checked_mul(&Polynomial::constant(stored_scale.clone()))
                else {
                    return false;
                };
                let integer_slack = if self.engine.strict_symbol_bindings.is_some()
                    && self.engine.strict_symbol_bindings_valid
                    && !self.engine.proof_integer_formation
                {
                    goal_scale.sub(&BigInt::from_i64(1))
                } else {
                    BigInt::zero()
                };
                self.prove_base_lower_bound(
                    &scaled_goal.sub(&scaled_stored),
                    &bound
                        .mul(&goal_scale)
                        .sub(&stored_bound.mul(&stored_scale))
                        .sub(&integer_slack),
                )
            }

            pub(crate) fn horner_interval(
                &self,
                polynomial: &Polynomial,
                depth: usize,
            ) -> Interval {
                if let Some(constant) = polynomial.constant_value() {
                    return Interval::constant(constant);
                }
                if depth >= 128 {
                    return Interval::unbounded();
                }
                let Some(atom) = polynomial
                    .terms
                    .keys()
                    .find_map(|monomial| monomial.keys().next())
                else {
                    return Interval::unbounded();
                };
                let mut coefficients = BTreeMap::<u32, Polynomial>::new();
                for (monomial, coefficient) in &polynomial.terms {
                    let mut remainder = monomial.clone();
                    let power = remainder.remove(atom).unwrap_or(0);
                    coefficients
                        .entry(power)
                        .or_default()
                        .terms
                        .insert(remainder, coefficient.clone());
                }
                let atom_interval = self.atom_interval(atom);
                let mut powers = coefficients.iter().rev();
                let Some((&highest_power, leading)) = powers.next() else {
                    return Interval::unbounded();
                };
                if highest_power > 128 {
                    return Interval::unbounded();
                }
                let mut previous_power = highest_power;
                let mut interval = self.horner_interval(leading, depth + 1);
                for (&power, coefficient) in powers {
                    interval = interval
                        .multiply(&atom_interval.correlated_power(previous_power - power))
                        .add(&self.horner_interval(coefficient, depth + 1));
                    previous_power = power;
                }
                interval.multiply(&atom_interval.correlated_power(previous_power))
            }
        }

        fn nonconstant_monomials_cmp(left: &Polynomial, right: &Polynomial) -> std::cmp::Ordering {
            left.terms
                .keys()
                .filter(|monomial| !monomial.is_empty())
                .cmp(right.terms.keys().filter(|monomial| !monomial.is_empty()))
        }

        fn positive_coefficient_pairs<'a>(
            goal: &'a Polynomial,
            stored: &'a Polynomial,
        ) -> impl Iterator<Item = (&'a BigInt, &'a BigInt)> {
            goal.terms
                .iter()
                .filter_map(move |(monomial, coefficient)| {
                    if monomial.is_empty() {
                        return None;
                    }
                    let other = stored.terms.get(monomial)?;
                    (!coefficient.is_zero()
                        && !other.is_zero()
                        && coefficient.is_negative() == other.is_negative())
                    .then_some((coefficient, other))
                })
        }
    }
    use crate::proof_contracts::arithmetic_domains::BigIntInterval as Interval;
    pub(crate) use lower_bound_queries::{LowerBoundQueries, PreparedLowerBoundIndex};
    pub(crate) mod conditional_values {
        use super::{BigInt, BinaryOperator, Engine, OpaqueTerm, Polynomial};
        use std::collections::BTreeSet;
        use std::sync::atomic::Ordering;

        pub(crate) type Comparison = (BinaryOperator, Polynomial, Polynomial);

        #[derive(Debug, Clone, PartialEq, Eq)]
        pub(crate) struct ConditionalValueArm {
            pub(crate) conditions: Vec<Comparison>,
            pub(crate) value: Polynomial,
        }

        impl ConditionalValueArm {
            pub(crate) fn visit_operands(&self, mut visit: impl FnMut(&Polynomial)) {
                for (_, left, right) in &self.conditions {
                    visit(left);
                    visit(right);
                }
                visit(&self.value);
            }

            pub(crate) fn mapped(
                &self,
                mut map: impl FnMut(&Polynomial) -> Option<Polynomial>,
            ) -> Option<Self> {
                Some(Self {
                    conditions: self
                        .conditions
                        .iter()
                        .map(|(operator, left, right)| Some((*operator, map(left)?, map(right)?)))
                        .collect::<Option<Vec<_>>>()?,
                    value: map(&self.value)?,
                })
            }
        }

        impl Engine<'_> {
            pub(crate) fn conditional_value(
                &mut self,
                arms: Vec<ConditionalValueArm>,
            ) -> Option<Polynomial> {
                if arms.is_empty() {
                    return None;
                }
                if arms.iter().all(|arm| arm.value == arms[0].value) {
                    return Some(arms[0].value.clone());
                }
                if let Some((atom, _)) = self.opaque_terms.iter().find(|(_, operation)| {
            matches!(operation, OpaqueTerm::Conditional { arms: existing } if existing == &arms)
        }) {
            return Some(Polynomial::atom(atom.clone()));
        }
                let identity = self
                    .denotation_identities
                    .try_update(Ordering::Relaxed, Ordering::Relaxed, |current| {
                        current.checked_add(1)
                    })
                    .ok()?;
                let atom = format!("\0conditional:{identity}");
                self.register_opaque_term(atom.clone(), OpaqueTerm::Conditional { arms });
                Some(Polynomial::atom(atom))
            }

            pub(crate) fn retain_operation_definitions(&mut self, branch: &Self) -> Option<()> {
                if !std::sync::Arc::ptr_eq(
                    &self.denotation_identities,
                    &branch.denotation_identities,
                ) {
                    return None;
                }
                for (atom, operation) in &branch.opaque_terms {
                    self.register_opaque_term(atom.clone(), operation.clone());
                }
                Some(())
            }

            pub(crate) fn charge_conditional_work(&self) -> Option<()> {
                let cost = 1usize
                    .checked_add(self.bounds.len())?
                    .checked_add(self.opaque_terms.len())?;
                self.conditional_work_remaining
                    .try_update(Ordering::Relaxed, Ordering::Relaxed, |remaining| {
                        remaining.checked_sub(cost)
                    })
                    .ok()
                    .map(|_| ())
            }

            pub(crate) fn conditional_lower_bound(
                &self,
                polynomial: &Polynomial,
                bound: &BigInt,
            ) -> Option<bool> {
                if self.conditional_terms.is_empty() {
                    return None;
                }
                let polynomial = self.substituted(polynomial);
                let mut dependencies: BTreeSet<String> = polynomial
                    .terms
                    .keys()
                    .flat_map(|monomial| monomial.keys().cloned())
                    .collect();
                for (atom, operation) in self.opaque_terms.iter().rev() {
                    if dependencies.contains(atom) {
                        operation.visit_operands(|operand| {
                            dependencies.extend(
                                operand
                                    .terms
                                    .keys()
                                    .flat_map(|monomial| monomial.keys().cloned()),
                            );
                        });
                    }
                }
                let (atom, arms) = self.opaque_terms.iter().find_map(|(atom, operation)| {
                    if !dependencies.contains(atom)
                        || self.substituted(&Polynomial::atom(atom.clone()))
                            != Polynomial::atom(atom.clone())
                    {
                        return None;
                    }
                    let OpaqueTerm::Conditional { arms } = operation else {
                        return None;
                    };
                    Some((atom, arms))
                })?;
                Some(arms.iter().all(|arm| {
                    if self.charge_conditional_work().is_none() {
                        return false;
                    }
                    let mut selected = self.clone();
                    selected.harvest_substitution(&Polynomial::atom(atom.clone()), &arm.value);
                    if selected.integer_comparisons_unsatisfiable(arm.conditions.clone()) {
                        return true;
                    }
                    selected.prove_at_least(&selected.substituted(&polynomial), bound)
                }))
            }
        }
    }
    use conditional_values::ConditionalValueArm;
    pub(crate) mod call_values {
        use super::{BinaryOperator, Engine, IntegerApplicationInput, OpaqueTerm, Polynomial};
        use crate::frozen_program::expression_table;
        use std::sync::atomic::Ordering;
        use symbols::SymbolHandle;
        use typed_trees::expression::ExpressionHandle;

        impl Engine<'_> {
            pub(crate) fn refresh_call_congruences(
                &mut self,
                comparisons: &mut Vec<(BinaryOperator, Polynomial, Polynomial)>,
            ) -> bool {
                for position in 0..self.opaque_terms.len() {
                    let (_, operation) = &self.opaque_terms[position];
                    let value = match operation {
                        OpaqueTerm::Call {
                            owner,
                            expression,
                            target,
                            arguments,
                        } => {
                            let normalized = arguments
                                .iter()
                                .map(|input| input.mapped(|value| Some(self.substituted(value))))
                                .collect::<Option<Vec<_>>>();
                            let Some(normalized) = normalized else {
                                return false;
                            };
                            if normalized == *arguments {
                                continue;
                            }
                            let (owner, expression, target) = (*owner, *expression, *target);
                            self.selected_call_value(owner, expression, target, normalized)
                        }
                        OpaqueTerm::DeclarationApplication { measure, input } => {
                            let Some(normalized) =
                                input.mapped(|value| Some(self.substituted(value)))
                            else {
                                return false;
                            };
                            if normalized == *input {
                                continue;
                            }
                            self.declared_application_value(*measure, normalized)
                        }
                        _ => continue,
                    };
                    let atom = self.opaque_terms[position].0.clone();
                    let Some(value) = value else {
                        return false;
                    };
                    let previous = self.substituted(&Polynomial::atom(atom.clone()));
                    let canonical = self.substituted(&value);
                    if previous == canonical {
                        continue;
                    }
                    self.harvest_substitution(&canonical, &previous);
                    comparisons.push((BinaryOperator::Equal, previous, canonical));
                }
                true
            }

            pub(crate) fn declared_application_value(
                &mut self,
                measure: SymbolHandle,
                input: impl Into<IntegerApplicationInput>,
            ) -> Option<Polynomial> {
                self.program
                    .measures()
                    .iter()
                    .find(|definition| definition.symbol == measure)?;
                let input = input.into().mapped(|value| Some(self.substituted(value)))?;
                if let Some((atom, _)) = self.opaque_terms.iter().find(|(_, operation)| {
            matches!(operation, OpaqueTerm::DeclarationApplication { measure: existing, input: value }
                if *existing == measure && *value == input)
        }) { return Some(Polynomial::atom(atom.clone())); }
                let identity = self
                    .denotation_identities
                    .try_update(Ordering::Relaxed, Ordering::Relaxed, |current| {
                        current.checked_add(1)
                    })
                    .ok()?;
                let atom = format!("\0declared-application:{identity}");
                self.register_opaque_term(
                    atom.clone(),
                    OpaqueTerm::DeclarationApplication { measure, input },
                );
                Some(Polynomial::atom(atom))
            }

            pub(crate) fn selected_call_value(
                &mut self,
                owner: SymbolHandle,
                expression: ExpressionHandle,
                target: SymbolHandle,
                arguments: Vec<IntegerApplicationInput>,
            ) -> Option<Polynomial> {
                if !owner.is_valid() || !target.is_valid() {
                    return None;
                }
                let call = expression_table(self.program).call_node(expression)?;
                let selected = super::super::specification_calls::selected_call_contract(
                    self.program,
                    owner,
                    call,
                )?;
                if super::super::specification_calls::owner_symbol(&selected) != target
                    || expression_table(self.program)
                        .expression_handles(call.arguments)
                        .len()
                        != arguments.len()
                {
                    return None;
                }
                let arguments = arguments
                    .into_iter()
                    .map(|input| input.mapped(|value| Some(self.substituted(value))))
                    .collect::<Option<Vec<_>>>()?;
                if let Some((atom, _)) = self.opaque_terms.iter().find(|(_, operation)| {
            matches!(operation, OpaqueTerm::Call { owner: existing_owner, expression: existing_expression,
                target: existing_target, arguments: existing_arguments }
                if *existing_owner == owner && *existing_expression == expression
                && *existing_target == target && *existing_arguments == arguments)
        }) { return Some(Polynomial::atom(atom.clone())); }
                let identity = self
                    .denotation_identities
                    .try_update(Ordering::Relaxed, Ordering::Relaxed, |current| {
                        current.checked_add(1)
                    })
                    .ok()?;
                let atom = format!("\0applied-call:{identity}");
                self.register_opaque_term(
                    atom.clone(),
                    OpaqueTerm::Call {
                        owner,
                        expression,
                        target,
                        arguments,
                    },
                );
                Some(Polynomial::atom(atom))
            }
        }
    }
    pub(crate) mod captured_calls {
        use super::super::scoped_arithmetic::{
            ScopedArithmeticBinder, ScopedArithmeticBinding, ScopedArithmeticExpression,
            ScopedArithmeticValue, calls::ScopedCalls, install_hypotheses,
        };
        use super::{Engine, IntegerApplicationInput, Polynomial};
        use crate::frozen_program::expression_table;
        use typed_trees::expression::{BinaryOperator, ExpressionHandle, ExpressionNode};

        impl Engine<'_> {
            pub(crate) fn complete_formed_call(
                &mut self,
                expression: ExpressionHandle,
                arguments: &[(ExpressionHandle, IntegerApplicationInput)],
                result: &Polynomial,
            ) -> bool {
                let mut remaining = 4096usize;
                let Some(call) = expression_table(self.program).call_node(expression) else {
                    return false;
                };
                let Some(owner) = super::super::specification_calls::selected_call_contract(
                    self.program,
                    self.source_owner,
                    call,
                ) else {
                    return false;
                };
                let parameters =
                    super::super::specification_calls::owner_parameters(self.program, &owner);
                if parameters.len() != arguments.len() {
                    return false;
                }
                let mut actuals = Vec::new();
                for (parameter, (source, input)) in parameters.iter().zip(arguments) {
                    let Some(mut bindings) = input.scoped_bindings(parameter.symbol, |value| {
                        captured_polynomial(value, &self.unsigned_atoms, &mut remaining)
                    }) else {
                        return false;
                    };
                    let Some(root) = bindings.first_mut() else {
                        return false;
                    };
                    root.binder = ScopedArithmeticBinder::Occurrence(*source);
                    actuals.extend(bindings);
                }
                let Some(result) =
                    captured_polynomial(result, &self.unsigned_atoms, &mut remaining)
                else {
                    return false;
                };
                let mut calls = self.captured_calls.take().unwrap_or_else(|| {
                    ScopedCalls::for_declaration(self.program, self.machine_symbol)
                });
                let hypotheses =
                    calls.formed_call_guarantees(self.source_owner, expression, &actuals, result);
                self.captured_calls = Some(calls);
                let Some(hypotheses) = hypotheses else {
                    return false;
                };
                let previous_owner = self.source_owner;
                let previous_types = self.source_type_bindings.clone();
                let previous_formals = self.formal_arguments.take();
                let previous_symbols = self.strict_symbol_bindings.clone();
                let previous_result = self.strict_result_binding.clone();
                let previous_occurrences = self.strict_occurrences.clone();
                let previous_reads = self.formal_read_arguments.clone();
                let previous_owned = self.owned_arguments.clone();
                let previous_conditions = std::mem::take(&mut self.saved_conditions);
                let accepted = install_hypotheses(self.program, self, &hypotheses);
                self.source_owner = previous_owner;
                self.source_type_bindings = previous_types;
                self.formal_arguments = previous_formals;
                self.strict_symbol_bindings = previous_symbols;
                self.strict_result_binding = previous_result;
                self.strict_occurrences = previous_occurrences;
                self.formal_read_arguments = previous_reads;
                self.owned_arguments = previous_owned;
                self.saved_conditions = previous_conditions;
                accepted
            }

            pub(crate) fn capture_contract_call_actuals(
                &mut self,
                expression: ExpressionHandle,
                supplied: &[ScopedArithmeticBinding],
                remaining: &mut usize,
            ) -> Option<Vec<ScopedArithmeticBinding>> {
                let call = expression_table(self.program).call_node(expression)?;
                let owner = super::super::specification_calls::selected_call_contract(
                    self.program,
                    self.source_owner,
                    call,
                )?;
                let parameters =
                    super::super::specification_calls::owner_parameters(self.program, &owner);
                let arguments = expression_table(self.program).expression_handles(call.arguments);
                if parameters.len() != arguments.len() {
                    return None;
                }
                let mut actuals = supplied.to_vec();
                for (parameter, argument) in parameters.iter().zip(arguments) {
                    if parameter.is_mutable
                        || actuals.iter().any(|binding| {
                            binding.binder == ScopedArithmeticBinder::Occurrence(*argument)
                        })
                    {
                        continue;
                    }
                    let captured = (|| {
                        let required = self.call_input_type(*argument, parameter.type_reference)?;
                        let input = if self
                            .program
                            .primitive_type_reference(parameter.type_reference)
                            .is_some()
                        {
                            self.contract_actual_is_captured(*argument, remaining)
                                .then_some(())?;
                            IntegerApplicationInput::Scalar(self.normalize(*argument)?)
                        } else {
                            self.captured_record_call_input(*argument, parameters, arguments)?
                        };
                        if !crate::has_anonymous_numeric_results(self.program, *argument) {
                            let actual = match &input {
                                IntegerApplicationInput::Scalar(_) => {
                                    self.source_result_type(*argument)?
                                }
                                IntegerApplicationInput::Record { type_reference, .. } => {
                                    *type_reference
                                }
                            };
                            if !crate::declared_input_type_matches(self.program, actual, required) {
                                return None;
                            }
                        }
                        let mut bindings = input.scoped_bindings(parameter.symbol, |value| {
                            captured_polynomial(value, &self.unsigned_atoms, remaining)
                        })?;
                        bindings.first_mut()?.binder =
                            ScopedArithmeticBinder::Occurrence(*argument);
                        Some(bindings)
                    })();
                    if let Some(bindings) = captured {
                        actuals.extend(bindings);
                    }
                }
                Some(actuals)
            }

            fn contract_actual_is_captured(
                &self,
                expression: ExpressionHandle,
                remaining: &mut usize,
            ) -> bool {
                let mut pending = vec![expression];
                while let Some(expression) = pending.pop() {
                    let Some(next) = remaining.checked_sub(1) else {
                        return false;
                    };
                    *remaining = next;
                    if self
                        .strict_occurrences
                        .iter()
                        .any(|(bound, _)| *bound == expression)
                        || self.formal_coordinate_value(expression).is_some()
                    {
                        continue;
                    }
                    let node = expression_table(self.program).expression(expression);
                    match node {
                        ExpressionNode::Name(name) => {
                            if self.strict_symbol_value(name.symbol).is_none()
                                && !(crate::reserved_result_owner(self.program, expression)
                                    .is_some()
                                    && self.strict_result_binding.is_some())
                                && self
                                    .program
                                    .closed_integer_value_in(expression, self.source_owner)
                                    .is_none()
                            {
                                return false;
                            }
                        }
                        ExpressionNode::Member(_)
                        | ExpressionNode::Indexed(_)
                        | ExpressionNode::Call(_) => {
                            if self
                                .program
                                .closed_integer_value_in(expression, self.source_owner)
                                .is_none()
                            {
                                return false;
                            }
                        }
                        _ => crate::queries::expression_traversal::children(
                            self.program,
                            node,
                            |child| pending.push(child),
                        ),
                    }
                }
                true
            }

            pub(crate) fn capture_expression_calls(
                &mut self,
                expression: ExpressionHandle,
            ) -> bool {
                let Some(symbols) = self.strict_symbol_bindings.as_ref() else {
                    return false;
                };
                let mut bindings = Vec::new();
                let mut remaining = 4096usize;
                for (symbol, value) in symbols {
                    let Some(value) =
                        captured_polynomial(value, &self.unsigned_atoms, &mut remaining)
                    else {
                        return false;
                    };
                    bindings.push(ScopedArithmeticBinding {
                        binder: ScopedArithmeticBinder::Symbol(*symbol),
                        value,
                    });
                }
                for (occurrence, value) in &self.strict_occurrences {
                    let Some(value) =
                        captured_polynomial(value, &self.unsigned_atoms, &mut remaining)
                    else {
                        return false;
                    };
                    bindings.push(ScopedArithmeticBinding {
                        binder: ScopedArithmeticBinder::Occurrence(*occurrence),
                        value,
                    });
                }
                let mut pending = vec![(expression, false, 0usize)];
                while let Some((operand, visited, depth)) = pending.pop() {
                    let Some(next) = remaining.checked_sub(1) else {
                        return false;
                    };
                    remaining = next;
                    if depth >= 64 {
                        return false;
                    }
                    let node = expression_table(self.program).expression(operand);
                    if !visited {
                        pending.push((operand, true, depth));
                        crate::expression_traversal::children(self.program, node, |child| {
                            pending.push((child, false, depth + 1))
                        });
                        continue;
                    }
                    let ExpressionNode::Call(call) = node else {
                        continue;
                    };
                    let Some(owner) = super::super::specification_calls::selected_call_contract(
                        self.program,
                        self.source_owner,
                        call,
                    ) else {
                        continue;
                    };
                    let parameters =
                        super::super::specification_calls::owner_parameters(self.program, &owner);
                    let arguments =
                        expression_table(self.program).expression_handles(call.arguments);
                    if parameters.len() != arguments.len() {
                        return false;
                    }
                    for (parameter, argument) in parameters.iter().zip(arguments) {
                        if !self
                            .program
                            .primitive_type_reference(parameter.type_reference)
                            .is_some_and(|primitive| primitive.is_fixed_integer())
                            || bindings.iter().any(|binding| {
                                binding.binder == ScopedArithmeticBinder::Occurrence(*argument)
                            })
                        {
                            continue;
                        }
                        let Some(argument_bindings) =
                            demanded_bindings(self.program, *argument, &bindings, &mut remaining)
                        else {
                            return false;
                        };
                        bindings.push(ScopedArithmeticBinding {
                            binder: ScopedArithmeticBinder::Occurrence(*argument),
                            value: ScopedArithmeticValue::Term(ScopedArithmeticExpression {
                                owner: self.source_owner,
                                expression: *argument,
                                bindings: argument_bindings,
                            }),
                        });
                    }
                }
                let source = ScopedArithmeticExpression {
                    owner: self.source_owner,
                    expression,
                    bindings,
                };
                let mut calls = self.captured_calls.take().unwrap_or_else(|| {
                    ScopedCalls::for_declaration(self.program, self.machine_symbol)
                });
                let prepared = calls.expression(&source);
                let hypotheses = calls.hypotheses(&[]);
                self.captured_calls = Some(calls);
                let (Some(prepared), Some(hypotheses)) = (prepared, hypotheses) else {
                    return false;
                };
                let previous_owner = self.source_owner;
                let previous_symbols = self.strict_symbol_bindings.clone();
                let previous_result = self.strict_result_binding.clone();
                let previous_occurrences = self.strict_occurrences.clone();
                let previous_reads = self.formal_read_arguments.clone();
                let previous_owned = self.owned_arguments.clone();
                let previous_conditions = std::mem::take(&mut self.saved_conditions);
                let prepared_occurrences = self
                    .install_scoped_expression(&prepared)
                    .then(|| self.strict_occurrences.clone());
                let accepted = prepared_occurrences.is_some()
                    && install_hypotheses(self.program, self, &hypotheses);
                self.source_owner = previous_owner;
                self.strict_symbol_bindings = previous_symbols;
                self.strict_result_binding = previous_result;
                self.strict_occurrences = previous_occurrences;
                self.formal_read_arguments = previous_reads;
                self.owned_arguments = previous_owned;
                self.saved_conditions = previous_conditions;
                if !accepted {
                    return false;
                }
                for (occurrence, value) in prepared_occurrences.into_iter().flatten() {
                    if !self.bind_strict_occurrence(occurrence, value) {
                        return false;
                    }
                }
                true
            }
        }

        fn demanded_bindings(
            program: &dyn crate::CheckingInput,
            expression: ExpressionHandle,
            bindings: &[ScopedArithmeticBinding],
            remaining: &mut usize,
        ) -> Option<Vec<ScopedArithmeticBinding>> {
            let mut selected = Vec::new();
            let mut pending = vec![expression];
            while let Some(expression) = pending.pop() {
                *remaining = remaining.checked_sub(1)?;
                let occurrence = ScopedArithmeticBinder::Occurrence(expression);
                if let Some(binding) = bindings.iter().find(|binding| binding.binder == occurrence)
                {
                    if !selected
                        .iter()
                        .any(|candidate: &ScopedArithmeticBinding| candidate.binder == occurrence)
                    {
                        selected.push(binding.clone());
                    }
                    continue;
                }
                let node = expression_table(program).expression(expression);
                if let ExpressionNode::Name(name) = node {
                    let binder = ScopedArithmeticBinder::Symbol(name.symbol);
                    if let Some(binding) = bindings.iter().find(|binding| binding.binder == binder)
                        && !selected.iter().any(|candidate| candidate.binder == binder)
                    {
                        selected.push(binding.clone());
                    }
                }
                crate::queries::expression_traversal::children(program, node, |child| {
                    pending.push(child)
                });
            }
            Some(selected)
        }

        fn captured_polynomial(
            polynomial: &Polynomial,
            unsigned: &[String],
            remaining: &mut usize,
        ) -> Option<ScopedArithmeticValue> {
            let mut sum = ScopedArithmeticValue::Integer(super::super::BigInt::zero());
            for (monomial, coefficient) in &polynomial.terms {
                *remaining = remaining.checked_sub(1)?;
                let mut term = ScopedArithmeticValue::Integer(coefficient.clone());
                for (identity, power) in monomial {
                    let atom = ScopedArithmeticValue::Atom {
                        identity: identity.clone(),
                        unsigned: unsigned.contains(identity),
                    };
                    for _ in 0..*power {
                        *remaining = remaining.checked_sub(1)?;
                        term = ScopedArithmeticValue::IntegerOperation {
                            operator: BinaryOperator::Multiply,
                            left: Box::new(term),
                            right: Box::new(atom.clone()),
                        };
                    }
                }
                sum = ScopedArithmeticValue::IntegerOperation {
                    operator: BinaryOperator::Add,
                    left: Box::new(sum),
                    right: Box::new(term),
                };
            }
            Some(sum)
        }
    }
    pub(crate) mod mathematical_terms {
        use super::{Engine, Judgment, Polynomial};
        use crate::mathematical_applications::application_spine;
        use crate::mathematical_applications::{PreparedConstantMeaning, PreparedMathematicalView};
        use proof_admission::{Term, TermHandle};
        use typed_trees::expression::{BinaryOperator, ExpressionHandle};

        impl Engine<'_> {
            pub(crate) fn judge_mathematical_application(
                &mut self,
                expression: ExpressionHandle,
            ) -> Judgment {
                if super::super::struct_trace() {
                    eprintln!(
                        "STRUCT mathematical expression={expression:?} prepared={}",
                        self.program.prepared_mathematics().is_some()
                    );
                }
                let Some(view) = self.program.prepared_mathematics() else {
                    return unknown();
                };
                let Some(application) = view.application(expression) else {
                    return unknown();
                };
                if super::super::struct_trace() {
                    eprintln!(
                        "STRUCT mathematical term={:?} captures={:?}",
                        view.arena.get(application.term),
                        view.applications
                            .captures
                            .span_or_empty(application.captures)
                    );
                }
                let captures = view
                    .applications
                    .captures
                    .span_or_empty(application.captures)
                    .iter()
                    .map(|capture| Some(capture.expression))
                    .collect::<Vec<_>>();
                self.judge_mathematical_term(view, application.term, &captures, 0)
            }

            pub(crate) fn collect_mathematical_comparisons(
                &mut self,
                expression: ExpressionHandle,
                comparisons: &mut Vec<(BinaryOperator, Polynomial, Polynomial)>,
            ) -> bool {
                let Some(view) = self.program.prepared_mathematics() else {
                    return false;
                };
                let Some(application) = view.application(expression) else {
                    return false;
                };
                let captures = view
                    .applications
                    .captures
                    .span_or_empty(application.captures)
                    .iter()
                    .map(|capture| Some(capture.expression))
                    .collect::<Vec<_>>();
                self.collect_mathematical_term(view, application.term, &captures, comparisons, 0)
            }

            pub(crate) fn mathematical_comparison(
                &mut self,
                expression: ExpressionHandle,
            ) -> Option<(BinaryOperator, Polynomial, Polynomial)> {
                let view = self.program.prepared_mathematics()?;
                let application = view.application(expression)?;
                let captures = view
                    .applications
                    .captures
                    .span_or_empty(application.captures)
                    .iter()
                    .map(|capture| Some(capture.expression))
                    .collect::<Vec<_>>();
                self.term_comparison(view, application.term, &captures, 0)
            }

            pub(crate) fn normalize_mathematical_application(
                &mut self,
                expression: ExpressionHandle,
            ) -> Option<Polynomial> {
                let view = self.program.prepared_mathematics()?;
                let application = view.application(expression)?;
                let captures = view
                    .applications
                    .captures
                    .span_or_empty(application.captures)
                    .iter()
                    .map(|capture| Some(capture.expression))
                    .collect::<Vec<_>>();
                self.normalize_mathematical_term(view, application.term, &captures, 0)
            }

            fn collect_mathematical_term(
                &mut self,
                view: PreparedMathematicalView<'_>,
                term: TermHandle,
                captures: &[Option<ExpressionHandle>],
                comparisons: &mut Vec<(BinaryOperator, Polynomial, Polynomial)>,
                depth: usize,
            ) -> bool {
                if depth >= 128 {
                    return false;
                }
                match view.arena.get(term) {
                    Term::Squash { ty } => {
                        self.collect_mathematical_term(view, ty, captures, comparisons, depth + 1)
                    }
                    Term::Sigma { domain, codomain }
                        if !matches!(view.arena.get(domain), Term::Two) =>
                    {
                        let mut extended = captures.to_vec();
                        extended.push(None);
                        let left = self.collect_mathematical_term(
                            view,
                            domain,
                            captures,
                            comparisons,
                            depth + 1,
                        );
                        let right = self.collect_mathematical_term(
                            view,
                            codomain,
                            &extended,
                            comparisons,
                            depth + 1,
                        );
                        left && right
                    }
                    _ => {
                        if let Some(comparison) =
                            self.term_comparison(view, term, captures, depth + 1)
                        {
                            comparisons.push(comparison);
                            true
                        } else {
                            false
                        }
                    }
                }
            }

            fn judge_mathematical_term(
                &mut self,
                view: PreparedMathematicalView<'_>,
                term: TermHandle,
                captures: &[Option<ExpressionHandle>],
                depth: usize,
            ) -> Judgment {
                if depth >= 128 {
                    return unknown();
                }
                match view.arena.get(term) {
                    Term::Squash { ty } => {
                        self.judge_mathematical_term(view, ty, captures, depth + 1)
                    }
                    Term::Id { ty, left, right } if matches!(view.arena.get(ty), Term::Two) => {
                        match (view.arena.get(left), view.arena.get(right)) {
                            (Term::TwoZero, Term::TwoZero) | (Term::TwoOne, Term::TwoOne) => {
                                Judgment::Proven
                            }
                            (Term::TwoZero, Term::TwoOne) | (Term::TwoOne, Term::TwoZero) => {
                                Judgment::ConstantFalse
                            }
                            _ => unknown(),
                        }
                    }
                    Term::Id { ty, left, right }
                        if self.is_identity_carrier(view, ty)
                            && same_term(view, left, right, 0) =>
                    {
                        Judgment::Proven
                    }
                    Term::Sigma { domain, codomain } => {
                        let mut extended = captures.to_vec();
                        extended.push(None);
                        if matches!(view.arena.get(domain), Term::Two) {
                            let Term::CaseTwo {
                                zero_branch,
                                one_branch,
                                ..
                            } = view.arena.get(codomain)
                            else {
                                return unknown();
                            };
                            alternative(
                                self.judge_mathematical_term(
                                    view,
                                    zero_branch,
                                    &extended,
                                    depth + 1,
                                ),
                                self.judge_mathematical_term(
                                    view,
                                    one_branch,
                                    &extended,
                                    depth + 1,
                                ),
                            )
                        } else {
                            conjunction(
                                self.judge_mathematical_term(view, domain, captures, depth + 1),
                                self.judge_mathematical_term(view, codomain, &extended, depth + 1),
                            )
                        }
                    }
                    _ => match self.term_comparison(view, term, captures, depth + 1) {
                        Some((operator, left, right)) => {
                            self.judge_comparison(operator, left, right)
                        }
                        None => unknown(),
                    },
                }
            }

            fn is_identity_carrier(
                &self,
                view: PreparedMathematicalView<'_>,
                ty: TermHandle,
            ) -> bool {
                let Term::Constant { declaration, .. } = view.arena.get(ty) else {
                    return false;
                };
                matches!(
                    view.constant(declaration),
                    Some(
                        PreparedConstantMeaning::IntegerCarrier
                            | PreparedConstantMeaning::AddressCarrier
                            | PreparedConstantMeaning::BooleanCarrier
                    )
                )
            }

            fn term_comparison(
                &mut self,
                view: PreparedMathematicalView<'_>,
                term: TermHandle,
                captures: &[Option<ExpressionHandle>],
                depth: usize,
            ) -> Option<(BinaryOperator, Polynomial, Polynomial)> {
                if depth >= 128 {
                    return None;
                }
                if let Term::Squash { ty } = view.arena.get(term) {
                    return self.term_comparison(view, ty, captures, depth + 1);
                }
                if let Term::Id { ty, left, right } = view.arena.get(term) {
                    if !self.is_identity_carrier(view, ty) {
                        return None;
                    }
                    return Some((
                        BinaryOperator::Equal,
                        self.normalize_mathematical_term(view, left, captures, depth + 1)?,
                        self.normalize_mathematical_term(view, right, captures, depth + 1)?,
                    ));
                }
                let (declaration, arguments) = application_spine(view, term)?;
                match (view.constant(declaration)?, arguments.as_slice()) {
                    (PreparedConstantMeaning::IntegerRelation(operator), [left, right]) => Some((
                        *operator,
                        self.normalize_mathematical_term(view, *left, captures, depth + 1)?,
                        self.normalize_mathematical_term(view, *right, captures, depth + 1)?,
                    )),
                    (PreparedConstantMeaning::Negation, [proposition]) => {
                        let (operator, left, right) =
                            self.term_comparison(view, *proposition, captures, depth + 1)?;
                        Some((operator.complement()?, left, right))
                    }
                    _ => None,
                }
            }

            fn normalize_mathematical_term(
                &mut self,
                view: PreparedMathematicalView<'_>,
                term: TermHandle,
                captures: &[Option<ExpressionHandle>],
                depth: usize,
            ) -> Option<Polynomial> {
                if depth >= 128 {
                    return None;
                }
                if let Term::Variable(index) = view.arena.get(term) {
                    let position = captures.len().checked_sub(index as usize + 1)?;
                    let expression = captures[position]?;
                    return self
                        .normalize(expression)
                        .or_else(|| self.normalize_integer_embedding(expression));
                }
                let (declaration, arguments) = application_spine(view, term)?;
                match (view.constant(declaration)?, arguments.as_slice()) {
                    (PreparedConstantMeaning::Integer(value), []) => {
                        Some(Polynomial::constant(value.clone()))
                    }
                    (PreparedConstantMeaning::AddressBound(symbol), [])
                        if self.program.symbols.builtin_type_member(*symbol)
                            == Some(symbols::BuiltinTypeMember::AddressBound) =>
                    {
                        self.address_model_bound()
                    }
                    (PreparedConstantMeaning::IntegerOperation(operator), [left, right]) => {
                        let left =
                            self.normalize_mathematical_term(view, *left, captures, depth + 1)?;
                        let right =
                            self.normalize_mathematical_term(view, *right, captures, depth + 1)?;
                        match operator {
                            BinaryOperator::Add => Some(left.add(&right)),
                            BinaryOperator::Subtract => Some(left.sub(&right)),
                            BinaryOperator::Multiply => left.checked_mul(&right),
                            _ => None,
                        }
                    }
                    (PreparedConstantMeaning::IntegerEmbedding { interval, .. }, [argument]) => {
                        let value =
                            self.normalize_mathematical_term(view, *argument, captures, depth + 1)?;
                        self.bounds
                            .push((value.clone(), interval.low.as_ref()?.clone()));
                        if let Some(maximum) = &interval.high {
                            self.bounds.push((value.neg(), maximum.negate()));
                        } else {
                            let bound = self.address_model_bound()?;
                            self.bounds
                                .push((bound.sub(&value), numerics::bignum::BigInt::from_i64(1)));
                        }
                        self.refresh_difference_bounds();
                        Some(value)
                    }
                    _ => None,
                }
            }
        }

        fn same_term(
            view: PreparedMathematicalView<'_>,
            left: TermHandle,
            right: TermHandle,
            depth: usize,
        ) -> bool {
            if left == right {
                return true;
            }
            if depth >= 128 {
                return false;
            }
            match (view.arena.get(left), view.arena.get(right)) {
                (Term::Variable(left), Term::Variable(right)) => left == right,
                (
                    Term::Constant {
                        declaration: left,
                        levels: left_levels,
                    },
                    Term::Constant {
                        declaration: right,
                        levels: right_levels,
                    },
                ) => left == right && left_levels == right_levels,
                (
                    Term::Apply {
                        function: left,
                        argument: left_argument,
                    },
                    Term::Apply {
                        function: right,
                        argument: right_argument,
                    },
                ) => {
                    same_term(view, left, right, depth + 1)
                        && same_term(view, left_argument, right_argument, depth + 1)
                }
                _ => false,
            }
        }

        fn unknown() -> Judgment {
            Judgment::Unknown {
                goal_in_language: false,
            }
        }
        fn conjunction(left: Judgment, right: Judgment) -> Judgment {
            match (left, right) {
                (Judgment::ConstantFalse, _) | (_, Judgment::ConstantFalse) => {
                    Judgment::ConstantFalse
                }
                (Judgment::Refuted, _) | (_, Judgment::Refuted) => Judgment::Refuted,
                (Judgment::Proven, Judgment::Proven) => Judgment::Proven,
                _ => unknown(),
            }
        }
        fn alternative(left: Judgment, right: Judgment) -> Judgment {
            match (left, right) {
                (Judgment::Proven, _) | (_, Judgment::Proven) => Judgment::Proven,
                (
                    Judgment::ConstantFalse | Judgment::Refuted,
                    Judgment::ConstantFalse | Judgment::Refuted,
                ) => Judgment::Refuted,
                _ => unknown(),
            }
        }
    }
    pub(crate) mod strict_bindings {
        use super::super::{
            BigInt, BinaryOperator, ExpressionHandle, ExpressionNode, Machine, SymbolHandle,
        };
        use super::{Engine, Interval, OpaqueTerm, Polynomial};
        use crate::frozen_program::expression_table;
        use crate::proof_contracts::arithmetic_domains::DispatchSelection;
        use crate::{
            StrictArithmeticBindingValue, StrictArithmeticExpressionBinding,
            StrictArithmeticSymbolBinding,
        };
        use typed_trees::expression::UnaryOperator;

        #[derive(Clone, PartialEq, Eq)]
        pub(crate) struct AdmittedIntegerRemainder {
            dividend: Polynomial,
            divisor: Polynomial,
            value: Polynomial,
        }

        impl<'program> Engine<'program> {
            pub(crate) fn with_formal_arguments<Output>(
                &mut self,
                owner: SymbolHandle,
                arguments: &[(SymbolHandle, Polynomial)],
                query: impl FnOnce(&mut Self) -> Option<Output>,
            ) -> Option<Output> {
                if !owner.is_valid() || arguments.iter().any(|(symbol, _)| !symbol.is_valid()) {
                    return None;
                }
                let previous_owner = self.source_owner;
                let previous_arguments = self.formal_arguments.replace(arguments.to_vec());
                let previous_occurrences = std::mem::take(&mut self.strict_occurrences);
                let previous_reads = std::mem::take(&mut self.formal_read_arguments);
                let previous_owned = std::mem::take(&mut self.owned_arguments);
                let previous_conditions = std::mem::take(&mut self.saved_conditions);
                self.source_owner = owner;
                let value = query(self);
                self.source_owner = previous_owner;
                self.formal_arguments = previous_arguments;
                self.strict_occurrences = previous_occurrences;
                self.formal_read_arguments = previous_reads;
                self.owned_arguments = previous_owned;
                self.saved_conditions = previous_conditions;
                value
            }

            pub(crate) fn integer_value_fit(
                &mut self,
                value: &Polynomial,
                minimum: &BigInt,
                maximum: &Polynomial,
                maximum_is_exclusive: bool,
                target_address_model: bool,
            ) -> super::super::operand_fits::CarrierFit {
                use super::super::operand_fits::CarrierFit;
                if self.requires_unsatisfiable {
                    return CarrierFit::Unknown;
                }
                let value = self.substituted(value);
                let maximum = self.substituted(maximum);
                if self.prove_at_least(&value, minimum)
                    && self.prove_at_least(
                        &maximum.sub(&value),
                        &BigInt::from_i64(i64::from(maximum_is_exclusive)),
                    )
                {
                    return CarrierFit::Proven;
                }
                if self.prove_at_least(
                    &Polynomial::constant(minimum.clone()).sub(&value),
                    &BigInt::from_i64(1),
                ) || self.prove_at_least(
                    &value.sub(&maximum),
                    &BigInt::from_i64(i64::from(!maximum_is_exclusive)),
                ) {
                    return CarrierFit::Refuted;
                }
                if target_address_model
                    && maximum_is_exclusive
                    && minimum == &BigInt::zero()
                    && self
                        .address_model_bound()
                        .is_some_and(|bound| bound == maximum)
                    && let Some(value) = value.constant_value()
                    && value.to_u64().is_some()
                {
                    return CarrierFit::Pending {
                        interval: Interval::constant(value),
                    };
                }
                CarrierFit::Unknown
            }

            pub(crate) fn strict_for_declaration(
                program: &'program dyn crate::CheckingInput,
                owner: SymbolHandle,
            ) -> Self {
                let mut engine = Self::for_explicit_bindings(program);
                engine.machine_symbol = owner;
                engine.source_owner = owner;
                engine
            }

            pub(crate) fn strict(
                program: &'program dyn crate::CheckingInput,
                machine: &Machine,
                bindings: &[StrictArithmeticSymbolBinding],
            ) -> Self {
                let mut engine = Self::for_owner(program, machine.symbol, None);
                let mut resolved = Vec::with_capacity(bindings.len());
                for binding in bindings {
                    let polynomial = match &binding.value {
                        StrictArithmeticBindingValue::Atom { identity, unsigned } => {
                            engine.declare_atom(identity, *unsigned);
                            Polynomial::atom(identity.clone())
                        }
                        StrictArithmeticBindingValue::Integer(value) => {
                            Polynomial::constant(value.clone())
                        }
                    };
                    if let Some((_, existing)) = resolved
                        .iter()
                        .find(|(symbol, _)| *symbol == binding.symbol)
                    {
                        if existing != &polynomial {
                            engine.strict_symbol_bindings_valid = false;
                            return engine;
                        }
                        continue;
                    }
                    resolved.push((binding.symbol, polynomial));
                }
                engine.strict_symbol_bindings = Some(resolved);
                engine
            }

            pub(crate) fn bind_matched_integer_subject(
                &mut self,
                expression: ExpressionHandle,
                value: BigInt,
            ) {
                if let Some(symbol) = crate::single_segment_name_symbol(self.program, expression) {
                    self.replace_strict_symbol(symbol, Polynomial::constant(value));
                    return;
                }
                if !matches!(
                    expression_table(self.program).expression(expression),
                    ExpressionNode::Member(_)
                ) {
                    return;
                }
                let atom = format!(
                    "\0{}",
                    super::integer_source_identity(self.program, expression)
                );
                self.substitutions.insert(atom, Polynomial::constant(value));
            }

            fn replace_strict_symbol(&mut self, symbol: SymbolHandle, value: Polynomial) {
                let Some(bindings) = &mut self.strict_symbol_bindings else {
                    return;
                };
                if let Some((_, existing)) = bindings.iter_mut().find(|(bound, _)| *bound == symbol)
                {
                    *existing = value;
                    return;
                }
                bindings.push((symbol, value));
            }

            pub(crate) fn strict_symbol_bindings_are_valid(&self) -> bool {
                self.strict_symbol_bindings_valid
            }

            pub(crate) fn strict_symbol_value(&self, symbol: SymbolHandle) -> Option<Polynomial> {
                if !self.strict_symbol_bindings_valid {
                    return None;
                }
                self.strict_symbol_bindings
                    .as_ref()?
                    .iter()
                    .find(|(bound, _)| *bound == symbol)
                    .map(|(_, value)| value.clone())
            }

            pub(crate) fn closed_symbol_bindings(
                &self,
            ) -> Option<Vec<StrictArithmeticSymbolBinding>> {
                if !self.strict_symbol_bindings_valid {
                    return None;
                }
                Some(
                    self.strict_symbol_bindings
                        .iter()
                        .flatten()
                        .filter_map(|(symbol, value)| {
                            Some(StrictArithmeticSymbolBinding {
                                symbol: *symbol,
                                value: StrictArithmeticBindingValue::Integer(
                                    value.constant_value()?,
                                ),
                            })
                        })
                        .collect(),
                )
            }

            pub(crate) fn normalize_scoped_value(
                &mut self,
                value: &crate::ScopedArithmeticValue,
            ) -> Option<Polynomial> {
                use crate::ScopedArithmeticValue;
                Some(match value {
                    ScopedArithmeticValue::CapturedInteger(denotation) => {
                        let leaves = denotation
                            .leaf_atoms()
                            .iter()
                            .map(|identity| {
                                self.declare_atom(identity, false);
                                (identity.clone(), Polynomial::atom(identity.clone()))
                            })
                            .collect();
                        self.instantiate_integer_denotation(denotation, &leaves)?
                    }
                    ScopedArithmeticValue::TypeReference(_)
                    | ScopedArithmeticValue::OwnedSnapshot(_) => {
                        return None;
                    }
                    ScopedArithmeticValue::Atom { identity, unsigned } => {
                        self.declare_atom(identity, *unsigned);
                        Polynomial::atom(identity.clone())
                    }
                    ScopedArithmeticValue::BoundedInteger { value, interval } => {
                        let polynomial = self.normalize_scoped_value(value)?;
                        if let Some(minimum) = &interval.low {
                            self.bounds.push((polynomial.clone(), minimum.clone()));
                        }
                        if let Some(maximum) = &interval.high {
                            self.bounds.push((polynomial.neg(), maximum.negate()));
                        }
                        polynomial
                    }
                    ScopedArithmeticValue::Integer(value) => Polynomial::constant(value.clone()),
                    ScopedArithmeticValue::IntegerOperation {
                        operator,
                        left,
                        right,
                    } => {
                        if !matches!(
                            operator,
                            BinaryOperator::Add
                                | BinaryOperator::Subtract
                                | BinaryOperator::Multiply
                                | BinaryOperator::Divide
                                | BinaryOperator::Modulo
                        ) {
                            return None;
                        }
                        let left = self.normalize_scoped_value(left)?;
                        let right = self.normalize_scoped_value(right)?;
                        self.integer_binary_value(*operator, left, right)?
                    }
                    ScopedArithmeticValue::Term(term) => self
                        .with_scoped_expression(term, |engine| engine.normalize(term.expression))?,
                    ScopedArithmeticValue::CollectionLength(_) => return None,
                    ScopedArithmeticValue::AdmittedIntegerRemainder(term) => self
                        .with_scoped_expression(term, |engine| {
                            engine.capture_admitted_integer_remainder(term.expression)
                        })?,
                })
            }

            fn capture_admitted_integer_remainder(
                &mut self,
                expression: ExpressionHandle,
            ) -> Option<Polynomial> {
                let binary = expression_table(self.program).binary_node(expression)?;
                if binary.operator != BinaryOperator::Modulo {
                    return None;
                }
                let mut admitted = self.clone();
                let dividend = admitted.normalize(binary.left)?;
                let divisor = admitted.normalize(binary.right)?;
                let value = admitted.integer_binary_value(
                    BinaryOperator::Modulo,
                    dividend.clone(),
                    divisor.clone(),
                )?;
                if !admitted.bind_strict_occurrence(expression, value.clone()) {
                    return None;
                }
                let recipe = AdmittedIntegerRemainder {
                    dividend,
                    divisor,
                    value: value.clone(),
                };
                if !admitted.admitted_integer_remainders.contains(&recipe) {
                    admitted.admitted_integer_remainders.push(recipe);
                }
                admitted.refresh_admitted_integer_remainders();
                *self = admitted;
                Some(value)
            }

            pub(crate) fn refresh_admitted_integer_remainders(&mut self) {
                let recipes = self.admitted_integer_remainders.clone();
                loop {
                    let mut changed = false;
                    for recipe in &recipes {
                        changed |= self.install_integer_operation_bounds(
                            BinaryOperator::Modulo,
                            &recipe.dividend,
                            &recipe.divisor,
                            &recipe.value,
                        );
                    }
                    if !changed {
                        break;
                    }
                }
            }

            fn with_scoped_expression(
                &mut self,
                term: &crate::ScopedArithmeticExpression,
                query: impl FnOnce(&mut Self) -> Option<Polynomial>,
            ) -> Option<Polynomial> {
                let previous_owner = self.source_owner;
                let previous_types = self.source_type_bindings.clone();
                let previous_reads = self.formal_read_arguments.clone();
                let previous_owned = self.owned_arguments.clone();
                let value = (|| {
                    self.install_scoped_expression(term).then_some(())?;
                    query(self)
                })();
                self.source_owner = previous_owner;
                self.source_type_bindings = previous_types;
                self.formal_read_arguments = previous_reads;
                self.owned_arguments = previous_owned;
                value
            }

            pub(crate) fn install_scoped_expression(
                &mut self,
                expression: &crate::ScopedArithmeticExpression,
            ) -> bool {
                if !expression.owner.is_valid() {
                    return false;
                }
                self.source_owner = expression.owner;
                self.install_scoped_bindings(&expression.bindings)
            }

            fn declared_source_result_type(
                &self,
                expression: ExpressionHandle,
            ) -> Option<typed_trees::types::TypeReferenceHandle> {
                if let Some(parameters) =
                    crate::proof_contracts::contract_results::source_contract_parameters(
                        self.program,
                        self.source_owner,
                        expression,
                    )
                {
                    return crate::parameter_expression_result_type_reference(
                        self.program,
                        self.source_owner,
                        parameters,
                        expression,
                    );
                }
                if let Some(domain) = self.program.domain_definition(self.source_owner) {
                    return crate::value_custody::expression_types::domain_expression_result_type_reference(
                self.program,
                domain,
                expression,
            );
                }
                if let Some((_, signature)) =
                    self.program.trait_machine_signature(self.source_owner)
                {
                    return crate::parameter_expression_result_type_reference(
                        self.program,
                        signature.symbol,
                        self.program.state_signature_parameters(signature),
                        expression,
                    );
                }
                crate::value_custody::expression_types::declaration_expression_result_type_reference(
                    self.program,
                    self.source_owner,
                    None,
                    &|place| {
                        crate::proof_contracts::proof_embeddings::expression_type_reference(
                            self.program,
                            place,
                        )
                    },
                    expression,
                )
            }

            pub(crate) fn source_result_type(
                &self,
                expression: ExpressionHandle,
            ) -> Option<typed_trees::types::TypeReferenceHandle> {
                if !self.source_type_bindings.is_empty()
                    && let Some(binary) = expression_table(self.program).binary_node(expression)
                {
                    let operands =
                        [binary.left, binary.right].map(|operand| self.source_result_type(operand));
                    if let Some(spelling) =
                        typed_trees::operator::binary_operator_spelling(binary.operator)
                        && typed_trees::operator::has_builtin_spelled_expression_meaning(
                            self.program,
                            self.source_owner,
                            expression,
                            spelling,
                            &operands,
                        )
                        && let Some(reference) =
                            crate::value_custody::expression_types::builtin_binary_result_type_reference(
                                self.program,
                                binary,
                                operands,
                                &mut |operand| self.source_result_type(operand),
                            )
                    {
                        return Some(reference);
                    }
                }
                let reference = self.declared_source_result_type(expression)?;
                Some(typed_trees::static_applications::project_type_operand(
                    self.program,
                    reference,
                    &self.source_type_bindings,
                ))
            }

            pub(crate) fn selected_binary_meaning(
                &self,
                expression: ExpressionHandle,
                binary: &typed_trees::expression::TableBinaryExpression,
            ) -> bool {
                let owner = self.source_owner;
                let operands =
                    [binary.left, binary.right].map(|operand| self.source_result_type(operand));
                if matches!(
                    binary.operator,
                    BinaryOperator::Add
                        | BinaryOperator::Subtract
                        | BinaryOperator::Multiply
                        | BinaryOperator::Divide
                        | BinaryOperator::Modulo
                ) {
                    crate::proof_contracts::bound_expression_meaning::builtin_arithmetic_for_operand_types(
                self.program,
                owner,
                expression,
                &operands,
            ) && (super::super::proof_integer::proof_integer_expression(self.program, expression)
                || self
                    .source_result_type(expression)
                    .is_some_and(|reference| {
                        use numerics::arithmetic::ArithmeticDomain;
                        let admitted_policies = [
                            ArithmeticDomain::Exact,
                            ArithmeticDomain::Wrapping,
                            ArithmeticDomain::Saturating,
                        ];
                        self.program
                            .primitive_type_reference(reference)
                            .is_some_and(|primitive| {
                                primitive.is_fixed_integer()
                                    || (primitive == typed_trees::types::PrimitiveType::Addr
                                        && self
                                            .program
                                            .arithmetic_domain_for_type_reference(reference)
                                            == ArithmeticDomain::Exact)
                            })
                            && admitted_policies.contains(
                                &self.program.arithmetic_domain_for_type_reference(reference),
                            )
                    }))
                } else {
                    let Some(spelling) =
                        crate::proof_contracts::parameter_expression_meaning::spelled_binary_operator(
                            binary.operator,
                        )
                    else {
                        return true;
                    };
                    typed_trees::operator::has_builtin_spelled_expression_meaning(
                        self.program,
                        owner,
                        expression,
                        spelling,
                        &operands,
                    )
                }
            }

            pub(crate) fn install_dispatch_selection(&mut self, selection: DispatchSelection) {
                use crate::proof_contracts::arithmetic_domains::DispatchCondition;
                let (subject, pattern) = match selection.condition {
                    DispatchCondition::Equality { subject, pattern } => (subject, pattern),
                    DispatchCondition::Predicate(condition) => {
                        let mut comparisons = Vec::new();
                        self.collect_condition_comparisons(
                            condition,
                            selection.matched,
                            &mut comparisons,
                        );
                        self.install_hypotheses(comparisons);
                        return;
                    }
                };
                let operands = [subject, pattern].map(|operand| self.source_result_type(operand));
                if !typed_trees::operator::has_builtin_spelled_expression_meaning(
                    self.program,
                    self.source_owner,
                    selection.expression,
                    language_core::OperatorSpelling::Equal,
                    &operands,
                ) {
                    return;
                }
                let mut comparisons = Vec::new();
                if let ExpressionNode::Boolean(value) =
                    expression_table(self.program).expression(pattern)
                {
                    self.collect_condition_comparisons(
                        subject,
                        selection.matched == *value,
                        &mut comparisons,
                    );
                } else if let (Some(left), Some(right)) =
                    (self.normalize(subject), self.normalize(pattern))
                {
                    comparisons.push((
                        if selection.matched {
                            BinaryOperator::Equal
                        } else {
                            BinaryOperator::NotEqual
                        },
                        left,
                        right,
                    ));
                }
                self.install_hypotheses(comparisons);
            }

            fn collect_condition_comparisons(
                &mut self,
                expression: ExpressionHandle,
                positive: bool,
                comparisons: &mut Vec<(BinaryOperator, Polynomial, Polynomial)>,
            ) {
                match self.program.expression_table.expression(expression).clone() {
                    ExpressionNode::Boolean(value) => {
                        self.requires_unsatisfiable |= value != positive;
                        return;
                    }
                    ExpressionNode::Unary(unary) if unary.operator == UnaryOperator::LogicalNot => {
                        self.collect_condition_comparisons(unary.operand, !positive, comparisons);
                        return;
                    }
                    ExpressionNode::Binary(binary)
                        if self.selected_binary_meaning(expression, &binary) =>
                    {
                        if binary.operator == BinaryOperator::And && positive
                            || binary.operator == BinaryOperator::Or && !positive
                        {
                            self.collect_condition_comparisons(binary.left, positive, comparisons);
                            self.collect_condition_comparisons(binary.right, positive, comparisons);
                            return;
                        }
                        if matches!(
                            binary.operator,
                            BinaryOperator::Equal | BinaryOperator::NotEqual
                        ) {
                            let wrapped = match (
                                expression_table(self.program).expression(binary.left),
                                expression_table(self.program).expression(binary.right),
                            ) {
                                (_, ExpressionNode::Boolean(value)) => Some((binary.left, *value)),
                                (ExpressionNode::Boolean(value), _) => Some((binary.right, *value)),
                                _ => None,
                            };
                            if let Some((operand, value)) = wrapped {
                                self.collect_condition_comparisons(
                                    operand,
                                    positive
                                        == (value == (binary.operator == BinaryOperator::Equal)),
                                    comparisons,
                                );
                                return;
                            }
                        }
                    }
                    _ => {}
                }
                if let Some((operator, left, right)) = self.comparison_polynomials(expression)
                    && let Some(operator) = if positive {
                        Some(operator)
                    } else {
                        operator.complement()
                    }
                {
                    comparisons.push((operator, left, right));
                }
            }

            pub(crate) fn install_scoped_bindings(
                &mut self,
                bindings: &[crate::ScopedArithmeticBinding],
            ) -> bool {
                use crate::ScopedArithmeticBinder;
                if !self.strict_symbol_bindings_valid {
                    return false;
                }
                self.strict_occurrences.clear();
                let mut symbols: Vec<(SymbolHandle, Polynomial)> =
                    Vec::with_capacity(bindings.len());
                self.saved_conditions.clear();
                let mut occurrences = Vec::new();
                let mut coordinates: Vec<(crate::DeclaredInputRead, Polynomial)> = Vec::new();
                let mut types = Vec::new();
                let mut owned = Vec::new();
                let mut result = None;
                for binding in bindings {
                    if let crate::ScopedArithmeticValue::OwnedSnapshot(snapshot) = &binding.value {
                        let valid = match binding.binder {
                            ScopedArithmeticBinder::Symbol(symbol) => symbol.is_valid(),
                            ScopedArithmeticBinder::Occurrence(expression) => {
                                expression_table(self.program).expression_is_valid(expression)
                            }
                            _ => false,
                        };
                        if !valid {
                            return false;
                        }
                        if let Some((_, existing)) =
                            owned.iter().find(|(binder, _)| binder == &binding.binder)
                        {
                            if existing != snapshot {
                                return false;
                            }
                        } else {
                            owned.push((binding.binder.clone(), snapshot.clone()));
                        }
                        continue;
                    }
                    if let ScopedArithmeticBinder::Type(symbol) = binding.binder {
                        let super::super::ScopedArithmeticValue::TypeReference(reference) =
                            binding.value
                        else {
                            return false;
                        };
                        if !symbol.is_valid()
                            || !self
                                .program
                                .type_reference_table
                                .contains_type_reference(reference)
                        {
                            return false;
                        }
                        if let Some((_, existing)) =
                            types.iter().find(|(formal, _)| *formal == symbol)
                        {
                            if *existing != reference {
                                return false;
                            }
                        } else {
                            types.push((symbol, reference));
                        }
                        continue;
                    }
                    let Some(polynomial) = self.normalize_scoped_value(&binding.value) else {
                        return false;
                    };
                    match binding.binder {
                        ScopedArithmeticBinder::Type(_) => {
                            unreachable!("type metadata handled above")
                        }
                        ScopedArithmeticBinder::Symbol(symbol) => {
                            if !symbol.is_valid() {
                                return false;
                            }
                            if let Some((_, existing)) =
                                symbols.iter().find(|(candidate, _)| *candidate == symbol)
                            {
                                if *existing != polynomial {
                                    return false;
                                }
                                continue;
                            }
                            symbols.push((symbol, polynomial));
                        }
                        ScopedArithmeticBinder::Result => {
                            if result
                                .as_ref()
                                .is_some_and(|existing| *existing != polynomial)
                            {
                                return false;
                            }
                            result = Some(polynomial);
                        }
                        ScopedArithmeticBinder::Occurrence(expression) => {
                            occurrences.push((expression, polynomial));
                        }
                        ScopedArithmeticBinder::DeclaredRead(ref read) => {
                            if !read.coordinate.parameter.is_valid() {
                                return false;
                            }
                            if let Some((_, existing)) =
                                coordinates.iter().find(|(bound, _)| bound == read)
                            {
                                if *existing != polynomial {
                                    return false;
                                }
                            } else {
                                coordinates.push((read.clone(), polynomial));
                            }
                        }
                    }
                }
                self.source_type_bindings = types;
                self.strict_symbol_bindings = Some(symbols);
                self.strict_result_binding = result;
                self.formal_read_arguments = coordinates;
                self.owned_arguments = owned;
                self.strict_occurrences.clear();
                for (expression, polynomial) in occurrences {
                    if !self.bind_strict_occurrence(expression, polynomial) {
                        return false;
                    }
                }
                true
            }

            pub(crate) fn coordinate_value(
                &self,
                coordinate: &crate::RankSubjectCoordinate,
            ) -> Option<Polynomial> {
                let mut reads = self
                    .formal_read_arguments
                    .iter()
                    .filter(|(bound, _)| &bound.coordinate == coordinate);
                let (_, value) = reads.next()?;
                reads
                    .all(|(_, other)| other == value)
                    .then(|| value.clone())
            }

            pub(crate) fn declared_read_value(
                &self,
                read: &crate::DeclaredInputRead,
            ) -> Option<Polynomial> {
                self.formal_read_arguments
                    .iter()
                    .find(|(bound, _)| bound == read)
                    .map(|(_, value)| value.clone())
            }

            pub(crate) fn formal_coordinate_value(
                &self,
                expression: ExpressionHandle,
            ) -> Option<Polynomial> {
                let place = crate::canonical_place_from_expression(self.program, expression)?;
                self.coordinate_value(&crate::RankSubjectCoordinate {
                    parameter: place.root.as_symbol()?,
                    path: place.segments,
                })
            }

            pub(crate) fn bind_strict_projection(
                &mut self,
                expression: ExpressionHandle,
                value: Polynomial,
            ) -> bool {
                matches!(
                    expression_table(self.program).expression(expression),
                    ExpressionNode::Member(_)
                ) && self.bind_strict_occurrence(expression, value)
            }

            pub(crate) fn bind_strict_integer_division(
                &mut self,
                expression: ExpressionHandle,
            ) -> Option<()> {
                let binary = expression_table(self.program).binary_node(expression)?;
                let dividend = self.normalize(binary.left)?;
                let divisor = self.normalize(binary.right)?;
                if !matches!(
                    binary.operator,
                    BinaryOperator::Divide | BinaryOperator::Modulo
                ) {
                    return None;
                }
                let value = self.integer_binary_value(binary.operator, dividend, divisor)?;
                self.bind_strict_occurrence(expression, value).then_some(())
            }

            pub(crate) fn bind_strict_integer_shift(
                &mut self,
                expression: ExpressionHandle,
                count_bits: u32,
            ) -> Option<()> {
                let binary = expression_table(self.program).binary_node(expression)?;
                let value = self.normalize(binary.left)?;
                let count = self.normalize(binary.right)?;
                let value = match binary.operator {
                    BinaryOperator::ShiftLeft => {
                        self.integer_shift_left(value, count, count_bits)?
                    }
                    BinaryOperator::ShiftRight => {
                        self.integer_shift_right(value, count, count_bits)?
                    }
                    _ => return None,
                };
                self.bind_strict_occurrence(expression, value).then_some(())
            }

            pub(crate) fn bind_strict_integer_bitwise(
                &mut self,
                expression: ExpressionHandle,
                bits: u32,
                signed: bool,
            ) -> Option<()> {
                let binary = expression_table(self.program).binary_node(expression)?;
                let left = self.normalize(binary.left)?;
                let right = self.normalize(binary.right)?;
                let value = match binary.operator {
                    BinaryOperator::BitwiseAnd
                    | BinaryOperator::BitwiseOr
                    | BinaryOperator::BitwiseXor => {
                        self.integer_bitwise(binary.operator, left, right, bits, signed)?
                    }
                    _ => return None,
                };
                self.bind_strict_occurrence(expression, value).then_some(())
            }

            pub(crate) fn bind_captured_integer_place(
                &mut self,
                machine: &Machine,
                state: &typed_trees::state::State,
                expression: ExpressionHandle,
                value: BigInt,
            ) -> bool {
                let Some(reference) =
                    crate::declared_place_type_raw(self.program, machine, Some(state), expression)
                else {
                    return false;
                };
                crate::canonical_place_from_expression(self.program, expression).is_some()
                    && self
                        .program
                        .primitive_type_reference(reference)
                        .is_some_and(|primitive| primitive.is_fixed_integer())
                    && crate::has_builtin_bound_expression_meaning(
                        self.program,
                        machine,
                        Some(state),
                        expression,
                    )
                    && self.bind_strict_occurrence(expression, Polynomial::constant(value))
            }

            pub(crate) fn strict_occurrence_value(
                &self,
                expression: ExpressionHandle,
            ) -> Option<Polynomial> {
                self.strict_occurrences
                    .iter()
                    .find(|(source, _)| *source == expression)
                    .map(|(_, value)| value.clone())
            }

            pub(crate) fn bind_strict_occurrence(
                &mut self,
                expression: ExpressionHandle,
                value: Polynomial,
            ) -> bool {
                if self.strict_symbol_bindings.is_none()
                    || !self.strict_symbol_bindings_valid
                    || !expression_table(self.program).expression_is_valid(expression)
                {
                    return false;
                }
                if let Some((_, existing)) = self
                    .strict_occurrences
                    .iter()
                    .find(|(candidate, _)| *candidate == expression)
                {
                    return *existing == value;
                }
                self.strict_occurrences.push((expression, value));
                true
            }

            pub(crate) fn exact_argument_values(
                &mut self,
                arguments: &[StrictArithmeticExpressionBinding],
            ) -> Option<Vec<(SymbolHandle, Polynomial)>> {
                if !self.strict_symbol_bindings_valid || self.strict_symbol_bindings.is_none() {
                    return None;
                }
                let resolved = arguments
                    .iter()
                    .map(|argument| {
                        argument.symbol.is_valid().then_some(())?;
                        Some((argument.symbol, self.normalize(argument.expression)?))
                    })
                    .collect::<Option<Vec<_>>>();
                let mut formals: Vec<(SymbolHandle, Polynomial)> = Vec::new();
                for (symbol, polynomial) in resolved? {
                    match formals.iter().find(|(candidate, _)| *candidate == symbol) {
                        Some((_, existing)) if *existing != polynomial => return None,
                        Some(_) => {}
                        None => formals.push((symbol, polynomial)),
                    }
                }
                Some(formals)
            }

            pub(crate) fn bind_goal_formals(&mut self, formals: Vec<(SymbolHandle, Polynomial)>) {
                self.strict_occurrences.clear();
                let Some(bindings) = &mut self.strict_symbol_bindings else {
                    self.saved_conditions.clear();
                    return;
                };
                self.saved_conditions.clear();
                for (symbol, polynomial) in formals {
                    match bindings
                        .iter_mut()
                        .find(|(candidate, _)| *candidate == symbol)
                    {
                        Some((_, existing)) => *existing = polynomial,
                        None => bindings.push((symbol, polynomial)),
                    }
                }
            }

            pub(crate) fn bind_strict_arguments(
                &mut self,
                arguments: &[StrictArithmeticExpressionBinding],
            ) -> bool {
                if !self.strict_symbol_bindings_valid || self.strict_symbol_bindings.is_none() {
                    return false;
                }
                let Some(resolved) = arguments
                    .iter()
                    .map(|argument| {
                        argument.symbol.is_valid().then_some(())?;
                        Some((argument.symbol, self.normalize(argument.expression)?))
                    })
                    .collect::<Option<Vec<_>>>()
                else {
                    return false;
                };
                let Some(bindings) = &mut self.strict_symbol_bindings else {
                    return false;
                };
                for (symbol, polynomial) in resolved {
                    if let Some((_, existing)) =
                        bindings.iter().find(|(candidate, _)| *candidate == symbol)
                    {
                        if existing != &polynomial {
                            return false;
                        }
                    } else {
                        bindings.push((symbol, polynomial));
                    }
                }
                true
            }

            pub(crate) fn rebind_saved_expression(
                &mut self,
                symbol: SymbolHandle,
                expression: ExpressionHandle,
            ) -> bool {
                if !self.strict_symbol_bindings_valid || self.strict_symbol_bindings.is_none() {
                    return false;
                }
                let previous = self.strict_symbol_bindings.as_mut().and_then(|bindings| {
                    bindings
                        .iter()
                        .position(|(candidate, _)| *candidate == symbol)
                        .map(|index| bindings.remove(index).1)
                });
                match self.normalize(expression) {
                    Some(polynomial) => {
                        let Some(bindings) = &mut self.strict_symbol_bindings else {
                            return false;
                        };
                        bindings.push((symbol, polynomial));
                        true
                    }
                    None => {
                        if let Some(previous) = previous
                            && let Some(bindings) = &mut self.strict_symbol_bindings
                        {
                            bindings.push((symbol, previous));
                        }
                        false
                    }
                }
            }

            pub(crate) fn register_opaque_term(&mut self, atom: String, term: OpaqueTerm) {
                if self.opaque_terms.iter().any(|(minted, _)| *minted == atom) {
                    return;
                }
                if matches!(&term, OpaqueTerm::Conditional { .. }) {
                    self.conditional_terms.push(self.opaque_terms.len());
                }
                self.opaque_terms.push((atom, term));
            }
        }
    }
    impl<'program> Engine<'program> {
        pub(crate) fn lower_bound_queries(&self) -> LowerBoundQueries<'_, 'program> {
            LowerBoundQueries::prepared(self)
        }
    }

    pub(crate) enum Judgment {
        Proven,
        ConstantFalse,
        Refuted,
        Unknown { goal_in_language: bool },
    }

    pub(crate) type Monomial = BTreeMap<String, u32>;

    #[derive(Debug, Clone, PartialEq, Eq, Default)]
    pub(crate) struct Polynomial {
        pub(crate) terms: BTreeMap<Monomial, BigInt>,
    }

    impl Polynomial {
        pub(crate) fn constant(value: BigInt) -> Self {
            let mut polynomial = Self::default();
            if !value.is_zero() {
                polynomial.terms.insert(Monomial::new(), value);
            }
            polynomial
        }

        pub(crate) fn atom(name: String) -> Self {
            let mut monomial = Monomial::new();
            monomial.insert(name, 1);
            let mut polynomial = Self::default();
            polynomial.terms.insert(monomial, BigInt::from_i64(1));
            polynomial
        }

        pub(crate) fn constant_value(&self) -> Option<BigInt> {
            match self.terms.len() {
                0 => Some(BigInt::zero()),
                1 => self.terms.get(&Monomial::new()).cloned(),
                _ => None,
            }
        }

        fn excludes_integer_zero(&self) -> bool {
            let mut divisor = BigInt::zero();
            let mut constant = BigInt::zero();
            for (monomial, coefficient) in &self.terms {
                if monomial.is_empty() {
                    constant = coefficient.clone();
                } else {
                    divisor = divisor.gcd(coefficient);
                }
            }
            if divisor.is_zero() {
                return !constant.is_zero();
            }
            constant
                .div_rem(&divisor)
                .is_some_and(|(_, remainder)| !remainder.is_zero())
        }

        pub(crate) fn add(&self, other: &Self) -> Self {
            let mut terms = self.terms.clone();
            Self::accumulate(&mut terms, other, false);
            Self { terms }
        }

        fn accumulate(terms: &mut BTreeMap<Monomial, BigInt>, other: &Self, subtract: bool) {
            for (monomial, coefficient) in &other.terms {
                if let Some(entry) = terms.get_mut(monomial) {
                    *entry = if subtract {
                        entry.sub(coefficient)
                    } else {
                        entry.add(coefficient)
                    };
                    if entry.is_zero() {
                        terms.remove(monomial);
                    }
                } else if !coefficient.is_zero() {
                    let coefficient = if subtract {
                        coefficient.negate()
                    } else {
                        coefficient.clone()
                    };
                    terms.insert(monomial.clone(), coefficient);
                }
            }
        }

        fn neg(&self) -> Self {
            let mut terms = BTreeMap::new();
            for (monomial, coefficient) in &self.terms {
                terms.insert(monomial.clone(), coefficient.negate());
            }
            Self { terms }
        }

        pub(crate) fn sub(&self, other: &Self) -> Self {
            let mut terms = self.terms.clone();
            Self::accumulate(&mut terms, other, true);
            Self { terms }
        }

        pub(crate) fn checked_mul(&self, other: &Self) -> Option<Self> {
            let mut result = Self::default();
            for (left_monomial, left_coefficient) in &self.terms {
                for (right_monomial, right_coefficient) in &other.terms {
                    let coefficient = left_coefficient.mul(right_coefficient);
                    let mut monomial = left_monomial.clone();
                    for (atom, power) in right_monomial {
                        let entry = monomial.entry(atom.clone()).or_insert(0);
                        *entry = entry.checked_add(*power)?;
                    }
                    let entry = result
                        .terms
                        .entry(monomial.clone())
                        .or_insert_with(BigInt::zero);
                    *entry = entry.add(&coefficient);
                    if entry.is_zero() {
                        result.terms.remove(&monomial);
                    }
                }
            }
            Some(result)
        }

        fn as_atom_difference(&self) -> Option<(String, String, BigInt)> {
            let mut positive = None;
            let mut negative = None;
            let mut constant = BigInt::zero();
            for (monomial, coefficient) in &self.terms {
                if monomial.is_empty() {
                    constant = coefficient.clone();
                    continue;
                }
                if monomial.len() != 1 || *monomial.values().next().unwrap() != 1 {
                    return None;
                }
                let atom = monomial.keys().next().unwrap().clone();
                if *coefficient == BigInt::from_i64(1) && positive.is_none() {
                    positive = Some(atom);
                } else if *coefficient == BigInt::from_i64(-1) && negative.is_none() {
                    negative = Some(atom);
                } else {
                    return None;
                }
            }
            Some((positive?, negative?, constant))
        }

        fn as_single_atom(&self) -> Option<(String, i64, BigInt)> {
            let mut atom = None;
            let mut coefficient_value = BigInt::zero();
            let mut constant = BigInt::zero();
            for (monomial, coefficient) in &self.terms {
                if monomial.is_empty() {
                    constant = coefficient.clone();
                    continue;
                }
                if monomial.len() != 1 || *monomial.values().next().unwrap() != 1 || atom.is_some()
                {
                    return None;
                }
                atom = Some(monomial.keys().next().unwrap().clone());
                coefficient_value = coefficient.clone();
            }
            let atom = atom?;
            let sign = if coefficient_value == BigInt::from_i64(1) {
                1
            } else if coefficient_value == BigInt::from_i64(-1) {
                -1
            } else {
                return None;
            };
            Some((atom, sign, constant))
        }
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    pub(crate) enum OpaqueTerm {
        DeclarationApplication {
            measure: SymbolHandle,
            input: IntegerApplicationInput,
        },
        Conditional {
            arms: Vec<ConditionalValueArm>,
        },
        Call {
            owner: SymbolHandle,
            expression: ExpressionHandle,
            target: SymbolHandle,
            arguments: Vec<IntegerApplicationInput>,
        },
        IntegerPolicy {
            primitive: typed_trees::types::PrimitiveType,
            domain: numerics::arithmetic::ArithmeticDomain,
            value: Polynomial,
        },
        Remainder {
            operand: Polynomial,
            modulus: Polynomial,
            tight_interval: bool,
        },
        Quotient {
            dividend: Polynomial,
            divisor: Polynomial,
        },
        ShiftLeft {
            value: Polynomial,
            count: Polynomial,
            count_bits: u32,
        },
        ShiftRight {
            value: Polynomial,
            count: Polynomial,
            count_bits: u32,
        },
        Bitwise {
            operator: BinaryOperator,
            left: Polynomial,
            right: Polynomial,
            bits: u32,
            signed: bool,
        },
    }

    #[derive(Clone)]
    pub(crate) struct SavedCondition {
        pub(crate) symbol: SymbolHandle,
        pub(crate) holds: bool,
        pub(crate) comparisons: Vec<(BinaryOperator, Polynomial, Polynomial)>,
        pub(crate) fully_visible: bool,
    }

    #[derive(Clone)]
    pub(crate) struct Engine<'program> {
        pub(crate) program: &'program dyn CheckingInput,
        machine_symbol: SymbolHandle,
        source_owner: SymbolHandle,
        source_type_bindings: Vec<(SymbolHandle, TypeReferenceHandle)>,
        pub(crate) parameter_atoms: Vec<String>,
        strict_symbol_bindings: Option<Vec<(SymbolHandle, Polynomial)>>,
        formal_arguments: Option<Vec<(SymbolHandle, Polynomial)>>,
        formal_read_arguments: Vec<(crate::DeclaredInputRead, Polynomial)>,
        owned_arguments: Vec<(crate::ScopedArithmeticBinder, crate::CapturedOwnedSnapshot)>,
        strict_symbol_bindings_valid: bool,
        strict_result_binding: Option<Polynomial>,
        strict_occurrences: Vec<(ExpressionHandle, Polynomial)>,
        admitted_integer_remainders: Vec<strict_bindings::AdmittedIntegerRemainder>,
        pub(crate) saved_conditions: Vec<SavedCondition>,
        captured_calls: Option<super::scoped_arithmetic::calls::ScopedCalls<'program>>,
        proof_integer_formation: bool,
        unsigned_atoms: Vec<String>,
        pub(crate) substitutions: BTreeMap<String, Polynomial>,
        pub(crate) bounds: Vec<(Polynomial, BigInt)>,
        nonzero_differences: Vec<Polynomial>,
        arithmetic_intervals: BTreeMap<String, Interval>,
        opaque_terms: Vec<(String, OpaqueTerm)>,
        denotation_identities: Arc<std::sync::atomic::AtomicU64>,
        conditional_terms: Vec<usize>,
        conditional_work_remaining: Arc<std::sync::atomic::AtomicUsize>,
        matrix: difference_matrix::DifferenceBounds,
        pub(crate) requires_unsatisfiable: bool,
    }

    const ZERO_ATOM: &str = "\u{0}zero";
    const SUBSTITUTION_ROUNDS: usize = 8;

    impl<'program> Engine<'program> {
        pub(crate) fn new(program: &'program dyn CheckingInput, machine: &Machine) -> Self {
            let mut engine = Self::for_owner(program, machine.symbol, None);
            for state in program.machine_states(machine) {
                for parameter in program.state_parameters(state) {
                    let name = parameter.name.as_str().to_owned();
                    if engine.parameter_atoms.contains(&name) {
                        continue;
                    }
                    let unsigned = unsigned_parameter_carrier(program, parameter.type_reference);
                    engine.declare_atom(&name, unsigned);
                }
            }
            engine
        }

        pub(crate) fn immutable_local_initializer(
            &self,
            symbol: SymbolHandle,
        ) -> Option<ExpressionHandle> {
            let machine = self.program.machine(self.machine_symbol)?;
            for state in self.program.machine_states(machine) {
                for statement in self
                    .program
                    .statement_table
                    .statements(state.statement_nodes)
                {
                    if let typed_trees::statement::StatementNode::LocalData(local) = statement
                        && local.symbol == symbol
                        && !local.is_mutable
                        && local.initial_value.is_valid()
                    {
                        return Some(local.initial_value);
                    }
                }
            }
            None
        }

        fn for_owner(
            program: &'program dyn CheckingInput,
            owner: SymbolHandle,
            strict_symbol_bindings: Option<Vec<(SymbolHandle, Polynomial)>>,
        ) -> Self {
            Self {
                program,
                machine_symbol: owner,
                source_owner: owner,
                source_type_bindings: Vec::new(),
                parameter_atoms: Vec::new(),
                strict_symbol_bindings,
                formal_arguments: None,
                formal_read_arguments: Vec::new(),
                owned_arguments: Vec::new(),
                strict_symbol_bindings_valid: true,
                strict_result_binding: None,
                strict_occurrences: Vec::new(),
                admitted_integer_remainders: Vec::new(),
                saved_conditions: Vec::new(),
                captured_calls: None,
                proof_integer_formation: false,
                unsigned_atoms: Vec::new(),
                substitutions: BTreeMap::new(),
                bounds: Vec::new(),
                nonzero_differences: Vec::new(),
                arithmetic_intervals: BTreeMap::new(),
                opaque_terms: Vec::new(),
                denotation_identities: Arc::new(std::sync::atomic::AtomicU64::new(0)),
                conditional_terms: Vec::new(),
                conditional_work_remaining: Arc::new(std::sync::atomic::AtomicUsize::new(1 << 20)),
                matrix: difference_matrix::DifferenceBounds::default(),
                requires_unsatisfiable: false,
            }
        }

        pub(crate) fn integer_projection_registrations(&self) -> (usize, usize, usize, usize) {
            (
                self.parameter_atoms.len(),
                self.opaque_terms.len(),
                self.arithmetic_intervals.len(),
                self.bounds.len(),
            )
        }

        pub(crate) fn has_opaque_terms(&self) -> bool {
            !self.opaque_terms.is_empty()
        }

        pub(crate) fn truncate_opaque_terms_since(&mut self, start: usize) -> bool {
            let mut removed_existing_interval = false;
            while self.opaque_terms.len() > start {
                if let Some((atom, _)) = self.opaque_terms.pop()
                    && self.arithmetic_intervals.remove(&atom).is_some()
                    && self
                        .opaque_terms
                        .iter()
                        .any(|(existing, _)| *existing == atom)
                {
                    removed_existing_interval = true;
                }
            }
            let retained = self.opaque_terms.len();
            self.conditional_terms
                .retain(|position| *position < retained);
            removed_existing_interval
        }

        pub(crate) fn restore_matrix_from(&mut self, source: &Self) {
            self.matrix = source.matrix.clone();
            self.requires_unsatisfiable = source.requires_unsatisfiable;
        }

        pub(crate) fn restore_intervals_from(&mut self, source: &Self) {
            self.arithmetic_intervals = source.arithmetic_intervals.clone();
        }

        pub(crate) fn opaque_term_name_if_uncorrelated(&self, index: usize) -> Option<&str> {
            self.opaque_terms
                .get(index)
                .and_then(|(name, term)| match term {
                    OpaqueTerm::IntegerPolicy { .. }
                    | OpaqueTerm::ShiftLeft { .. }
                    | OpaqueTerm::Bitwise { .. } => Some(name.as_str()),
                    OpaqueTerm::Call { .. }
                    | OpaqueTerm::Conditional { .. }
                    | OpaqueTerm::DeclarationApplication { .. } => None,
                    OpaqueTerm::Quotient { .. }
                    | OpaqueTerm::Remainder { .. }
                    | OpaqueTerm::ShiftRight { .. } => None,
                })
        }

        pub(crate) fn opaque_term_name_if_uncorrelated_with_queries(
            &self,
            index: usize,
            queries: &LowerBoundQueries<'_, 'program>,
        ) -> Option<&str> {
            self.opaque_terms
                .get(index)
                .and_then(|(name, term)| match term {
                    OpaqueTerm::Call { .. }
                    | OpaqueTerm::Conditional { .. }
                    | OpaqueTerm::DeclarationApplication { .. } => None,
                    OpaqueTerm::IntegerPolicy { .. }
                    | OpaqueTerm::ShiftLeft { .. }
                    | OpaqueTerm::Bitwise { .. } => Some(name.as_str()),
                    OpaqueTerm::Quotient { dividend, .. }
                    | OpaqueTerm::Remainder {
                        modulus: dividend, ..
                    }
                    | OpaqueTerm::ShiftRight {
                        value: dividend, ..
                    } => {
                        let interval = self.arithmetic_intervals.get(name.as_str())?;
                        let Some(low) = &interval.low else {
                            return Some(name.as_str());
                        };
                        if interval.high.as_ref() == Some(low) {
                            return None;
                        }
                        let upper_bound_poly = match term {
                            OpaqueTerm::Quotient { .. } => self.substituted(dividend),
                            OpaqueTerm::Remainder { .. } | OpaqueTerm::ShiftRight { .. } => self
                                .substituted(dividend)
                                .sub(&Polynomial::constant(BigInt::from_i64(1))),
                            _ => unreachable!(),
                        };
                        let proves_upper_le_low = queries.prove_at_least(
                            &Polynomial::constant(low.clone()).sub(&upper_bound_poly),
                            &BigInt::zero(),
                        );
                        (!proves_upper_le_low).then_some(name.as_str())
                    }
                })
        }

        pub(crate) fn opaque_terms_since_mention(&self, start: usize, atom: &str) -> bool {
            let poly_mentions = |poly: &Polynomial| {
                poly.terms
                    .keys()
                    .any(|monomial| monomial.contains_key(atom))
            };
            self.opaque_terms.get(start..).is_some_and(|terms| {
                terms.iter().any(|(_, term)| match term {
                    OpaqueTerm::IntegerPolicy { value, .. } => poly_mentions(value),
                    OpaqueTerm::Remainder {
                        operand, modulus, ..
                    } => poly_mentions(operand) || poly_mentions(modulus),
                    OpaqueTerm::Quotient { dividend, divisor } => {
                        poly_mentions(dividend) || poly_mentions(divisor)
                    }
                    OpaqueTerm::ShiftLeft { value, count, .. }
                    | OpaqueTerm::ShiftRight { value, count, .. } => {
                        poly_mentions(value) || poly_mentions(count)
                    }
                    OpaqueTerm::DeclarationApplication { input, .. } => {
                        let mut mentions = false;
                        input.visit_values(|value| mentions |= poly_mentions(value));
                        mentions
                    }
                    OpaqueTerm::Conditional { arms } => arms.iter().any(|arm| {
                        let mut mentions = false;
                        arm.visit_operands(|value| mentions |= poly_mentions(value));
                        mentions
                    }),
                    OpaqueTerm::Call { arguments, .. } => arguments.iter().any(|input| {
                        let mut mentions = false;
                        input.visit_values(|value| mentions |= poly_mentions(value));
                        mentions
                    }),
                    OpaqueTerm::Bitwise { left, right, .. } => {
                        poly_mentions(left) || poly_mentions(right)
                    }
                })
            })
        }

        pub(crate) fn opaque_terms_since_only_wrapping_or_bitwise(&self, start: usize) -> bool {
            self.opaque_terms.get(start..).is_some_and(|terms| {
                terms.iter().all(|(_, term)| {
                    matches!(
                        term,
                        OpaqueTerm::IntegerPolicy {
                            domain: numerics::arithmetic::ArithmeticDomain::Wrapping,
                            ..
                        } | OpaqueTerm::Bitwise {
                            operator: BinaryOperator::BitwiseOr | BinaryOperator::BitwiseXor,
                            ..
                        }
                    )
                })
            })
        }

        fn declare_atom(&mut self, identity: &str, unsigned: bool) {
            if !self.parameter_atoms.iter().any(|atom| atom == identity) {
                self.parameter_atoms.push(identity.to_owned());
            }
            if unsigned && !self.unsigned_atoms.iter().any(|atom| atom == identity) {
                self.unsigned_atoms.push(identity.to_owned());
            }
        }
        pub(crate) fn refresh_opaque_intervals(&mut self) {
            if self.opaque_terms.is_empty() {
                return;
            }
            for position in 0..self.opaque_terms.len() {
                let (atom, term) = self.opaque_terms[position].clone();
                let interval = match term {
                    OpaqueTerm::Call { .. }
                    | OpaqueTerm::Conditional { .. }
                    | OpaqueTerm::DeclarationApplication { .. } => continue,
                    OpaqueTerm::IntegerPolicy {
                        primitive,
                        domain,
                        value,
                    } => self.integer_policy_interval(primitive, domain, &value),
                    OpaqueTerm::Quotient { dividend, divisor } => {
                        self.quotient_interval(&dividend, &divisor)
                    }
                    OpaqueTerm::Remainder {
                        operand,
                        modulus,
                        tight_interval,
                    } => self.remainder_interval(&operand, &modulus, tight_interval),
                    OpaqueTerm::ShiftLeft {
                        value,
                        count,
                        count_bits,
                    } => self.shift_left_interval(&value, &count, count_bits),
                    OpaqueTerm::ShiftRight {
                        value,
                        count,
                        count_bits,
                    } => self.shift_right_interval(&value, &count, count_bits),
                    OpaqueTerm::Bitwise {
                        operator,
                        left,
                        right,
                        bits,
                        signed,
                    } => self.bitwise_interval(operator, &left, &right, bits, signed),
                };
                self.arithmetic_intervals.insert(atom, interval);
            }
        }

        pub(crate) fn for_proof_integer_formation(
            program: &'program dyn CheckingInput,
            owner: SymbolHandle,
            hypotheses: &[ExpressionHandle],
            selections: &[crate::proof_contracts::arithmetic_domains::DispatchSelection],
        ) -> Self {
            let mut bindings = Vec::new();
            for (handle, expression) in expression_table(program).iter_expressions() {
                let ExpressionNode::Name(path) = expression else {
                    continue;
                };
                if path.symbol.is_valid()
                    && (crate::proof_contracts::proof_embeddings::integer_embedding(
                        program, handle,
                    )
                    .is_some()
                        || proof_integer_expression(program, handle))
                    && !bindings.iter().any(|(symbol, _)| *symbol == path.symbol)
                {
                    bindings.push((
                        path.symbol,
                        Polynomial::atom(format!("\0proof-symbol:{:?}", path.symbol)),
                    ));
                }
            }
            let mut engine = Self::strict_for_declaration(program, owner);
            engine.strict_symbol_bindings = Some(bindings);
            engine.proof_integer_formation = true;
            engine.install_source_hypotheses(hypotheses);
            for selection in selections {
                engine.install_dispatch_selection(*selection);
            }
            engine
        }

        pub(crate) fn for_explicit_bindings(program: &'program dyn CheckingInput) -> Self {
            Self::for_owner(program, SymbolHandle::default(), Some(Vec::new()))
        }

        pub(crate) fn with_result_atom(
            program: &'program dyn CheckingInput,
            machine: &Machine,
            root: &typed_trees::state::State,
        ) -> Self {
            let mut engine = Self::new(program, machine);
            let shadowed = program
                .state_parameters(root)
                .iter()
                .any(|parameter| parameter.name.as_str() == RESULT_BINDER);
            if !shadowed {
                let unsigned = root.return_type.is_valid()
                    && unsigned_parameter_carrier(program, root.return_type);
                engine.declare_atom(RESULT_BINDER, unsigned);
            }
            engine
        }

        pub(crate) fn add_requires(&mut self, facts: &[ExpressionHandle]) -> bool {
            let mut comparisons = Vec::new();
            self.collect_entry_range_hypotheses(&mut comparisons);
            let mut fully_visible = self.install_hypotheses(comparisons);
            fully_visible &= self.install_source_hypotheses(facts);
            fully_visible
        }

        fn install_source_hypotheses(&mut self, facts: &[ExpressionHandle]) -> bool {
            let mut fully_visible = true;
            for fact in facts {
                let mut comparisons = Vec::new();
                let mut integer_differences = Vec::new();
                for conjunct in self.conjuncts(*fact) {
                    let retain_integer_differences = self.strict_symbol_bindings.is_none()
                        && (self.is_mathematical_application(conjunct)
                            || self.source_integer_disequality(conjunct));
                    let first_comparison = comparisons.len();
                    fully_visible &= self.collect_comparisons(&[conjunct], &mut comparisons);
                    if retain_integer_differences {
                        integer_differences.extend(
                            comparisons[first_comparison..]
                                .iter()
                                .filter(|(operator, _, _)| *operator == BinaryOperator::NotEqual)
                                .map(|(_, left, right)| left.sub(right)),
                        );
                    }
                }
                fully_visible &= self.install_hypotheses(comparisons);
                for difference in integer_differences {
                    let difference = self.substituted(&difference);
                    if !self.nonzero_differences.contains(&difference) {
                        self.nonzero_differences.push(difference);
                    }
                }
            }
            fully_visible
        }

        fn source_integer_disequality(&self, expression: ExpressionHandle) -> bool {
            let ExpressionNode::Binary(binary) =
                expression_table(self.program).expression(expression)
            else {
                return false;
            };
            if binary.operator != BinaryOperator::NotEqual {
                return false;
            }
            let operands = [binary.left, binary.right];
            let references = operands.map(|operand| self.source_result_type(operand));
            operands
                .into_iter()
                .zip(references)
                .all(|(operand, reference)| {
                    proof_integer_expression(self.program, operand)
                        || match reference
                            .and_then(|reference| self.program.primitive_type_reference(reference))
                        {
                            Some(primitive) => {
                                primitive.is_integer()
                                    || primitive == typed_trees::types::PrimitiveType::Addr
                            }
                            None => {
                                super::proof_integer::anonymous_integer_value(self.program, operand)
                                    .is_some()
                            }
                        }
                })
                && typed_trees::operator::has_builtin_spelled_expression_meaning(
                    self.program,
                    self.source_owner,
                    expression,
                    language_core::OperatorSpelling::NotEqual,
                    &references,
                )
        }

        pub(crate) fn collect_entry_range_hypotheses(
            &mut self,
            comparisons: &mut Vec<(BinaryOperator, Polynomial, Polynomial)>,
        ) {
            let Some(machine) = self.program.machine(self.machine_symbol) else {
                return;
            };
            let Some(entry) = self.program.machine_states(machine).first() else {
                return;
            };
            for parameter in self.program.state_parameters(entry) {
                let atom = Polynomial::atom(parameter.name.as_str().to_owned());
                if let Some((minimum, maximum)) = self
                    .program
                    .primitive_type_reference(parameter.type_reference)
                    .filter(|primitive| primitive.is_fixed_integer())
                    .and_then(|primitive| primitive.integer_bounds())
                {
                    comparisons.push((
                        BinaryOperator::GreaterOrEqual,
                        atom.clone(),
                        Polynomial::constant(BigInt::from_i128(minimum)),
                    ));
                    comparisons.push((
                        BinaryOperator::LessOrEqual,
                        atom.clone(),
                        Polynomial::constant(BigInt::from_i128(maximum)),
                    ));
                }
                let Some(interval) =
                    crate::proof_contracts::arithmetic_domains::range_constraint_interval(
                        self.program,
                        parameter.type_reference,
                    )
                else {
                    continue;
                };
                if let Some(low) = interval.low() {
                    comparisons.push((
                        BinaryOperator::GreaterOrEqual,
                        atom.clone(),
                        Polynomial::constant(BigInt::from_i64(low)),
                    ));
                }
                if let Some(high) = interval.high() {
                    comparisons.push((
                        BinaryOperator::LessOrEqual,
                        atom.clone(),
                        Polynomial::constant(BigInt::from_i64(high)),
                    ));
                }
            }
        }

        pub(crate) fn collect_comparisons(
            &mut self,
            facts: &[ExpressionHandle],
            comparisons: &mut Vec<(BinaryOperator, Polynomial, Polynomial)>,
        ) -> bool {
            let mut fully_visible = true;
            for fact in facts {
                if self.is_mathematical_application(*fact) {
                    fully_visible &= self.collect_mathematical_comparisons(*fact, comparisons);
                    continue;
                }
                for conjunct in self.conjuncts(*fact) {
                    match self.comparison_polynomials(conjunct) {
                        Some(comparison) => comparisons.push(comparison),
                        None => fully_visible = false,
                    }
                }
            }
            fully_visible
        }

        pub(crate) fn install_hypotheses(
            &mut self,
            mut comparisons: Vec<(BinaryOperator, Polynomial, Polynomial)>,
        ) -> bool {
            let mut fully_visible = true;
            for (operator, left, right) in &comparisons {
                if *operator == BinaryOperator::Equal {
                    self.harvest_substitution(left, right);
                }
            }
            if !self.refresh_call_congruences(&mut comparisons) {
                return false;
            }
            let mut lower_bounds = std::mem::take(&mut self.bounds);
            for (polynomial, _) in &mut lower_bounds {
                *polynomial = self.substituted(polynomial);
            }
            let mut nonzero_differences = Vec::new();
            for (operator, left, right) in comparisons {
                let left = self.substituted(&left);
                let right = self.substituted(&right);
                let difference_rl = right.sub(&left);
                let difference_lr = left.sub(&right);
                match operator {
                    BinaryOperator::Less => lower_bounds.push((difference_rl, BigInt::from_i64(1))),
                    BinaryOperator::LessOrEqual => {
                        lower_bounds.push((difference_rl, BigInt::zero()))
                    }
                    BinaryOperator::Greater => {
                        lower_bounds.push((difference_lr, BigInt::from_i64(1)))
                    }
                    BinaryOperator::GreaterOrEqual => {
                        lower_bounds.push((difference_lr, BigInt::zero()))
                    }
                    BinaryOperator::Equal => {
                        lower_bounds.push((difference_rl, BigInt::zero()));
                        lower_bounds.push((difference_lr, BigInt::zero()));
                    }
                    BinaryOperator::NotEqual => nonzero_differences.push(difference_lr),
                    _ => fully_visible = false,
                }
            }
            for (polynomial, bound) in lower_bounds {
                if let Some(value) = polynomial.constant_value() {
                    if value < bound {
                        self.requires_unsatisfiable = true;
                    }
                    continue;
                }
                self.bounds.push((polynomial, bound));
            }

            self.refresh_difference_bounds();
            let previous_bounds = self.bounds.len();
            for difference in nonzero_differences {
                if self.strict_symbol_bindings.is_some()
                    && !self.nonzero_differences.contains(&difference)
                {
                    self.nonzero_differences.push(difference.clone());
                }
                let opposite = difference.neg();
                let (nonnegative, nonpositive) = {
                    let queries = self.lower_bound_queries();
                    (
                        queries.prove_at_least(&difference, &BigInt::zero()),
                        queries.prove_at_least(&opposite, &BigInt::zero()),
                    )
                };
                match (nonnegative, nonpositive) {
                    (true, true) => self.requires_unsatisfiable = true,
                    (true, false) => self.bounds.push((difference, BigInt::from_i64(1))),
                    (false, true) => self.bounds.push((opposite, BigInt::from_i64(1))),
                    (false, false) => {}
                }
            }
            if self.bounds.len() != previous_bounds {
                self.refresh_difference_bounds();
            }
            fully_visible
        }

        pub(crate) fn integer_comparisons_unsatisfiable(
            &mut self,
            comparisons: Vec<(BinaryOperator, Polynomial, Polynomial)>,
        ) -> bool {
            if self.strict_symbol_bindings.is_none() || !self.strict_symbol_bindings_valid {
                return false;
            }
            let equalities = comparisons
                .iter()
                .filter(|(operator, _, _)| *operator == BinaryOperator::Equal)
                .map(|(_, left, right)| left.sub(right))
                .collect::<Vec<_>>();
            if !self.install_hypotheses(comparisons) {
                return false;
            }
            self.refresh_opaque_intervals();
            if self.requires_unsatisfiable
                || equalities
                    .iter()
                    .any(|difference| self.substituted(difference).excludes_integer_zero())
            {
                return true;
            }
            if self.opaque_terms.is_empty()
                && self.bounds.iter().all(|(polynomial, _)| {
                    polynomial.as_atom_difference().is_some()
                        || polynomial.as_single_atom().is_some()
                })
            {
                return false;
            }
            self.bounds_are_inconsistent()
        }

        pub(crate) fn judge(&mut self, fact: ExpressionHandle) -> Judgment {
            match expression_table(self.program).expression(fact) {
                ExpressionNode::Boolean(true) => return Judgment::Proven,
                ExpressionNode::Boolean(false) => return Judgment::ConstantFalse,
                _ => {}
            }
            if self.is_mathematical_application(fact) {
                return self.judge_mathematical_application(fact);
            }
            let conjuncts = self.conjuncts(fact);
            if conjuncts.len() > 1 {
                let mut constant_false = false;
                let mut refuted = false;
                let mut unknown = false;
                let mut all_in_language = true;
                for conjunct in conjuncts {
                    match self.judge(conjunct) {
                        Judgment::Proven => {}
                        Judgment::ConstantFalse => constant_false = true,
                        Judgment::Refuted => refuted = true,
                        Judgment::Unknown { goal_in_language } => {
                            unknown = true;
                            all_in_language &= goal_in_language;
                        }
                    }
                }
                return if constant_false {
                    Judgment::ConstantFalse
                } else if refuted {
                    Judgment::Refuted
                } else if unknown {
                    Judgment::Unknown {
                        goal_in_language: all_in_language,
                    }
                } else {
                    Judgment::Proven
                };
            }

            let Some((operator, left, right)) = self.comparison_polynomials(fact) else {
                return Judgment::Unknown {
                    goal_in_language: false,
                };
            };
            self.judge_comparison(operator, left, right)
        }

        fn judge_comparison(
            &mut self,
            operator: BinaryOperator,
            left: Polynomial,
            right: Polynomial,
        ) -> Judgment {
            let left = self.substituted(&left);
            let right = self.substituted(&right);
            let difference_rl = right.sub(&left);
            let difference_lr = left.sub(&right);

            if let Some(value) = difference_rl.constant_value() {
                let holds = match operator {
                    BinaryOperator::Less => !value.is_negative() && !value.is_zero(),
                    BinaryOperator::LessOrEqual => !value.is_negative(),
                    BinaryOperator::Greater => value.is_negative(),
                    BinaryOperator::GreaterOrEqual => value.is_negative() || value.is_zero(),
                    BinaryOperator::Equal => value.is_zero(),
                    BinaryOperator::NotEqual => !value.is_zero(),
                    _ => {
                        return Judgment::Unknown {
                            goal_in_language: false,
                        };
                    }
                };
                return if holds {
                    Judgment::Proven
                } else {
                    Judgment::ConstantFalse
                };
            }

            let zero = BigInt::zero();
            let one = BigInt::from_i64(1);
            let proved = match operator {
                BinaryOperator::Less => self.prove_at_least(&difference_rl, &one),
                BinaryOperator::LessOrEqual => self.prove_at_least(&difference_rl, &zero),
                BinaryOperator::Greater => self.prove_at_least(&difference_lr, &one),
                BinaryOperator::GreaterOrEqual => self.prove_at_least(&difference_lr, &zero),
                BinaryOperator::Equal => {
                    self.prove_at_least(&difference_rl, &zero)
                        && self.prove_at_least(&difference_lr, &zero)
                }
                BinaryOperator::NotEqual => self.proves_nonzero(&difference_lr),
                _ => {
                    return Judgment::Unknown {
                        goal_in_language: false,
                    };
                }
            };
            if proved {
                return Judgment::Proven;
            }

            let negation_proved = match operator {
                BinaryOperator::Less => self.prove_at_least(&difference_lr, &zero),
                BinaryOperator::LessOrEqual => self.prove_at_least(&difference_lr, &one),
                BinaryOperator::Greater => self.prove_at_least(&difference_rl, &zero),
                BinaryOperator::GreaterOrEqual => self.prove_at_least(&difference_rl, &one),
                BinaryOperator::Equal => self.proves_nonzero(&difference_lr),
                BinaryOperator::NotEqual => {
                    self.prove_at_least(&difference_rl, &zero)
                        && self.prove_at_least(&difference_lr, &zero)
                }
                _ => false,
            };
            if negation_proved {
                return Judgment::Refuted;
            }

            Judgment::Unknown {
                goal_in_language: true,
            }
        }
        pub(crate) fn conjuncts(&self, fact: ExpressionHandle) -> Vec<ExpressionHandle> {
            let node = self.program.expression_table.expression(fact).clone();
            match node {
                ExpressionNode::Binary(binary)
                    if binary.operator == BinaryOperator::And
                        && self.selected_binary_meaning(fact, &binary) =>
                {
                    let mut left = self.conjuncts(binary.left);
                    left.extend(self.conjuncts(binary.right));
                    left
                }
                ExpressionNode::Borrow(inner) => self.conjuncts(inner.target),
                _ => vec![fact],
            }
        }

        pub(crate) fn comparison_polynomials(
            &mut self,
            fact: ExpressionHandle,
        ) -> Option<(BinaryOperator, Polynomial, Polynomial)> {
            if self.is_mathematical_application(fact) {
                return self.mathematical_comparison(fact);
            }
            let node = self.program.expression_table.expression(fact).clone();
            let ExpressionNode::Binary(binary) = node else {
                return None;
            };
            if !self.selected_binary_meaning(fact, &binary) {
                return None;
            }
            if !binary.operator.is_comparison() {
                return None;
            }
            let left = self.normalize(binary.left)?;
            let right = self.normalize(binary.right)?;
            Some((binary.operator, left, right))
        }

        pub(crate) fn normalize(&mut self, expression: ExpressionHandle) -> Option<Polynomial> {
            if self.strict_symbol_bindings.is_some()
                && !expression_table(self.program).expression_is_valid(expression)
            {
                return None;
            }
            if let Some(value) =
                super::proof_integer::anonymous_integer_value(self.program, expression)
            {
                return Some(Polynomial::constant(value));
            }
            if let Some((_, value)) = self
                .strict_occurrences
                .iter()
                .find(|(candidate, _)| *candidate == expression)
            {
                return Some(value.clone());
            }
            if let Some(value) = self.formal_coordinate_value(expression) {
                return Some(value);
            }
            if self.strict_symbol_bindings.is_some()
                && !self.proof_integer_formation
                && let Some(value) = self
                    .program
                    .closed_integer_value_in(expression, self.source_owner)
            {
                return Some(Polynomial::constant(value.value));
            }
            let node = self.program.expression_table.expression(expression).clone();
            match node {
                ExpressionNode::Member(_)
                    if self.strict_symbol_bindings.is_some()
                        && !self.proof_integer_formation
                        && self.formal_arguments.is_none() =>
                {
                    let matched =
                        format!("\0{}", integer_source_identity(self.program, expression));
                    if let Some(replacement) = self.substitutions.get(&matched) {
                        return Some(replacement.clone());
                    }
                    let machine = self.program.machine(self.machine_symbol)?;
                    let root = member_receiver_root_symbol(self.program, expression);
                    if root != Some(self.machine_symbol) && root.is_some() {
                        return None;
                    }
                    let state = self.program.machine_states(machine).first()?;
                    let place_type = crate::value_custody::places::declared_place_type_raw(
                        self.program,
                        machine,
                        Some(state),
                        expression,
                    )?;
                    let carrier = self.program.primitive_type_reference(place_type).and_then(
                        |primitive| {
                            crate::proof_contracts::arithmetic_domains::primitive_range(primitive)
                        },
                    )?;
                    let interval =
                        crate::proof_contracts::arithmetic_domains::standing_integer_interval(
                            self.program,
                            machine,
                            state,
                            expression,
                        )
                        .unwrap_or(carrier);
                    let atom = format!("\0{}", integer_source_identity(self.program, expression));
                    self.arithmetic_intervals.insert(
                        atom.clone(),
                        Interval {
                            low: interval.low.map(BigInt::from_i64),
                            high: interval.high.map(BigInt::from_i64),
                        },
                    );
                    Some(Polynomial::atom(atom))
                }
                ExpressionNode::Member(_) => None,
                ExpressionNode::Integer(value) => Some(Polynomial::constant(value.value_bignum()?)),
                ExpressionNode::Borrow(inner) => self.normalize(inner.target),
                ExpressionNode::Name(path) => {
                    if let Some((_, value)) = self
                        .formal_arguments
                        .iter()
                        .flatten()
                        .find(|(symbol, _)| *symbol == path.symbol)
                    {
                        return Some(value.clone());
                    }
                    if self.program.symbols.builtin_type_member(path.symbol)
                        == Some(symbols::BuiltinTypeMember::AddressBound)
                    {
                        return self.address_model_bound();
                    }
                    if self.formal_arguments.is_some()
                        && !crate::reserved_result_place(self.program, expression)
                            .is_some_and(|place| place.machine_symbol == self.source_owner)
                    {
                        return self
                            .program
                            .closed_integer_value_in(expression, self.source_owner)
                            .map(|value| Polynomial::constant(value.value));
                    }
                    if let Some(bindings) = &self.strict_symbol_bindings {
                        let [member] =
                            expression_table(self.program).name_path_members(path.members)
                        else {
                            return None;
                        };
                        if let Some(value) = bindings.iter().find_map(|(symbol, value)| {
                            (*symbol == path.symbol).then(|| value.clone())
                        }) {
                            return Some(value);
                        }
                        return self
                            .strict_result_binding
                            .clone()
                            .filter(|_| member.as_str() == RESULT_BINDER);
                    }
                    let members = expression_table(self.program).name_path_members(path.members);
                    if members.len() != 1 {
                        return None;
                    }
                    let name = members[0].as_str().to_owned();
                    if !self.parameter_atoms.contains(&name) {
                        return None;
                    }
                    Some(Polynomial::atom(name))
                }
                ExpressionNode::Unary(unary) if unary.operator == UnaryOperator::BitwiseNot => {
                    let reference = self.source_result_type(expression)?;
                    let primitive = self.program.primitive_type_reference(reference)?;
                    let operand = self.normalize(unary.operand)?;
                    Self::integer_complement_value(primitive, &operand)
                }
                ExpressionNode::Unary(_) => None,
                ExpressionNode::Binary(binary)
                    if matches!(
                        binary.operator,
                        BinaryOperator::BitwiseAnd
                            | BinaryOperator::BitwiseOr
                            | BinaryOperator::BitwiseXor
                    ) =>
                {
                    self.selected_bitwise_value(expression, &binary)
                }
                ExpressionNode::Binary(binary)
                    if !self.selected_binary_meaning(expression, &binary)
                        && matches!(
                            binary.operator,
                            BinaryOperator::Add
                                | BinaryOperator::Subtract
                                | BinaryOperator::Multiply
                        )
                        && super::ranking_range::unselected_or_builtin_arithmetic(
                            self.program,
                            expression,
                        ) =>
                {
                    let left = self.normalize(binary.left)?;
                    let right = self.normalize(binary.right)?;
                    let value = match binary.operator {
                        BinaryOperator::Add => left.add(&right),
                        BinaryOperator::Subtract => left.sub(&right),
                        BinaryOperator::Multiply => left.checked_mul(&right)?,
                        _ => return None,
                    };
                    if let Some(result) = self.selected_policy_result(expression, value.clone()) {
                        return Some(result);
                    }
                    let primitive =
                        [binary.left, binary.right]
                            .into_iter()
                            .find_map(|operand| {
                                crate::proof_contracts::proof_embeddings::integer_embedding(
                                    self.program,
                                    operand,
                                )
                                .map(|embedding| embedding.primitive)
                                .filter(|primitive| primitive.is_fixed_integer())
                            })?;
                    self.integer_policy_value(
                        primitive,
                        numerics::arithmetic::ArithmeticDomain::Wrapping,
                        value,
                    )
                }
                ExpressionNode::Binary(binary)
                    if !self.selected_binary_meaning(expression, &binary) =>
                {
                    None
                }
                ExpressionNode::Binary(binary)
                    if matches!(
                        binary.operator,
                        BinaryOperator::ShiftLeft | BinaryOperator::ShiftRight
                    ) =>
                {
                    self.selected_exact_shift_value(expression, &binary)
                }
                ExpressionNode::Binary(binary)
                    if !proof_integer_expression(self.program, expression)
                        && matches!(
                            binary.operator,
                            BinaryOperator::Add
                                | BinaryOperator::Subtract
                                | BinaryOperator::Multiply
                                | BinaryOperator::Divide
                                | BinaryOperator::Modulo
                        )
                        && self
                            .source_result_type(expression)
                            .is_some_and(|reference| {
                                matches!(
                                    self.program.arithmetic_domain_for_type_reference(reference),
                                    numerics::arithmetic::ArithmeticDomain::Wrapping
                                        | numerics::arithmetic::ArithmeticDomain::Saturating
                                )
                            }) =>
                {
                    let left = self.normalize(binary.left)?;
                    let right = self.normalize(binary.right)?;
                    let value = self.integer_binary_value(binary.operator, left, right)?;
                    self.selected_policy_result(expression, value)
                }
                ExpressionNode::Binary(binary) => match binary.operator {
                    BinaryOperator::Add => {
                        let left = self.normalize(binary.left)?;
                        let right = self.normalize(binary.right)?;
                        self.selected_policy_result(expression, left.add(&right))
                    }
                    BinaryOperator::Subtract => {
                        let left = self.normalize(binary.left)?;
                        let right = self.normalize(binary.right)?;
                        self.selected_policy_result(expression, left.sub(&right))
                    }
                    BinaryOperator::Multiply => {
                        let left = self.normalize(binary.left)?;
                        let right = self.normalize(binary.right)?;
                        let product = left.checked_mul(&right)?;
                        self.selected_policy_result(expression, product)
                    }
                    BinaryOperator::Divide | BinaryOperator::Modulo => {
                        let dividend = self.normalize(binary.left)?;
                        let divisor = self.normalize(binary.right)?;
                        if self.strict_symbol_bindings.is_some()
                            && !self.proof_integer_formation
                            && self
                                .source_result_type(expression)
                                .is_some_and(|reference| {
                                    self.program
                                        .primitive_type_reference(reference)
                                        .is_some_and(|primitive| primitive.is_fixed_integer())
                                })
                        {
                            return self.integer_binary_value(binary.operator, dividend, divisor);
                        }
                        let builtin_proof_integer =
                            proof_integer_expression(self.program, expression)
                                && expression_table(self.program)
                                    .authored_selection_occurrences(expression)
                                    .all(|occurrence| {
                                        use language_semantics::declaration_selection::{
                                            AuthoredDeclarationSelectionIntrinsic as Intrinsic,
                                            AuthoredDeclarationSelectionLateBinding as LateBinding,
                                            AuthoredDeclarationSelectionTarget as Target,
                                        };
                                        self.program
                                            .authored_declaration_selections()
                                            .get(occurrence)
                                            .is_some_and(|selection| {
                                                matches!(
                                                    selection.target(),
                                                    Target::Intrinsic(Intrinsic::BuiltinOperator)
                                                        | Target::LateBound(
                                                            LateBinding::CheckedOperator
                                                        )
                                                )
                                            })
                                    });
                        if builtin_proof_integer
                            && let (Some(dividend), Some(divisor)) = (
                                self.substituted(&dividend).constant_value(),
                                self.substituted(&divisor).constant_value(),
                            )
                        {
                            let (quotient, remainder) = dividend.div_rem(&divisor)?;
                            return Some(Polynomial::constant(
                                if binary.operator == BinaryOperator::Divide {
                                    quotient
                                } else {
                                    remainder
                                },
                            ));
                        }
                        if builtin_proof_integer {
                            let divisor = self.substituted(&divisor);
                            if !self.proves_nonzero(&divisor) {
                                return None;
                            }
                            return self.integer_binary_value(
                                binary.operator,
                                self.substituted(&dividend),
                                divisor,
                            );
                        }
                        if binary.operator == BinaryOperator::Divide {
                            return None;
                        }
                        let modulus = self.substituted(&divisor).constant_value()?;
                        if modulus.is_zero() {
                            return None;
                        }
                        self.integer_remainder(dividend, Polynomial::constant(modulus), false)
                    }
                    _ => None,
                },
                ExpressionNode::Call(call) => {
                    if crate::mathematical_applications::is_mathematical_call(self.program, &call) {
                        return self.normalize_mathematical_application(expression);
                    }
                    if crate::proof_contracts::proof_embeddings::is_exact_embed_call(
                        self.program,
                        &call,
                    ) {
                        let (_, argument) =
                            crate::proof_contracts::proof_embeddings::integer_embedding_argument(
                                self.program,
                                expression,
                            )?;
                        return self.normalize_integer_embedding(argument);
                    }
                    if self.formal_arguments.is_some() {
                        let owner = super::specification_calls::selected_call_contract(
                            self.program,
                            self.source_owner,
                            &call,
                        )?;
                        let target = super::specification_calls::owner_symbol(&owner);
                        let parameters =
                            super::specification_calls::owner_parameters(self.program, &owner);
                        let supplied_arguments =
                            expression_table(self.program).expression_handles(call.arguments);
                        let arguments = supplied_arguments
                            .iter()
                            .map(|argument| {
                                if self
                                    .source_result_type(*argument)
                                    .and_then(|reference| {
                                        self.program.primitive_type_reference(reference)
                                    })
                                    .is_some()
                                    || crate::has_anonymous_numeric_results(self.program, *argument)
                                {
                                    self.normalize(*argument)
                                        .map(IntegerApplicationInput::Scalar)
                                } else {
                                    self.captured_record_call_input(
                                        *argument,
                                        parameters,
                                        supplied_arguments,
                                    )
                                }
                            })
                            .collect::<Option<Vec<_>>>()?;
                        return self.selected_call_value(
                            self.source_owner,
                            expression,
                            target,
                            arguments,
                        );
                    }
                    if self.strict_symbol_bindings.is_some()
                        && self.formal_arguments.is_none()
                        && let Some(interval) =
                            crate::proof_contracts::arithmetic_domains::call_result_interval(
                                self.program,
                                self.machine_symbol,
                                expression,
                                &call,
                            )
                    {
                        let atom = format!("\0call-result:{expression:?}");
                        self.arithmetic_intervals.insert(
                            atom.clone(),
                            Interval {
                                low: interval.low().map(BigInt::from_i64),
                                high: interval.high().map(BigInt::from_i64),
                            },
                        );
                        return Some(Polynomial::atom(atom));
                    }
                    None
                }
                ExpressionNode::Cast(cast)
                    if proof_nat_cast(self.program, &cast)
                        && (self.strict_symbol_bindings.is_none()
                            || self.proof_integer_formation) =>
                {
                    self.normalize(cast.value)
                }
                ExpressionNode::Cast(cast) if self.value_preserving_integer_cast(&cast) => {
                    self.normalize(cast.value)
                }
                ExpressionNode::Match(dispatch) => self.normalize_matched_integer(&dispatch),
                _ => None,
            }
        }

        fn normalize_matched_integer(
            &mut self,
            dispatch: &TableMatchExpression,
        ) -> Option<Polynomial> {
            let arms = expression_table(self.program)
                .match_arms(dispatch.arms)
                .to_vec();
            if arms.is_empty() {
                return None;
            }
            let mut joined = None;
            for arm in arms {
                let normalized = self.normalize(arm.value)?;
                let value = self.substituted(&normalized);
                match &joined {
                    None => joined = Some(value),
                    Some(previous) if previous == &value => {}
                    Some(_) => return None,
                }
            }
            joined
        }

        fn selected_policy_result(
            &mut self,
            expression: ExpressionHandle,
            value: Polynomial,
        ) -> Option<Polynomial> {
            use numerics::arithmetic::ArithmeticDomain;
            if proof_integer_expression(self.program, expression) {
                return Some(value);
            }
            let reference = self.source_result_type(expression)?;
            match self.program.arithmetic_domain_for_type_reference(reference) {
                ArithmeticDomain::Exact => Some(value),
                ArithmeticDomain::Wrapping | ArithmeticDomain::Saturating => {
                    let primitive = self.program.primitive_type_reference(reference)?;
                    self.integer_policy_value(
                        primitive,
                        self.program.arithmetic_domain_for_type_reference(reference),
                        value,
                    )
                }
                ArithmeticDomain::Trapping => None,
            }
        }

        fn value_preserving_integer_cast(&self, cast: &TableCastExpression) -> bool {
            if cast.form.is_recast() || self.proof_integer_formation {
                return false;
            }
            self.program
                .primitive_type_reference(cast.target_type)
                .is_some_and(|target| target.is_fixed_integer())
                && (matches!(
                    expression_table(self.program).expression(cast.value),
                    ExpressionNode::Integer(_)
                ) || crate::proof_contracts::proof_embeddings::integer_embedding(
                    self.program,
                    cast.value,
                )
                .is_some_and(|source| source.primitive.is_fixed_integer()))
        }

        fn is_mathematical_application(&self, expression: ExpressionHandle) -> bool {
            expression_table(self.program)
                .call_node(expression)
                .is_some_and(|call| {
                    crate::mathematical_applications::is_mathematical_call(self.program, call)
                })
        }

        pub(crate) fn address_model_bound(&mut self) -> Option<Polynomial> {
            let polynomial = self.address_model_bound_value()?;
            self.bounds.push((polynomial.clone(), BigInt::from_i64(1)));
            Some(polynomial)
        }

        fn address_model_bound_value(&self) -> Option<Polynomial> {
            let bound = self
                .program
                .symbols
                .builtin_type_member_symbol(symbols::BuiltinTypeMember::AddressBound)?;
            let model = self.program.symbols.get(bound).parent;
            (self.program.symbols.builtin_type_atom(model)
                == Some(symbols::BuiltinTypeAtom::Address))
            .then_some(())?;
            Some(Polynomial::atom(format!(
                "\0address-model-bound:{model:?}:{bound:?}"
            )))
        }

        fn normalize_integer_embedding(
            &mut self,
            expression: ExpressionHandle,
        ) -> Option<Polynomial> {
            let embedding = crate::proof_contracts::proof_embeddings::integer_embedding(
                self.program,
                expression,
            )?;
            if let Some(literal) = expression_table(self.program).integer_node(expression) {
                return Some(Polynomial::constant(literal.value_bignum()?));
            }
            let direct = self.normalize(expression);
            if direct.is_none()
                && (self.formal_arguments.is_some()
                    || self.strict_symbol_bindings.is_some() && !self.proof_integer_formation)
            {
                return None;
            }
            let polynomial = direct.unwrap_or_else(|| {
                Polynomial::atom(format!(
                    "\0embed:{:?}:{}",
                    embedding.primitive,
                    integer_source_identity(self.program, expression),
                ))
            });
            self.bounds
                .push((polynomial.clone(), embedding.interval.low?));
            if let Some(maximum) = embedding.interval.high {
                self.bounds.push((polynomial.neg(), maximum.negate()));
            } else {
                let bound = self.address_model_bound()?;
                self.bounds
                    .push((bound.sub(&polynomial), BigInt::from_i64(1)));
            }
            self.refresh_difference_bounds();
            Some(polynomial)
        }
    }

    fn unsigned_parameter_carrier(
        program: &dyn CheckingInput,
        reference: TypeReferenceHandle,
    ) -> bool {
        program
            .type_reference_table
            .primitive_type(reference)
            .is_some_and(|primitive| !primitive.is_signed_integer())
    }

    fn member_receiver_root_symbol(
        program: &dyn CheckingInput,
        expression: ExpressionHandle,
    ) -> Option<SymbolHandle> {
        let mut handle = expression;
        loop {
            match expression_table(program).expression(handle) {
                ExpressionNode::Member(member) => handle = member.receiver,
                ExpressionNode::Borrow(inner) => handle = inner.target,
                ExpressionNode::Name(path) => {
                    return path.symbol.is_valid().then_some(path.symbol);
                }
                _ => return None,
            }
        }
    }

    fn integer_source_identity(
        program: &dyn CheckingInput,
        expression: ExpressionHandle,
    ) -> String {
        match expression_table(program).expression(expression) {
            ExpressionNode::Name(path) if path.symbol.is_valid() => {
                format!("name:{:?}", path.symbol)
            }
            ExpressionNode::Integer(literal) => format!("literal:{literal:?}"),
            ExpressionNode::Binary(binary) => format!(
                "binary:{:?}({},{})",
                binary.operator,
                integer_source_identity(program, binary.left),
                integer_source_identity(program, binary.right)
            ),
            ExpressionNode::Cast(cast) => format!(
                "cast:{:?}:{:?}:{:?}:{}",
                cast.target_type,
                cast.domain,
                cast.semantic_domain_id,
                integer_source_identity(program, cast.value)
            ),
            ExpressionNode::Member(member) if member.member_symbol.is_valid() => format!(
                "member:{:?}:{:?}:{}",
                member.member_symbol,
                member.case_variant,
                integer_source_identity(program, member.receiver)
            ),
            ExpressionNode::Indexed(indexed) => format!(
                "index:{}:{}",
                integer_source_identity(program, indexed.collection),
                integer_source_identity(program, indexed.index)
            ),
            ExpressionNode::Call(call) if call.target_symbol.is_valid() => {
                let plans = crate::machine_calls::calls::operand_call_plans(program, None);
                if !crate::machine_calls::denotational_calls::expression_values_have_call_identity(
                    program,
                    expression,
                    &plans.0,
                    &plans.1,
                    &|_| false,
                ) {
                    return format!("occurrence:{expression:?}");
                }
                format!(
                    "call:{:?}:{:?}:{}:{:?}",
                    call.target_symbol,
                    call.machine_arguments,
                    integer_source_identity(program, call.receiver),
                    expression_table(program)
                        .expression_handles(call.arguments)
                        .iter()
                        .map(|argument| integer_source_identity(program, *argument))
                        .collect::<Vec<_>>(),
                )
            }
            _ => format!("occurrence:{expression:?}"),
        }
    }
}
