    #[derive(Debug, Clone, PartialEq, Eq)]
    pub enum ScopedArithmeticBinder {
        Type(symbols::SymbolHandle),
        Symbol(symbols::SymbolHandle),
        DeclaredRead(crate::DeclaredInputRead),
        Occurrence(ExpressionHandle),
        Result,
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    pub enum ScopedArithmeticValue {
        TypeReference(typed_trees::types::TypeReferenceHandle),
        OwnedSnapshot(crate::CapturedOwnedSnapshot),
        CapturedInteger(crate::CapturedIntegerDenotation),
        Atom {
            identity: String,
            unsigned: bool,
        },
        BoundedInteger {
            value: Box<Self>,
            interval: BigIntInterval,
        },
        Integer(numerics::bignum::BigInt),
        IntegerOperation {
            operator: BinaryOperator,
            left: Box<Self>,
            right: Box<Self>,
        },
        Term(ScopedArithmeticExpression),
        CollectionLength(ScopedArithmeticExpression),
        AdmittedIntegerRemainder(ScopedArithmeticExpression),
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    pub struct ScopedArithmeticBinding {
        pub binder: ScopedArithmeticBinder,
        pub value: ScopedArithmeticValue,
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    pub struct ScopedArithmeticExpression {
        pub owner: symbols::SymbolHandle,
        pub expression: ExpressionHandle,
        pub bindings: Vec<ScopedArithmeticBinding>,
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    pub struct ScopedArithmeticHypothesis {
        pub proposition: ScopedArithmeticExpression,
        pub holds: bool,
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    pub struct ScopedArithmeticComparison {
        pub operator: BinaryOperator,
        pub left: ScopedArithmeticValue,
        pub right: ScopedArithmeticValue,
    }

    pub fn scoped_arithmetic_comparisons_unsatisfiable(
        program: &dyn crate::CheckingInput,
        context_machine: &Machine,
        comparisons: &[ScopedArithmeticComparison],
    ) -> bool {
        let mut calls = calls::ScopedCalls::new(program, context_machine);
        let mut engine = Engine::strict(program, context_machine, &[]);
        let mut normalized = Vec::with_capacity(comparisons.len());
        for comparison in comparisons {
            if !matches!(
                comparison.operator,
                BinaryOperator::Less
                    | BinaryOperator::LessOrEqual
                    | BinaryOperator::Greater
                    | BinaryOperator::GreaterOrEqual
                    | BinaryOperator::Equal
                    | BinaryOperator::NotEqual
            ) {
                return false;
            }
            let Some(left) = calls
                .value(&comparison.left)
                .and_then(|value| engine.normalize_scoped_value(&value))
            else {
                return false;
            };
            let Some(right) = calls
                .value(&comparison.right)
                .and_then(|value| engine.normalize_scoped_value(&value))
            else {
                return false;
            };
            normalized.push((comparison.operator, left, right));
        }
        let Some(hypotheses) = calls.hypotheses(&[]) else {
            return false;
        };
        if !install_hypotheses(program, &mut engine, &hypotheses) {
            return false;
        }
        engine.integer_comparisons_unsatisfiable(normalized)
    }

    #[derive(Clone)]
    pub struct ScopedCallResultObservation {
        pub expression: ExpressionHandle,
        pub path: Vec<facts::PlaceSegment>,
        pub primitive_type: typed_trees::types::PrimitiveType,
        pub value: ScopedArithmeticValue,
        pub read_dependencies: Vec<String>,
        pub(crate) backing: Option<crate::machine_calls::calls::CapturedStorageReadBacking>,
    }

    pub(crate) struct PendingScopedCallResultObservation {
        pub observation: ScopedCallResultObservation,
        pub declaration_root: ExpressionHandle,
        pub cases: Vec<ScalarProjectionCaseRequirement>,
        pub indices: Vec<ScalarProjectionIndexRequirement>,
        pub requires_backing: bool,
    }

    pub(crate) struct ScalarProjectionCaseRequirement {
        pub prefix_length: usize,
        pub variant: symbols::SymbolHandle,
    }

    pub(crate) struct ScalarProjectionIndexRequirement {
        pub prefix_length: usize,
        pub index: usize,
    }

    pub(crate) fn scalar_projection_requirements(
        program: &dyn crate::CheckingInput,
        reference: typed_trees::types::TypeReferenceHandle,
        path: &[facts::PlaceSegment],
    ) -> Option<(
        Vec<ScalarProjectionCaseRequirement>,
        Vec<ScalarProjectionIndexRequirement>,
    )> {
        let mut cases = Vec::new();
        let mut indices = Vec::new();
        for (prefix_length, segment) in path.iter().enumerate() {
            let current = crate::project_type_reference_from_segments(
                program,
                reference,
                &path[..prefix_length],
            )?;
            match segment {
                facts::PlaceSegment::Case { variant } => {
                    cases.push(ScalarProjectionCaseRequirement {
                        prefix_length,
                        variant: *variant,
                    })
                }
                facts::PlaceSegment::FixedIndex { index } => {
                    let collection = crate::unwrapped_type_reference(program, current)?;
                    if matches!(
                        program.type_reference_table.type_reference(collection),
                        typed_trees::types::TypeReferenceNode::Slice { .. }
                    ) {
                        indices.push(ScalarProjectionIndexRequirement {
                            prefix_length,
                            index: *index,
                        });
                    }
                }
                _ => {}
            }
        }
        Some((cases, indices))
    }

