pub(crate) mod structural_terms {
    use crate::frozen_program::expression_table;
    use symbols::JoinedPath;
    use typed_trees::expression::{ExpressionHandle, ExpressionNode, StaticMachineArgument};

    use super::StructuralTerm;

    pub(crate) fn borrow_term_in_scope(
        program: &dyn crate::CheckingInput,
        scope: Option<(
            &typed_trees::machine::Machine,
            &typed_trees::state::State,
            typed_trees::types::TypeReferenceHandle,
        )>,
        frame: Option<(
            symbols::SymbolHandle,
            &[typed_trees::signature::StateParameter],
        )>,
        expression: ExpressionHandle,
        value: StructuralTerm,
    ) -> Option<StructuralTerm> {
        let ExpressionNode::Borrow(borrow) = expression_table(program).expression(expression)
        else {
            return None;
        };
        if borrow.access != language_semantics::ReferenceAccess::Shared
            || matches!(value, StructuralTerm::ObservedValue { .. })
        {
            return Some(value);
        }
        let reference = |expression| {
            if let Some((owner, parameters)) = frame {
                crate::parameter_expression_result_type_reference(
                    program, owner, parameters, expression,
                )
            } else {
                let (machine, state, _) = scope?;
                crate::expression_result_type_reference(program, machine, state, expression)
            }
        };
        let declared = reference(borrow.target)?;
        if crate::reference_shell(program, declared).is_some() {
            return Some(value);
        }
        let source = completed_owned_carrier(program, &value).unwrap_or(declared);
        crate::declared_carriers_match(program, declared, source).then_some(())?;
        // Borrowing an owned value keeps its typed contents as the predicate
        // subject. Erasing this shell lets symbolic fields bypass the descriptor
        // boundary that the later completed argument correctly retains.
        shared_inline_observation(
            program,
            reference(expression)?,
            owned_projection_observation(program, source, value),
        )
    }

    pub(crate) mod binary {
        use super::StructuralTerm;
        use symbols::SymbolHandle;
        use typed_trees::expression::{BinaryOperator, ExpressionHandle, ExpressionNode};
        use typed_trees::machine::Machine;
        use typed_trees::signature::StateParameter;
        use typed_trees::state::State;
        use typed_trees::types::TypeReferenceHandle;

        pub(crate) fn unary_term_in_scope(
            program: &dyn crate::CheckingInput,
            scope: Option<(&Machine, &State, TypeReferenceHandle)>,
            frame: Option<(SymbolHandle, &[StateParameter])>,
            expression: ExpressionHandle,
            operand: StructuralTerm,
        ) -> Option<StructuralTerm> {
            let ExpressionNode::Unary(unary) = program.expression_table.expression(expression)
            else {
                return None;
            };
            let reference = if let Some((owner, parameters)) = frame {
                crate::parameter_expression_result_type_reference(
                    program,
                    owner,
                    parameters,
                    unary.operand,
                )
            } else {
                let (machine, state, _) = scope?;
                crate::expression_result_type_reference(program, machine, state, unary.operand)
            };
            if unary.operator == typed_trees::expression::UnaryOperator::BitwiseNot {
                let reference = reference?;
                let (primitive, _) = super::scalar_operand_meaning(program, reference, &operand)?;
                let corner = super::super::arithmetic_judgment::Engine::integer_complement_corner(
                    primitive,
                )?;
                let result = if let Some((owner, parameters)) = frame {
                    crate::parameter_expression_result_type_reference(
                        program, owner, parameters, expression,
                    )
                } else {
                    let (machine, state, _) = scope?;
                    crate::expression_result_type_reference(program, machine, state, expression)
                }?;
                if program.primitive_type_reference(result) != Some(primitive) {
                    return None;
                }
                // At a checked fixed width, complement is corner minus the value:
                // the unsigned maximum or signed -1 supplies the full bit width.
                // Both source observations survive this mathematical interpretation.
                let value = StructuralTerm::MathematicalBinary {
                    operator: BinaryOperator::Subtract,
                    left: Box::new(StructuralTerm::Integer(corner)),
                    right: Box::new(super::owned_projection_observation(
                        program, reference, operand,
                    )),
                };
                return Some(super::owned_projection_observation(program, result, value));
            }
            if unary.operator != typed_trees::expression::UnaryOperator::LogicalNot {
                return None;
            }
            if reference.and_then(|reference| program.primitive_type_reference(reference))
                != Some(typed_trees::types::PrimitiveType::Bool)
            {
                return operand
                    .is_checked_predicate()
                    .then(|| StructuralTerm::LogicalNot {
                        operand: Box::new(operand),
                    });
            }
            let reference = reference?;
            let meaning = super::scalar_operand_meaning(program, reference, &operand)?;
            Some(StructuralTerm::ScalarBinary {
                references: [reference; 2],
                operator: BinaryOperator::Equal,
                meaning: [meaning; 2],
                left: Box::new(operand),
                right: Box::new(StructuralTerm::boolean(false)),
            })
        }

        pub(crate) fn binary_term_in_scope(
            program: &dyn crate::CheckingInput,
            scope: Option<(&Machine, &State, TypeReferenceHandle)>,
            frame: Option<(SymbolHandle, &[StateParameter])>,
            expression: ExpressionHandle,
            left: StructuralTerm,
            right: StructuralTerm,
        ) -> Option<StructuralTerm> {
            let binary = program.expression_table.binary_node(expression)?;
            let state_scope = scope
                .map(|(machine, state, _)| (machine, state))
                .or_else(|| {
                    if frame.is_some() {
                        return None;
                    }
                    expression_scope(program, expression, 0)
                        .and_then(|symbol| scoped_machine_state(program, symbol))
                });
            let owner = frame
                .map(|(owner, _)| owner)
                .or_else(|| state_scope.map(|(machine, _)| machine.symbol))?;
            let expected = scope.map(|(_, _, expected)| expected);
            let expression_type = |expression| {
                if let Some((owner, parameters)) = frame {
                    crate::parameter_expression_result_type_reference(
                        program, owner, parameters, expression,
                    )
                } else {
                    let (machine, state) = state_scope?;
                    crate::expression_result_type_reference(program, machine, state, expression)
                }
            };
            let references = [binary.left, binary.right].map(expression_type);
            if binary.operator == BinaryOperator::CaseMembership {
                return None;
            }
            let spelling =
                crate::proof_contracts::parameter_expression_meaning::spelled_binary_operator(
                    binary.operator,
                );
            if let Some(spelling) = spelling
                && !typed_trees::operator::has_builtin_spelled_expression_meaning(
                    program,
                    owner,
                    expression,
                    spelling,
                    &references,
                )
            {
                if let Some(term) = sealed_primitive_float_scalar(
                    program,
                    owner,
                    expression,
                    &references,
                    left.clone(),
                    right.clone(),
                ) {
                    return Some(term);
                }
                if references.iter().any(Option::is_none)
                    || !typed_trees::operator::selected_trait_operator_meanings(
                        program,
                        owner,
                        spelling,
                        &references,
                    )
                    .is_empty()
                {
                    return None;
                }
                let candidates = typed_trees::operator::resolve_spelling_for_operands(
                    program,
                    spelling,
                    &references,
                    program.expression_table.source_span(expression),
                );
                let [selected] = candidates.as_slice() else {
                    return None;
                };
                if !crate::machine_calls::denotational_calls::selected_operator_has_closed_value_denotation(
            program,
            selected.operator,
        ) {
            return None;
        }
                let result_type = expression_type(expression)?;
                let name = program
                    .operator_path_members(selected.operator.name)
                    .last()?;
                return Some(StructuralTerm::Application {
                    result_type,
                    target: selected.operator.symbol,
                    selections: Vec::new(),
                    machine: super::structural_call_machine_name(name.as_str(), &[], &[]),
                    arguments: vec![left, right],
                });
            }
            if let Some(term) = super::builtin_anonymous_comparison_term(program, expression) {
                return Some(term);
            }
            if super::super::proof_integer::mathematical_integer_operands(
                program,
                [binary.left, binary.right],
            ) {
                if matches!(
                    binary.operator,
                    BinaryOperator::Divide | BinaryOperator::Modulo
                ) {
                    return None;
                }
                return Some(StructuralTerm::MathematicalBinary {
                    operator: binary.operator,
                    left: Box::new(left),
                    right: Box::new(right),
                });
            }
            let references =
                crate::value_custody::expression_types::builtin_scalar_operand_references(
                    program, binary, references, expected,
                )?;
            let meaning = [
                super::scalar_operand_meaning(program, references[0], &left)?,
                super::scalar_operand_meaning(program, references[1], &right)?,
            ];
            Some(StructuralTerm::ScalarBinary {
                references,
                operator: binary.operator,
                meaning,
                left: Box::new(left),
                right: Box::new(right),
            })
        }

        pub(crate) fn sealed_primitive_float_operator(
            program: &dyn crate::CheckingInput,
            owner: SymbolHandle,
            expression: ExpressionHandle,
            operand_types: &[Option<TypeReferenceHandle>],
        ) -> Option<BinaryOperator> {
            let operation = program.expression_table.binary_node(expression)?.operator;
            crate::proof_contracts::bound_expression_meaning::
        sealed_float_comparison_declaration_for_operands(
        program,
        owner,
        expression,
        operation,
        operand_types,
            )?;
            Some(operation)
        }

        fn sealed_primitive_float_scalar(
            program: &dyn crate::CheckingInput,
            owner: SymbolHandle,
            expression: ExpressionHandle,
            references: &[Option<TypeReferenceHandle>; 2],
            left: StructuralTerm,
            right: StructuralTerm,
        ) -> Option<StructuralTerm> {
            let operation =
                sealed_primitive_float_operator(program, owner, expression, references)?;
            let [Some(left_type), Some(right_type)] = *references else {
                return None;
            };
            let meaning = [
                super::scalar_operand_meaning(program, left_type, &left)?,
                super::scalar_operand_meaning(program, right_type, &right)?,
            ];
            Some(StructuralTerm::ScalarBinary {
                references: [left_type, right_type],
                operator: operation,
                meaning,
                left: Box::new(left),
                right: Box::new(right),
            })
        }

        pub(crate) fn scoped_machine_state(
            program: &dyn crate::CheckingInput,
            symbol: SymbolHandle,
        ) -> Option<(&Machine, &State)> {
            let mut owner = symbol;
            let mut visited = Vec::new();
            loop {
                if !owner.is_valid() || visited.contains(&owner) {
                    return None;
                }
                visited.push(owner);
                if let Some(selected) = program.machines().iter().find_map(|machine| {
                    program
                        .state_in_machine(machine, owner)
                        .map(|state| (machine, state))
                }) {
                    return Some(selected);
                }
                if let Some(machine) = program.machine(owner) {
                    return Some((machine, program.machine_states(machine).first()?));
                }
                owner = program.symbols.get(owner).parent;
            }
        }

        pub(crate) fn expression_scope(
            program: &dyn crate::CheckingInput,
            expression: ExpressionHandle,
            depth: usize,
        ) -> Option<SymbolHandle> {
            if depth >= 32 {
                return None;
            }
            match program.expression_table.expression(expression) {
                ExpressionNode::Name(path) => path.symbol.is_valid().then_some(path.symbol),
                ExpressionNode::Binary(binary) => expression_scope(program, binary.left, depth + 1)
                    .or_else(|| expression_scope(program, binary.right, depth + 1)),
                ExpressionNode::Member(member) => {
                    expression_scope(program, member.receiver, depth + 1)
                }
                ExpressionNode::Indexed(indexed) => {
                    expression_scope(program, indexed.collection, depth + 1)
                        .or_else(|| expression_scope(program, indexed.index, depth + 1))
                }
                ExpressionNode::Cast(cast) => expression_scope(program, cast.value, depth + 1),
                _ => None,
            }
        }
    }
    pub(crate) mod mathematical {
        use super::StructuralTerm;
        use crate::mathematical_applications::{
            PreparedApplication, PreparedCapture, PreparedConstantMeaning,
            PreparedMathematicalView, PreparedSourceBinding, PreparedSourceBindingKind,
        };
        use numerics::literals::FloatLiteral;
        use proof_admission::{Term, TermHandle};
        use typed_trees::expression::{BinaryOperator, ExpressionHandle};

        pub(crate) fn application_term(
            program: &dyn crate::CheckingInput,
            expression: ExpressionHandle,
            mut observe: impl FnMut(&PreparedCapture) -> Option<StructuralTerm>,
        ) -> Option<StructuralTerm> {
            let view = program.prepared_mathematics()?;
            let application = view.application(expression)?;
            let captures = view
                .applications
                .captures
                .span_or_empty(application.captures)
                .iter()
                .map(|capture| {
                    let mut value = observe(capture)?;
                    let mut value_type = capture.source_type;
                    if crate::reference_shell(program, capture.source_type).is_some()
                        && program
                            .primitive_type_reference(capture.observation_type)
                            .is_some()
                    {
                        crate::mathematical_applications::subject_observation_type_reference(
                            program,
                            capture.source_type,
                            capture.observation_type,
                        )?;
                        if !super::scalar_operand_is_observed(program, capture.source_type, &value)
                        {
                            return None;
                        }
                        // This receives an existing checked read. A descriptor
                        // alone cannot acquire the selected scalar carrier.
                        value = super::owned_projection_observation(
                            program,
                            capture.observation_type,
                            value.into_semantic_value(),
                        );
                        value_type = capture.observation_type;
                    }
                    let embeds_integer =
                        program
                            .primitive_type_reference(value_type)
                            .is_some_and(|primitive| {
                                primitive.is_fixed_integer()
                                    || primitive == typed_trees::types::PrimitiveType::Addr
                            });
                    let value = if embeds_integer {
                        StructuralTerm::IntegerEmbedding {
                            reference: value_type,
                            value: Box::new(value),
                        }
                    } else if crate::reference_shell(program, capture.source_type).is_none()
                        && crate::value_custody::places::data_definition_for_type(
                            program,
                            capture.source_type,
                        )
                        .is_some()
                    {
                        super::owned_projection_observation(program, capture.source_type, value)
                    } else {
                        value
                    };
                    Some(Some(value))
                })
                .collect::<Option<Vec<_>>>()?;
            read_term(program, view, application, application.term, &captures, 0)
        }

        fn read_term(
            program: &dyn crate::CheckingInput,
            view: PreparedMathematicalView<'_>,
            application: &PreparedApplication,
            term: TermHandle,
            captures: &[Option<StructuralTerm>],
            depth: usize,
        ) -> Option<StructuralTerm> {
            if depth >= 128 {
                return None;
            }
            let read = |term| read_term(program, view, application, term, captures, depth + 1);
            let source_captures = view
                .applications
                .captures
                .span_or_empty(application.captures)
                .len();
            let inserted_binders =
                u32::try_from(captures.len().checked_sub(source_captures)?).ok()?;
            if let Some((carrier, [left, right])) =
                view.identity_value(application, term, inserted_binders)
            {
                return Some(StructuralTerm::Identity {
                    carrier: carrier.type_identity,
                    left: Box::new(read(left)?),
                    right: Box::new(read(right)?),
                });
            }
            match view.arena.get(term) {
                Term::TwoZero | Term::TwoOne => {
                    Some(boolean(matches!(view.arena.get(term), Term::TwoOne)))
                }
                Term::Variable(index) => captures
                    .get(captures.len().checked_sub(index as usize + 1)?)?
                    .clone(),
                Term::Squash { ty } => read(ty),
                Term::Id { ty, left, right } if matches!(view.arena.get(ty), Term::Two) => {
                    let reference =
                        crate::proof_contracts::bound_expression_meaning::builtin_type_reference(
                            program,
                            symbols::BuiltinTypeAtom::Bool,
                        )?;
                    let meaning = (
                        typed_trees::types::PrimitiveType::Bool,
                        program.arithmetic_domain_for_type_reference(reference),
                    );
                    Some(StructuralTerm::ScalarBinary {
                        references: [reference; 2],
                        operator: BinaryOperator::Equal,
                        meaning: [meaning; 2],
                        left: Box::new(read(left)?),
                        right: Box::new(read(right)?),
                    })
                }
                Term::Id { ty, left, right } => {
                    let Term::Constant { declaration, .. } = view.arena.get(ty) else {
                        return None;
                    };
                    if !matches!(
                        view.constant(declaration),
                        Some(
                            PreparedConstantMeaning::IntegerCarrier
                                | PreparedConstantMeaning::AddressCarrier
                        )
                    ) {
                        return None;
                    }
                    Some(binary(BinaryOperator::Equal, read(left)?, read(right)?))
                }
                Term::Sigma { domain, codomain } => {
                    let mut extended = captures.to_vec();
                    extended.push(None);
                    if matches!(view.arena.get(domain), Term::Two) {
                        let Term::CaseTwo {
                            zero_branch,
                            one_branch,
                            scrutinee,
                            ..
                        } = view.arena.get(codomain)
                        else {
                            return None;
                        };
                        if !matches!(view.arena.get(scrutinee), Term::Variable(0)) {
                            return None;
                        }
                        return Some(binary(
                            BinaryOperator::Or,
                            read_term(
                                program,
                                view,
                                application,
                                zero_branch,
                                &extended,
                                depth + 1,
                            )?,
                            read_term(
                                program,
                                view,
                                application,
                                one_branch,
                                &extended,
                                depth + 1,
                            )?,
                        ));
                    }
                    Some(binary(
                        BinaryOperator::And,
                        read(domain)?,
                        read_term(program, view, application, codomain, &extended, depth + 1)?,
                    ))
                }
                _ => {
                    let (declaration, arguments) =
                        crate::mathematical_applications::application_spine(view, term)?;
                    match (view.constant(declaration)?, arguments.as_slice()) {
                        (PreparedConstantMeaning::Integer(value), []) => {
                            Some(StructuralTerm::Integer(value.clone()))
                        }
                        (PreparedConstantMeaning::FloatLiteral { format, bits }, []) => Some(
                            StructuralTerm::Float(FloatLiteral::from_bits(*format, *bits)?),
                        ),
                        (
                            PreparedConstantMeaning::FloatRelation {
                                operator,
                                reference,
                                ..
                            },
                            [left, right],
                        ) => {
                            let primitive = program.primitive_type_reference(*reference)?;
                            let domain = program.arithmetic_domain_for_type_reference(*reference);
                            Some(StructuralTerm::ScalarBinary {
                                references: [*reference; 2],
                                operator: *operator,
                                meaning: [(primitive, domain); 2],
                                left: Box::new(read(*left)?),
                                right: Box::new(read(*right)?),
                            })
                        }
                        (PreparedConstantMeaning::AddressBound(symbol), [])
                            if program.symbols.builtin_type_member(*symbol)
                                == Some(symbols::BuiltinTypeMember::AddressBound) =>
                        {
                            Some(StructuralTerm::BoundValue(*symbol))
                        }
                        (
                            PreparedConstantMeaning::IntegerOperation(operator)
                            | PreparedConstantMeaning::IntegerRelation(operator),
                            [left, right],
                        ) => Some(binary(*operator, read(*left)?, read(*right)?)),
                        (PreparedConstantMeaning::IntegerEmbedding { .. }, [argument]) => {
                            read(*argument)
                        }
                        (PreparedConstantMeaning::Negation, [proposition]) => {
                            let operand = read(*proposition)?;
                            if let StructuralTerm::MathematicalBinary {
                                operator,
                                left,
                                right,
                            } = &operand
                                && let Some(operator) = operator.complement()
                            {
                                return Some(StructuralTerm::MathematicalBinary {
                                    operator,
                                    left: left.clone(),
                                    right: right.clone(),
                                });
                            }
                            Some(StructuralTerm::LogicalNot {
                                operand: Box::new(operand),
                            })
                        }
                        (
                            PreparedConstantMeaning::SourceOperation {
                                expression,
                                owner,
                                source_type,
                                bindings,
                            },
                            arguments,
                        ) => {
                            match source_operation_term(
                                program,
                                *expression,
                                *owner,
                                *source_type,
                                bindings,
                                arguments,
                                read,
                            ) {
                                Ok(value) => Some(value),
                                Err(reason) => {
                                    if super::super::struct_trace() {
                                        eprintln!(
                                            "source value {:?} under {:?} cannot be read: {reason}",
                                            expression, owner
                                        );
                                    }
                                    None
                                }
                            }
                        }
                        // Opaque and source-selected operations have no builtin
                        // arithmetic law merely because their kernel result is Int.
                        _ => None,
                    }
                }
            }
        }

        /// Rejoin only the producer-recorded occurrence, under its own lexical scope.
        /// The checked spine supplies the actual dependency values; observing the
        /// occurrence must never recover the producer's unsubstituted formal instead.
        fn source_operation_term(
            program: &dyn crate::CheckingInput,
            expression: ExpressionHandle,
            owner: symbols::SymbolHandle,
            source_type: typed_trees::types::TypeReferenceHandle,
            bindings: &[PreparedSourceBinding],
            arguments: &[TermHandle],
            read: impl Fn(TermHandle) -> Option<StructuralTerm>,
        ) -> Result<StructuralTerm, String> {
            if bindings.len() != arguments.len() {
                return Err(format!(
                    "dependency arity {} differs from checked argument arity {}",
                    bindings.len(),
                    arguments.len()
                ));
            }
            if !program.expression_table.expression_is_valid(expression) || !owner.is_valid() {
                return Err(
                    "the retained source occurrence or lexical owner is unavailable".to_owned(),
                );
            }
            let mut values = Vec::with_capacity(bindings.len());
            for (position, (binding, argument)) in bindings.iter().zip(arguments).enumerate() {
                if binding.kind == PreparedSourceBindingKind::Type {
                    return Err(format!(
                        "type dependency {position} has no ordinary source type substitution"
                    ));
                }
                let value = read(*argument).ok_or_else(|| {
                    format!("value dependency {position} has no readable actual value")
                })?;
                values.push(value);
            }
            let scope = crate::machine_calls::calls::machine_state_by_symbol(program, owner)
                .or_else(|| {
                    let machine = program.machine_by_symbol(owner)?;
                    Some((machine, program.machine_states(machine).first()?))
                });
            let mut parameters = if let Some(definition) = program
                .mathematical_definitions()
                .iter()
                .find(|definition| definition.symbol == owner)
            {
                crate::mathematical_applications::ordinary_parameters(program, definition)
            } else if let Some((_, state)) = scope {
                program.state_parameters(state).to_vec()
            } else {
                return Err("the retained lexical owner has no declaration telescope".to_owned());
            };
            // Copied contract roots can use fresh formals. Their exact source types
            // come from the producer's own dependency census, not from the Id goal.
            for binding in bindings {
                if binding.symbol.is_valid() && binding.source_type.is_valid() {
                    if let Some(parameter) = parameters
                        .iter_mut()
                        .find(|parameter| parameter.symbol == binding.symbol)
                    {
                        parameter.type_reference = binding.source_type;
                    } else {
                        parameters.push(typed_trees::signature::StateParameter {
                            symbol: binding.symbol,
                            name: program.symbols.name(binding.symbol).into(),
                            type_reference: binding.source_type,
                            ..Default::default()
                        });
                    }
                }
            }
            let ambiguous_symbol = std::cell::Cell::new(false);
            let substitute = |candidate| {
                if let Some((_, value)) = bindings
                    .iter()
                    .zip(&values)
                    .find(|(binding, _)| binding.expressions.contains(&candidate))
                {
                    return Some(value.clone());
                }
                let typed_trees::expression::ExpressionNode::Name(path) =
                    program.expression_table.expression(candidate)
                else {
                    return None;
                };
                if !path.symbol.is_valid() {
                    return None;
                }
                let mut candidates = bindings
                    .iter()
                    .zip(&values)
                    .filter(|(binding, _)| binding.symbol == path.symbol);
                let (_, value) = candidates.next()?;
                if candidates.next().is_some() {
                    // None alone would permit the observer to recover a raw formal.
                    // Preserve this refusal across that callback boundary instead.
                    ambiguous_symbol.set(true);
                    return None;
                }
                Some(value.clone())
            };
            let value = super::structural_term(
                program,
                scope.map(|(machine, state)| (machine, state, source_type)),
                Some((owner, &parameters)),
                expression,
                Some(&substitute),
            );
            if ambiguous_symbol.get() {
                return Err("a source symbol has multiple actual dependency bindings without an exact occurrence association".to_owned());
            }
            let value = value.ok_or_else(|| "the retained occurrence has no complete selected structural value after dependency substitution".to_owned())?;
            Ok(if source_type.is_valid() {
                super::owned_projection_observation(program, source_type, value)
            } else {
                value
            })
        }

        fn binary(
            operator: BinaryOperator,
            left: StructuralTerm,
            right: StructuralTerm,
        ) -> StructuralTerm {
            StructuralTerm::MathematicalBinary {
                operator,
                left: Box::new(left),
                right: Box::new(right),
            }
        }

        fn boolean(value: bool) -> StructuralTerm {
            StructuralTerm::boolean(value)
        }
    }
    pub(crate) use mathematical::application_term as mathematical_application_term;
    pub(crate) mod collection_measures {
        use super::StructuralTerm;
        use language_semantics::declaration_selection::CollectionMeasure;
        use typed_trees::expression::TableMemberExpression;
        use typed_trees::types::FixedArrayLength;
        use typed_trees::types::TypeReferenceHandle;

        pub(crate) fn collection_measure_term(
            program: &dyn crate::CheckingInput,
            member: &TableMemberExpression,
            receiver: TypeReferenceHandle,
            collection: impl FnOnce() -> Option<StructuralTerm>,
        ) -> Option<StructuralTerm> {
            let measure =
                crate::value_custody::places::collection_operations::collection_measure_member(
                    program,
                    member,
                    crate::value_custody::places::collection_operations::MeasureReceiver::Declared(
                        receiver,
                    ),
                )?;
            observed_collection_measure(program, receiver, measure, collection)
        }

        pub(crate) fn observed_collection_measure(
            program: &dyn crate::CheckingInput,
            receiver: TypeReferenceHandle,
            measure: CollectionMeasure,
            collection: impl FnOnce() -> Option<StructuralTerm>,
        ) -> Option<StructuralTerm> {
            if measure == CollectionMeasure::Length
                && let Some(extent) = fixed_array_extent_term(program, receiver)
            {
                return Some(extent);
            }
            crate::slice_view_shell(program, receiver, &[])?;
            let collection = collection()?.into_collection_descriptor();
            collection.observation_identity_key()?;
            Some(StructuralTerm::CollectionMeasure {
                measure,
                collection: Box::new(collection),
            })
        }

        pub(crate) fn reference_argument_observation(
            program: &dyn crate::CheckingInput,
            declared: TypeReferenceHandle,
            descriptor: &StructuralTerm,
            referent: Option<StructuralTerm>,
        ) -> Option<StructuralTerm> {
            if crate::slice_view_shell(program, declared, &[]).is_some() {
                Some(match referent {
                    Some(value) => StructuralTerm::ObservedValue {
                        observed_type: declared,
                        value: Box::new(value),
                        descriptor: Some(Box::new(descriptor.clone().into_collection_descriptor())),
                    },
                    None => descriptor_only_observation(declared, descriptor.clone()),
                })
            } else {
                referent
            }
        }

        pub(crate) fn descriptor_only_observation(
            declared: TypeReferenceHandle,
            descriptor: StructuralTerm,
        ) -> StructuralTerm {
            StructuralTerm::ObservedValue {
                observed_type: declared,
                value: Box::new(StructuralTerm::Opaque(
                    "unobserved slice contents".to_owned(),
                )),
                descriptor: Some(Box::new(descriptor.into_collection_descriptor())),
            }
        }

        pub(crate) fn completed_collection_measure(
            program: &dyn crate::CheckingInput,
            measure: CollectionMeasure,
            collection: &StructuralTerm,
        ) -> Option<StructuralTerm> {
            if measure != CollectionMeasure::Length {
                return None;
            }
            let reference = match collection {
                StructuralTerm::CapturedValue { result_type, .. }
                | StructuralTerm::Application { result_type, .. } => *result_type,
                StructuralTerm::IndexedValue { element_type, .. } => *element_type,
                StructuralTerm::Projection { .. } => {
                    super::completed_owned_carrier(program, collection)?
                }
                _ => return None,
            };
            fixed_array_extent_term(program, reference)
        }

        fn fixed_array_extent_term(
            program: &dyn crate::CheckingInput,
            reference: TypeReferenceHandle,
        ) -> Option<StructuralTerm> {
            match crate::value_custody::places::fixed_array_type_extent(program, reference)? {
                FixedArrayLength::Literal(extent) => Some(StructuralTerm::Integer(
                    numerics::bignum::BigInt::from_u64(u64::try_from(*extent).ok()?),
                )),
                FixedArrayLength::ConstParameter { symbol, .. } if symbol.is_valid() => {
                    Some(StructuralTerm::BoundValue(*symbol))
                }
                _ => None,
            }
        }
    }
    pub(crate) use collection_measures::{
        collection_measure_term, completed_collection_measure, descriptor_only_observation,
        observed_collection_measure, reference_argument_observation,
    };
    pub(crate) mod constructors {
        use crate::frozen_program::expression_table;
        use numerics::bignum::BigInt;
        use numerics::literals::FloatLiteral;
        use symbols::SymbolHandle;
        use typed_trees::data::{DataDefinition, DataField, DataMember, DataVariant};
        use typed_trees::expression::ExpressionNode;
        use typed_trees::expression::{
            ExpressionHandle, TableStructLiteral, TableStructLiteralField,
        };
        use typed_trees::types::{
            PrimitiveType, TypeConstraintNode, TypeReferenceHandle, TypeReferenceNode,
        };

        use super::super::structural_judgment::ConstructorIdentity;
        use super::StructuralTerm;

        pub(crate) fn admitted_const_value_term(
            program: &dyn crate::CheckingInput,
            reference: TypeReferenceHandle,
            value: &language_semantics::const_value::CanonicalConstIdentity,
        ) -> Option<StructuralTerm> {
            fn decoded(
                program: &dyn crate::CheckingInput,
                reference: TypeReferenceHandle,
                value: language_semantics::const_value::DecodedCanonicalConstValue,
            ) -> Option<StructuralTerm> {
                use language_semantics::const_value::DecodedCanonicalConstValue;
                let reference = program
                    .type_reference_table
                    .unconstrained_type_reference(reference);
                let (data, case, fields) = match value {
                    DecodedCanonicalConstValue::Integer { value, .. } => {
                        return Some(StructuralTerm::Integer(BigInt::from_i128(value)));
                    }
                    DecodedCanonicalConstValue::Boolean(value) => {
                        return (program.type_reference_table.primitive_type(reference)
                            == Some(PrimitiveType::Bool))
                        .then(|| StructuralTerm::boolean(value));
                    }
                    DecodedCanonicalConstValue::Record { type_name, fields } => {
                        (type_name, None, fields)
                    }
                    DecodedCanonicalConstValue::Variant {
                        type_name,
                        case_name,
                        fields,
                    } => (type_name, Some(case_name), fields),
                    DecodedCanonicalConstValue::Array { .. }
                    | DecodedCanonicalConstValue::Float { .. } => {
                        return None;
                    }
                };
                let symbol = program.type_reference_table.type_head_symbol(reference)?;
                let definition = program.data_constructor_definition(reference, symbol)?;
                if definition.name.as_str() != data {
                    return None;
                }
                let variant = match case.as_deref() {
                    None => None,
                    Some(name) => {
                        let mut selected = program.data_members(definition).iter().filter_map(
                            |member| match member {
                                DataMember::Variant(variant) if variant.name.as_str() == name => {
                                    Some(variant)
                                }
                                _ => None,
                            },
                        );
                        let variant = selected.next()?;
                        if selected.next().is_some() {
                            return None;
                        }
                        Some(variant)
                    }
                };
                let declared = constructor_fields(program, definition, variant);
                if fields.len() != declared.len() {
                    return None;
                }
                let fields = fields
                    .into_iter()
                    .map(|(name, value)| {
                        let field = declared.iter().find(|field| field.name.as_str() == name)?;
                        Some((name, decoded(program, field.type_reference, value)?))
                    })
                    .collect::<Option<Vec<_>>>()?;
                let identity =
                    ConstructorIdentity::at_reference(program, reference, definition, variant)?;
                Some(constructed_term(identity, definition, variant, fields))
            }
            decoded(program, reference, value.decode_encoding()?)
        }

        pub(crate) fn is_case_observation(
            program: &dyn crate::CheckingInput,
            expression: ExpressionHandle,
        ) -> bool {
            matches!(expression_table(program).expression(expression), ExpressionNode::Binary(binary) if binary.operator == typed_trees::expression::BinaryOperator::CaseMembership)
                || expression_table(program)
                    .authored_selection_occurrences(expression)
                    .any(|occurrence| {
                        program
                            .authored_declaration_selections()
                            .get(occurrence)
                            .is_some_and(|selection| {
                                selection.kind()
                                    == typed_trees::AuthoredDeclarationSelectionKind::CaseMembership
                            })
                    })
        }

        pub(crate) fn case_guard_classifier<'program>(
            program: &'program dyn crate::CheckingInput,
            machine: &typed_trees::machine::Machine,
            state: Option<&typed_trees::state::State>,
            expression: ExpressionHandle,
        ) -> Option<(&'program DataDefinition, &'program DataVariant)> {
            use typed_trees::expression::BinaryOperator;
            let comparison = expression_table(program).binary_node(expression)?;
            let (definition, variant) = case_classifier(program, comparison.right)?;
            let membership =
                crate::proof_contracts::bound_expression_meaning::has_exact_case_membership_meaning(
                    program, machine, state, expression, comparison,
                );
            let fieldless_equality = comparison.operator == BinaryOperator::Equal
                && !is_case_observation(program, expression)
                && crate::has_builtin_binary_expression_meaning(
                    program, machine, state, expression,
                )
                && constructor_fields(program, definition, Some(variant)).is_empty();
            (membership || fieldless_equality).then_some((definition, variant))
        }

        pub(crate) fn case_classifier(
            program: &dyn crate::CheckingInput,
            expression: ExpressionHandle,
        ) -> Option<(&DataDefinition, &DataVariant)> {
            let definition =
                crate::proof_contracts::bound_expression_meaning::exact_case_reference_owner(
                    program, expression,
                )?;
            let ExpressionNode::Name(path) = expression_table(program).expression(expression)
            else {
                return None;
            };
            let variant =
                program
                    .data_members(definition)
                    .iter()
                    .find_map(|member| match member {
                        DataMember::Variant(variant) if variant.symbol == path.symbol => {
                            Some(variant)
                        }
                        _ => None,
                    })?;
            Some((definition, variant))
        }

        pub(crate) fn case_value_term(
            program: &dyn crate::CheckingInput,
            expression: ExpressionHandle,
        ) -> Option<StructuralTerm> {
            let (definition, variant) = case_classifier(program, expression)?;
            if !program.data_payload_fields(variant).is_empty() {
                return None;
            }
            let fields = constructor_fields(program, definition, Some(variant))
                .into_iter()
                .map(|field| {
                    if field.relevance.is_erased() {
                        return None;
                    }
                    Some((
                        field.name.as_str().to_owned(),
                        zero_value_structural_term(program, field.type_reference)?,
                    ))
                })
                .collect::<Option<Vec<_>>>()?;
            Some(constructed_term(
                ConstructorIdentity::nominal(program, definition, Some(variant))?,
                definition,
                Some(variant),
                fields,
            ))
        }

        pub(crate) fn constructor_literal_term(
            program: &dyn crate::CheckingInput,
            expression: ExpressionHandle,
            literal: &TableStructLiteral,
            mut field_term: impl FnMut(
                &DataField,
                Option<&TableStructLiteralField>,
            ) -> Option<StructuralTerm>,
        ) -> Option<StructuralTerm> {
            let definition =
                crate::value_custody::struct_literals::selected_construction_definition(
                    program, expression, literal,
                )?;
            let variant = match literal.case_symbol {
                Some(_) => Some(
                    crate::value_custody::struct_literals::selected_construction_case(
                        program, expression, literal, definition,
                    )?,
                ),
                None => {
                    if literal.case_name.is_some()
                        || program
                            .data_members(definition)
                            .iter()
                            .any(|member| matches!(member, DataMember::Variant(_)))
                    {
                        return None;
                    }
                    None
                }
            };
            let declared = constructor_fields(program, definition, variant);
            let supplied = expression_table(program).struct_fields(literal.fields);
            let selected_fields = supplied
                .iter()
                .map(|field| {
                    crate::value_custody::struct_literals::selected_construction_field(
                        program,
                        expression,
                        literal,
                        field.field_symbol,
                    )
                })
                .collect::<Option<Vec<_>>>()?;
            if selected_fields.iter().any(|field| {
                !declared
                    .iter()
                    .any(|declared| field.symbol.is_valid() && declared.symbol == field.symbol)
            }) {
                return None;
            }
            let reference = crate::value_custody::struct_literals::construction_application(
                program, expression,
            );
            let identity =
                ConstructorIdentity::at_reference(program, reference, definition, variant)?;
            complete_constructor_term(
                identity,
                definition,
                variant,
                declared.into_iter(),
                |field| {
                    let mut matches =
                        supplied
                            .iter()
                            .zip(&selected_fields)
                            .filter_map(|(supplied, selected)| {
                                (selected.symbol == field.symbol).then_some(supplied)
                            });
                    let value = if let Some(supplied) = matches.next() {
                        if matches.next().is_some() {
                            return None;
                        }
                        field_term(field, Some(supplied))?
                    } else {
                        if field.relevance.is_erased()
                            || crate::value_custody::data::type_requires_establishment(
                                program,
                                field.type_reference,
                            )
                            || crate::proof_only_classification(program)
                                .proof_only_mention(program, field.type_reference)
                                .is_some()
                        {
                            return None;
                        }
                        zero_value_structural_term(program, field.type_reference)
                            .or_else(|| field_term(field, None))?
                    };
                    Some(value)
                },
            )
        }

        pub(crate) fn captured_constructor_term(
            program: &dyn crate::CheckingInput,
            definition: &DataDefinition,
            variant: Option<&DataVariant>,
            field_value: impl FnMut(&DataField) -> Option<StructuralTerm>,
        ) -> Option<StructuralTerm> {
            complete_constructor_term(
                ConstructorIdentity::nominal(program, definition, variant)?,
                definition,
                variant,
                constructor_fields(program, definition, variant).into_iter(),
                field_value,
            )
        }

        fn complete_constructor_term<'field>(
            identity: ConstructorIdentity,
            definition: &DataDefinition,
            variant: Option<&DataVariant>,
            declared: impl ExactSizeIterator<Item = &'field DataField>,
            mut field_value: impl FnMut(&DataField) -> Option<StructuralTerm>,
        ) -> Option<StructuralTerm> {
            let mut fields = Vec::with_capacity(declared.len());
            for field in declared {
                fields.push((field.name.as_str().to_owned(), field_value(field)?));
            }
            Some(constructed_term(identity, definition, variant, fields))
        }

        fn constructor_fields<'program>(
            program: &'program dyn crate::CheckingInput,
            definition: &'program DataDefinition,
            variant: Option<&'program DataVariant>,
        ) -> Vec<&'program DataField> {
            program
                .data_members(definition)
                .iter()
                .filter_map(|member| match member {
                    DataMember::Field(field) => Some(field),
                    DataMember::Variant(_) => None,
                })
                .chain(
                    variant
                        .into_iter()
                        .flat_map(|variant| program.data_payload_fields(variant)),
                )
                .collect()
        }

        fn constructed_term(
            identity: ConstructorIdentity,
            definition: &DataDefinition,
            variant: Option<&DataVariant>,
            mut fields: Vec<(String, StructuralTerm)>,
        ) -> StructuralTerm {
            fields.sort_by(|(left, _), (right, _)| left.cmp(right));
            StructuralTerm::Constructor {
                identity,
                data: definition.name.as_str().to_owned(),
                case: variant
                    .map(|variant| variant.name.as_str())
                    .unwrap_or("")
                    .to_owned(),
                fields,
            }
        }

        pub(crate) fn zero_value_structural_term(
            program: &dyn crate::CheckingInput,
            type_reference: TypeReferenceHandle,
        ) -> Option<StructuralTerm> {
            if !type_reference.is_valid()
                || crate::proof_only_classification(program)
                    .proof_only_mention(program, type_reference)
                    .is_some()
            {
                return None;
            }
            zero_term(program, type_reference, &mut Vec::new())
        }

        fn zero_term(
            program: &dyn crate::CheckingInput,
            type_reference: TypeReferenceHandle,
            active: &mut Vec<SymbolHandle>,
        ) -> Option<StructuralTerm> {
            if crate::value_custody::data::type_requires_establishment(program, type_reference) {
                return None;
            }
            if let TypeReferenceNode::Constrained {
                base_type,
                constraints,
            } = program.type_reference_table.type_reference(type_reference)
            {
                for constraint in program.type_reference_table.constraints(*constraints) {
                    match constraint {
                        TypeConstraintNode::ArithmeticDomain(_) => {}

                        TypeConstraintNode::Domain(_) | TypeConstraintNode::Named(_) => {
                            return None;
                        }
                    }
                }
                return zero_term(program, *base_type, active);
            }
            if let Some(primitive) = program.type_reference_table.primitive_type(type_reference) {
                return match primitive {
                    PrimitiveType::Bool => Some(StructuralTerm::boolean(false)),
                    PrimitiveType::F32 | PrimitiveType::F64 => Some(StructuralTerm::Float(
                        FloatLiteral::from_f64(0.0).with_landing(
                            if primitive == PrimitiveType::F32 {
                                numerics::literals::FloatFormat::F32
                            } else {
                                numerics::literals::FloatFormat::F64
                            },
                        ),
                    )),
                    primitive if primitive.accepts_integer_literal() => {
                        Some(StructuralTerm::Integer(BigInt::zero()))
                    }
                    _ => None,
                };
            }
            if let TypeReferenceNode::FixedArray {
                element_type,
                length: typed_trees::types::FixedArrayLength::Literal(length),
            } = program.type_reference_table.type_reference(type_reference)
            {
                let element = if *length == 0 {
                    None
                } else {
                    Some(Box::new(zero_term(program, *element_type, active)?))
                };
                return Some(StructuralTerm::RepeatedArray {
                    length: u64::try_from(*length).ok()?,
                    element,
                });
            }
            let symbol = program
                .type_reference_table
                .type_head_symbol(type_reference)?;
            if !symbol.is_valid() || active.contains(&symbol) {
                return None;
            }
            let definition = program.data_constructor_definition(type_reference, symbol)?;
            if crate::value_custody::data::data_requires_establishment(program, definition) {
                return None;
            }
            active.push(symbol);
            let value = zero_constructor(program, definition, Some(type_reference), active);
            active.pop();
            value
        }

        pub(crate) fn zero_constructor_operands(
            program: &dyn crate::CheckingInput,
            definition: &DataDefinition,
        ) -> Option<StructuralTerm> {
            zero_constructor(
                program,
                definition,
                definition.generic_instance,
                &mut vec![definition.symbol],
            )
        }

        fn zero_constructor(
            program: &dyn crate::CheckingInput,
            definition: &DataDefinition,
            reference: Option<TypeReferenceHandle>,
            active: &mut Vec<SymbolHandle>,
        ) -> Option<StructuralTerm> {
            let variant = program
                .data_members(definition)
                .iter()
                .find_map(|member| match member {
                    DataMember::Variant(variant) => Some(variant),
                    DataMember::Field(_) => None,
                });
            let fields = constructor_fields(program, definition, variant)
                .into_iter()
                .map(|field| {
                    if field.relevance.is_erased() {
                        return None;
                    }
                    Some((
                        field.name.as_str().to_owned(),
                        zero_term(program, field.type_reference, active)?,
                    ))
                })
                .collect::<Option<Vec<_>>>();
            let identity = match reference {
                Some(reference) => {
                    ConstructorIdentity::at_reference(program, reference, definition, variant)?
                }
                None => ConstructorIdentity::nominal(program, definition, variant)?,
            };
            Some(constructed_term(identity, definition, variant, fields?))
        }
    }
    pub(crate) use entry_reads::immutable_entry_boolean_projection;
    pub(crate) mod entry_reads {
        use crate::frozen_program::expression_table;
        use language_core::ReferenceAccess;
        use numerics::arithmetic::ArithmeticDomain;
        use symbols::SymbolHandle;
        use typed_trees::expression::{ExpressionHandle, ExpressionNode};
        use typed_trees::machine::Machine;
        use typed_trees::state::State;
        use typed_trees::types::{TypeReferenceHandle, TypeReferenceNode};

        #[derive(Debug, Clone, PartialEq, Eq)]
        pub struct ImmutableEntryReadIdentity {
            machine: SymbolHandle,
            state: SymbolHandle,
            value: String,
        }

        impl ImmutableEntryReadIdentity {
            pub(crate) fn has_scope(&self, machine: SymbolHandle, state: SymbolHandle) -> bool {
                self.machine == machine && self.state == state
            }
        }

        pub fn immutable_entry_integer_projection(
            program: &dyn crate::CheckingInput,
            predicate: SymbolHandle,
            expression: ExpressionHandle,
        ) -> Option<(usize, Vec<facts::PlaceSegment>)> {
            let (position, projection, reference) =
                immutable_entry_scalar_projection(program, predicate, expression)?;
            (program
                .primitive_type_reference(reference)?
                .is_fixed_integer()
                && program.arithmetic_domain_for_type_reference(reference)
                    == ArithmeticDomain::Exact)
                .then_some((position, projection))
        }

        pub(crate) fn immutable_entry_boolean_projection(
            program: &dyn crate::CheckingInput,
            predicate: SymbolHandle,
            expression: ExpressionHandle,
        ) -> Option<(usize, Vec<facts::PlaceSegment>)> {
            let (position, projection, reference) =
                immutable_entry_scalar_projection(program, predicate, expression)?;
            (program.primitive_type_reference(reference)?
                == typed_trees::types::PrimitiveType::Bool)
                .then_some((position, projection))
        }

        fn immutable_entry_scalar_projection(
            program: &dyn crate::CheckingInput,
            predicate: SymbolHandle,
            expression: ExpressionHandle,
        ) -> Option<(usize, Vec<facts::PlaceSegment>, TypeReferenceHandle)> {
            let machine = program.machine(predicate)?;
            let entry = program.machine_states(machine).first()?;
            let reference = immutable_formal_expression(program, machine, entry, expression, 0)?;
            let place =
                crate::value_custody::places::canonical_place_from_expression(program, expression)?;
            if !place.segments.iter().all(|segment| {
                matches!(
                    segment,
                    facts::PlaceSegment::Field { .. } | facts::PlaceSegment::FixedIndex { .. }
                )
            }) {
                return None;
            }
            let position = program
                .state_parameters(entry)
                .iter()
                .position(|parameter| Some(parameter.symbol) == place.root.as_symbol())?;
            Some((position, place.segments, reference))
        }

        pub fn immutable_entry_indexed_read_identity(
            program: &dyn crate::CheckingInput,
            expression: ExpressionHandle,
        ) -> Option<ImmutableEntryReadIdentity> {
            expression_table(program).indexed_node(expression)?;
            let symbol = super::binary::expression_scope(program, expression, 0)?;
            let (machine, state) = super::binary::scoped_machine_state(program, symbol)?;
            let reference = immutable_formal_expression(program, machine, state, expression, 0)?;
            if !program
                .primitive_type_reference(reference)?
                .is_fixed_integer()
                || program.arithmetic_domain_for_type_reference(reference)
                    != ArithmeticDomain::Exact
            {
                return None;
            }
            let term = super::structural_term(
                program,
                Some((machine, state, state.return_type)),
                Some((machine.symbol, program.state_parameters(state))),
                expression,
                None,
            )?;
            Some(ImmutableEntryReadIdentity {
                machine: machine.symbol,
                state: state.symbol,
                value: term.observation_identity_key()?,
            })
        }

        pub fn instantiate_immutable_entry_indexed_read_identity(
            program: &dyn crate::CheckingInput,
            predicate: SymbolHandle,
            expression: ExpressionHandle,
            arguments: &[ExpressionHandle],
            caller_machine: &Machine,
            caller_state: &State,
        ) -> Option<ImmutableEntryReadIdentity> {
            let machine = program.machine(predicate)?;
            let entry = program.machine_states(machine).first()?;
            let parameters = program.state_parameters(entry);
            if parameters.len() != arguments.len() {
                return None;
            }
            expression_table(program).indexed_node(expression)?;
            let reference = immutable_formal_expression(program, machine, entry, expression, 0)?;
            if !program
                .primitive_type_reference(reference)?
                .is_fixed_integer()
                || program.arithmetic_domain_for_type_reference(reference)
                    != ArithmeticDomain::Exact
            {
                return None;
            }
            let mut actuals = Vec::new();
            for (parameter, argument) in parameters.iter().zip(arguments) {
                immutable_formal_expression(program, caller_machine, caller_state, *argument, 0)?;
                let reference = crate::expression_result_type_reference(
                    program,
                    caller_machine,
                    caller_state,
                    *argument,
                )?;
                if !crate::declared_carriers_match(program, parameter.type_reference, reference) {
                    return None;
                }
                actuals.push(super::structural_term(
                    program,
                    Some((caller_machine, caller_state, caller_state.return_type)),
                    Some((
                        caller_machine.symbol,
                        program.state_parameters(caller_state),
                    )),
                    *argument,
                    None,
                )?);
            }
            let bindings = |expression| {
                let ExpressionNode::Name(name) = expression_table(program).expression(expression)
                else {
                    return None;
                };
                let position = parameters
                    .iter()
                    .position(|parameter| parameter.symbol == name.symbol)?;
                actuals.get(position).cloned()
            };
            let term = super::structural_term(
                program,
                Some((machine, entry, entry.return_type)),
                Some((machine.symbol, parameters)),
                expression,
                Some(&bindings),
            )?;
            Some(ImmutableEntryReadIdentity {
                machine: caller_machine.symbol,
                state: caller_state.symbol,
                value: term.observation_identity_key()?,
            })
        }

        fn immutable_formal_expression(
            program: &dyn crate::CheckingInput,
            machine: &Machine,
            state: &State,
            expression: ExpressionHandle,
            depth: usize,
        ) -> Option<TypeReferenceHandle> {
            if depth >= 32 {
                return None;
            }
            let reference = match expression_table(program).expression(expression) {
                ExpressionNode::Name(name) => {
                    if !name.symbol.is_valid()
                        || name.head_symbol != name.symbol
                        || expression_table(program)
                            .name_path_members(name.members)
                            .len()
                            != 1
                    {
                        return None;
                    }
                    let parameter = program.state_parameters(state).iter().find(|parameter| {
                        parameter.symbol == name.symbol && !parameter.is_mutable
                    })?;
                    match crate::reference_shell(program, parameter.type_reference) {
                        Some(shell) if shell.access == ReferenceAccess::Shared => shell.referee,
                        Some(_) => return None,
                        None => parameter.type_reference,
                    }
                }
                ExpressionNode::Member(member) => {
                    if member.case_variant.is_some() {
                        return None;
                    }
                    let receiver = immutable_formal_expression(
                        program,
                        machine,
                        state,
                        member.receiver,
                        depth + 1,
                    )?;
                    let symbol = crate::value_custody::places::effective_member_symbol(
                        program,
                        member.receiver,
                        member,
                    );
                    crate::owned_projection_type_reference(
                        program,
                        receiver,
                        &[facts::PlaceSegment::Field { symbol }],
                    )?
                }
                ExpressionNode::Indexed(indexed) => {
                    if !crate::value_custody::places::place_has_builtin_coordinates(
                        program,
                        machine,
                        Some(state),
                        expression,
                    ) || expression_table(program).indexed_on_range(indexed)
                    {
                        return None;
                    }
                    let collection = immutable_formal_expression(
                        program,
                        machine,
                        state,
                        indexed.collection,
                        depth + 1,
                    )?;
                    let contextual_count = expression_table(program)
                        .integer_node(indexed.index)
                        .is_some_and(|literal| literal.landing().is_none());
                    if !contextual_count {
                        let selector = immutable_formal_expression(
                            program,
                            machine,
                            state,
                            indexed.index,
                            depth + 1,
                        )?;
                        if !program
                            .primitive_type_reference(selector)?
                            .is_fixed_integer()
                            || program.arithmetic_domain_for_type_reference(selector)
                                != ArithmeticDomain::Exact
                        {
                            return None;
                        }
                    }
                    let collection = crate::value_custody::places::unwrapped_type_reference(
                        program, collection,
                    )?;
                    let TypeReferenceNode::FixedArray { element_type, .. } =
                        program.type_reference_table.type_reference(collection)
                    else {
                        return None;
                    };
                    *element_type
                }
                ExpressionNode::Borrow(borrow) if borrow.access == ReferenceAccess::Shared => {
                    immutable_formal_expression(program, machine, state, borrow.target, depth + 1)?
                }
                ExpressionNode::Integer(_) => {
                    crate::expression_result_type_reference(program, machine, state, expression)?
                }
                _ => return None,
            };
            crate::reference_shell(program, reference)
                .is_none()
                .then_some(reference)
        }
    }
    pub(crate) mod equality {
        use symbols::SymbolHandle;
        use typed_trees::expression::{BinaryOperator, ExpressionHandle};
        use typed_trees::signature::StateParameter;
        use typed_trees::types::{PrimitiveType, TypeReferenceHandle, TypeReferenceNode};

        pub(crate) fn has_identity_equality_meaning(
            program: &dyn crate::CheckingInput,
            scope: SymbolHandle,
            parameters: &[StateParameter],
            expression: ExpressionHandle,
        ) -> bool {
            let Some(binary) = program.expression_table.binary_node(expression) else {
                return false;
            };
            let spelling = match binary.operator {
                BinaryOperator::Equal => language_core::OperatorSpelling::Equal,
                BinaryOperator::NotEqual => language_core::OperatorSpelling::NotEqual,
                _ => return false,
            };
            let types = [binary.left, binary.right].map(|operand| {
                crate::parameter_expression_result_type_reference(
                    program, scope, parameters, operand,
                )
            });
            // Select with complete declaration types before interpreting a builtin
            // scalar read. A reference overload still sees its descriptor type;
            // readable scalar contents do not authorize aggregate descriptor identity.
            if !typed_trees::operator::has_builtin_spelled_expression_meaning(
                program, scope, expression, spelling, &types,
            ) {
                return false;
            }
            let Some(types) =
                crate::value_custody::expression_types::builtin_scalar_operand_references(
                    program, binary, types, None,
                )
            else {
                return false;
            };
            types.iter().all(|reference| {
                let reference = *reference;
                if let Some((primitive, _)) =
                    crate::value_custody::expression_types::scalar_observation_meaning(program, reference)
                {
                    !matches!(primitive, PrimitiveType::F32 | PrimitiveType::F64)
                } else {
                    matches!(program.type_reference_table.type_reference(reference),
                        TypeReferenceNode::Named { symbol, .. } if matches!(program.symbols.builtin_type_atom(*symbol),
                            Some(symbols::BuiltinTypeAtom::Int | symbols::BuiltinTypeAtom::UInt)))
                }
            })
        }

        /// Complete builtin scalar carriers whose selected comparison can imply Id.
        /// This supplies neither operand observations nor comparison truth.
        pub(crate) fn builtin_identity_operand_references(
            program: &dyn crate::CheckingInput,
            scope: SymbolHandle,
            parameters: &[StateParameter],
            expression: ExpressionHandle,
        ) -> Option<[TypeReferenceHandle; 2]> {
            let binary = program.expression_table.binary_node(expression)?;
            let spelling = match binary.operator {
                BinaryOperator::Equal => language_core::OperatorSpelling::Equal,
                BinaryOperator::NotEqual => language_core::OperatorSpelling::NotEqual,
                _ => return None,
            };
            let types = [binary.left, binary.right].map(|operand| {
                crate::parameter_expression_result_type_reference(
                    program, scope, parameters, operand,
                )
            });
            if !typed_trees::operator::has_builtin_spelled_expression_meaning(
                program, scope, expression, spelling, &types,
            ) {
                return None;
            }
            let references =
                crate::value_custody::expression_types::builtin_scalar_operand_references(
                    program, binary, types, None,
                )?;
            // Only specified, same-carrier owned primitive comparisons imply Id.
            // Aggregate/custom comparisons require separate checked bridge evidence;
            // reading equal referent contents never identifies their descriptors.
            if references.iter().any(|reference| {
                crate::reference_shell(program, *reference).is_some()
                    || !program
                        .primitive_type_reference(*reference)
                        .is_some_and(|primitive| {
                            primitive.is_fixed_integer()
                                || matches!(primitive, PrimitiveType::Bool | PrimitiveType::Addr)
                        })
            }) || program.normalized_type_identity(references[0])
                != program.normalized_type_identity(references[1])
            {
                return None;
            }
            Some(references)
        }
    }
    pub use entry_reads::{
        ImmutableEntryReadIdentity, immutable_entry_indexed_read_identity,
        immutable_entry_integer_projection, instantiate_immutable_entry_indexed_read_identity,
    };
    pub(crate) mod indexed {
        use super::StructuralTerm;
        use symbols::SymbolHandle;
        use typed_trees::expression::ExpressionHandle;
        use typed_trees::machine::Machine;
        use typed_trees::signature::StateParameter;
        use typed_trees::state::State;
        use typed_trees::types::TypeReferenceHandle;

        pub(crate) fn indexed_term_in_scope(
            program: &dyn crate::CheckingInput,
            scope: Option<(&Machine, &State, TypeReferenceHandle)>,
            frame: Option<(SymbolHandle, &[StateParameter])>,
            expression: ExpressionHandle,
            collection: StructuralTerm,
            index: StructuralTerm,
        ) -> Option<StructuralTerm> {
            let indexed = program.expression_table.indexed_node(expression)?;
            if program.expression_table.indexed_on_range(indexed) {
                return None;
            }
            let state_scope = scope
                .map(|(machine, state, _)| (machine, state))
                .or_else(|| {
                    super::binary::expression_scope(program, expression, 0)
                        .and_then(|symbol| super::binary::scoped_machine_state(program, symbol))
                });
            let frame = frame.or_else(|| {
                let result = crate::reserved_result_place(program, expression)?;
                let parameters =
                    crate::proof_contracts::contract_results::source_contract_parameters(
                        program,
                        result.machine_symbol,
                        result.root,
                    )?;
                Some((result.machine_symbol, parameters))
            });
            let owner = frame
                .map(|(owner, _)| owner)
                .or_else(|| state_scope.map(|(machine, _)| machine.symbol))?;
            let expression_type = |expression| {
                if let Some((owner, parameters)) = frame {
                    crate::parameter_expression_result_type_reference(
                        program, owner, parameters, expression,
                    )
                } else {
                    let (machine, state) = state_scope?;
                    crate::expression_result_type_reference(program, machine, state, expression)
                }
            };
            let references = [indexed.collection, indexed.index].map(expression_type);
            if references[0].is_none()
                || !typed_trees::operator::builtin_index_read_is_spelled(
                    program,
                    owner,
                    expression,
                    &references,
                )
            {
                return None;
            }
            let element_type = expression_type(expression)?;
            if !super::scalar_operand_is_observed(program, references[0]?, &collection)
                || references[1].is_some_and(|reference| {
                    !super::scalar_operand_is_observed(program, reference, &index)
                })
            {
                return None;
            }
            let owned = super::owned_observation_type(program, &collection).is_some();
            let selected = StructuralTerm::IndexedValue {
                element_type,
                element_identity: program.normalized_type_identity(element_type),
                collection: Box::new(if owned {
                    collection.into_semantic_value()
                } else {
                    collection
                }),
                index: Box::new(index),
            };
            Some(if crate::reference_shell(program, element_type).is_some() {
                super::descriptor_only_observation(element_type, selected)
            } else if owned {
                super::owned_projection_observation(program, element_type, selected)
            } else {
                selected
            })
        }
    }
    pub(crate) use indexed::indexed_term_in_scope;
    pub(crate) mod owned_observations {
        use super::StructuralTerm;
        use typed_trees::types::{TypeReferenceHandle, TypeReferenceNode};

        pub(crate) fn owned_observation_type(
            program: &dyn crate::CheckingInput,
            value: &StructuralTerm,
        ) -> Option<TypeReferenceHandle> {
            let StructuralTerm::ObservedValue {
                observed_type,
                descriptor: None,
                ..
            } = value
            else {
                return None;
            };
            (observed_type.is_valid()
                && crate::reference_shell(program, *observed_type).is_none()
                && program.primitive_type_reference(*observed_type).is_none())
            .then_some(*observed_type)
        }

        pub(crate) fn owned_projection_observation(
            program: &dyn crate::CheckingInput,
            declared: TypeReferenceHandle,
            value: StructuralTerm,
        ) -> StructuralTerm {
            if let Some(algebra) = crate::content_algebra_for_type(program, declared) {
                if matches!(&value, StructuralTerm::ContentValue { algebra: actual, .. } if actual == &algebra)
                {
                    value
                } else {
                    StructuralTerm::ContentValue {
                        algebra,
                        value: Box::new(value),
                    }
                }
            } else if shared_inline_observation_type(program, &value)
                .is_some_and(|observed| crate::declared_carriers_match(program, declared, observed))
            {
                value
            } else if crate::reference_shell(program, declared).is_some() {
                super::descriptor_only_observation(declared, value.into_collection_descriptor())
            } else if matches!(&value, StructuralTerm::ObservedValue { observed_type, descriptor: None, .. } if *observed_type == declared)
            {
                value
            } else {
                StructuralTerm::ObservedValue {
                    observed_type: declared,
                    value: Box::new(value),
                    descriptor: None,
                }
            }
        }

        pub(crate) fn shared_inline_observation_type(
            program: &dyn crate::CheckingInput,
            value: &StructuralTerm,
        ) -> Option<TypeReferenceHandle> {
            let StructuralTerm::ObservedValue {
                observed_type,
                value,
                descriptor: None,
            } = value
            else {
                return None;
            };
            let shell = crate::reference_shell(program, *observed_type)?;
            if shell.access != language_semantics::ReferenceAccess::Shared
                || crate::slice_view_shell(program, *observed_type, &[]).is_some()
            {
                return None;
            }
            let contents_type = owned_observation_type(program, value).or_else(|| {
                let StructuralTerm::ObservedValue {
                    observed_type,
                    descriptor: None,
                    ..
                } = value.as_ref()
                else {
                    return None;
                };
                let carrier = program
                    .type_reference_table
                    .unconstrained_type_reference(*observed_type);
                let TypeReferenceNode::Named { symbol, .. } =
                    program.type_reference_table.type_reference(carrier)
                else {
                    return None;
                };
                program
                    .symbols
                    .builtin_type_atom(*symbol)
                    .filter(|atom| !atom.is_atomic())?;
                program.primitive_type_reference(carrier)?;
                Some(*observed_type)
            })?;
            crate::declared_carriers_match(program, shell.referee, contents_type)
                .then_some(*observed_type)
        }

        pub(crate) fn shared_inline_observation(
            program: &dyn crate::CheckingInput,
            declared: TypeReferenceHandle,
            value: StructuralTerm,
        ) -> Option<StructuralTerm> {
            let shell = crate::reference_shell(program, declared)?;
            if program.primitive_type_reference(shell.referee).is_some()
                && !super::scalar_operand_is_observed(program, declared, &value)
            {
                return None;
            }
            let value = StructuralTerm::ObservedValue {
                observed_type: declared,
                value: Box::new(owned_projection_observation(program, shell.referee, value)),
                descriptor: None,
            };
            shared_inline_observation_type(program, &value)?;
            Some(value)
        }
    }
    pub(crate) use owned_observations::{
        owned_observation_type, owned_projection_observation, shared_inline_observation,
        shared_inline_observation_type,
    };
    pub(crate) mod scalar_operands {
        use super::StructuralTerm;
        use numerics::arithmetic::ArithmeticDomain;
        use typed_trees::types::{PrimitiveType, TypeReferenceHandle};

        pub(crate) fn scalar_operand_meaning(
            program: &dyn crate::CheckingInput,
            declared: TypeReferenceHandle,
            term: &StructuralTerm,
        ) -> Option<(PrimitiveType, ArithmeticDomain)> {
            let meaning = crate::value_custody::expression_types::scalar_observation_meaning(
                program, declared,
            )?;
            scalar_operand_is_observed(program, declared, term).then_some(meaning)
        }

        pub(crate) fn scalar_operand_is_observed(
            program: &dyn crate::CheckingInput,
            declared: TypeReferenceHandle,
            term: &StructuralTerm,
        ) -> bool {
            if let Some(observed) = super::shared_inline_observation_type(program, term) {
                return crate::declared_carriers_match(program, declared, observed);
            }
            if let Some(observed) = super::owned_observation_type(program, term) {
                return crate::reference_shell(program, declared).is_none()
                    && crate::declared_carriers_match(program, declared, observed);
            }
            if term_is_unobserved_descriptor(program, term) {
                return false;
            }
            if let StructuralTerm::ObservedValue { observed_type, .. } = term {
                return crate::value_custody::expression_types::scalar_observation_meaning(
                    program, declared,
                ) == crate::value_custody::expression_types::scalar_observation_meaning(
                    program,
                    *observed_type,
                );
            }
            if crate::reference_shell(program, declared).is_none() {
                return true;
            }
            match term {
                StructuralTerm::ObservedValue { .. } => unreachable!("handled above"),
                StructuralTerm::CollectionMeasure { .. }
                | StructuralTerm::Variable(_)
                | StructuralTerm::BoundValue(_)
                | StructuralTerm::BoundProjection { .. }
                | StructuralTerm::Integer(_)
                | StructuralTerm::Float(_)
                | StructuralTerm::Constructor { .. }
                | StructuralTerm::ScalarBinary { .. } => true,
                StructuralTerm::Application { result_type, .. }
                | StructuralTerm::CapturedValue { result_type, .. } => {
                    crate::value_custody::expression_types::scalar_observation_meaning(
                        program,
                        *result_type,
                    )
                    .is_some()
                        || (crate::reference_shell(program, *result_type).is_none()
                            && crate::reference_shell(program, declared).is_some_and(|shell| {
                                shell.access.is_readable()
                                    && crate::declared_carriers_match(
                                        program,
                                        shell.referee,
                                        *result_type,
                                    )
                            }))
                }
                StructuralTerm::IndexedValue { element_type, .. } => {
                    crate::value_custody::expression_types::scalar_observation_meaning(
                        program, declared,
                    ) == crate::value_custody::expression_types::scalar_observation_meaning(
                        program,
                        *element_type,
                    )
                }
                StructuralTerm::ScalarRepresentation { target, .. } => {
                    crate::value_custody::expression_types::scalar_observation_meaning(
                        program, declared,
                    )
                    .is_some_and(|(primitive, _)| primitive == *target)
                }
                StructuralTerm::Projection { subject, .. } => {
                    !has_produced_subject(subject)
                        || completed_owned_carrier(program, term).is_some_and(|reference| {
                            crate::reference_shell(program, declared).is_some_and(|shell| {
                                shell.access.is_readable()
                                    && crate::declared_carriers_match(
                                        program,
                                        shell.referee,
                                        reference,
                                    )
                            })
                        })
                }
                StructuralTerm::Identity { .. }
                | StructuralTerm::LogicalNot { .. }
                | StructuralTerm::ContentValue { .. }
                | StructuralTerm::Opaque(_)
                | StructuralTerm::RepeatedArray { .. }
                | StructuralTerm::IntegerEmbedding { .. }
                | StructuralTerm::MathematicalBinary { .. } => false,
            }
        }

        pub(crate) fn term_is_unobserved_descriptor(
            program: &dyn crate::CheckingInput,
            term: &StructuralTerm,
        ) -> bool {
            match term {
                StructuralTerm::ObservedValue {
                    observed_type,
                    value,
                    descriptor,
                } => {
                    let observed_slice_contents = crate::slice_view_shell(program, *observed_type, &[])
                .is_some_and(|slice| slice.access == language_semantics::ReferenceAccess::Shared)
                && !crate::proof_contracts::carrier_contents::type_has_forbidden_argument_observation_content(
                    program,
                    *observed_type,
                )
                && descriptor
                    .as_ref()
                    .is_some_and(|descriptor| descriptor.observation_identity_key().is_some())
                && value.observation_identity_key().is_some();
                    (program.primitive_type_reference(*observed_type).is_none()
                        && super::shared_inline_observation_type(program, term).is_none()
                        && super::owned_observation_type(program, term).is_none()
                        && !observed_slice_contents)
                        || term_is_unobserved_descriptor(program, value)
                }
                StructuralTerm::Application {
                    result_type,
                    arguments,
                    ..
                } => {
                    crate::reference_shell(program, *result_type).is_some()
                        || arguments
                            .iter()
                            .any(|argument| term_is_unobserved_descriptor(program, argument))
                }
                StructuralTerm::CapturedValue { result_type, .. } => {
                    crate::reference_shell(program, *result_type).is_some()
                }
                StructuralTerm::IndexedValue {
                    element_type,
                    collection,
                    index,
                    ..
                } => {
                    crate::reference_shell(program, *element_type).is_some()
                        || term_is_unobserved_descriptor(program, collection)
                        || term_is_unobserved_descriptor(program, index)
                }
                StructuralTerm::Constructor { fields, .. } => fields
                    .iter()
                    .any(|(_, value)| term_is_unobserved_descriptor(program, value)),
                StructuralTerm::Projection { subject, path } => {
                    term_is_unobserved_descriptor(program, subject)
                        || matches!(
                            subject.as_ref().semantic_value(),
                            StructuralTerm::Application { result_type, .. }
                                if super::call_projection_field_symbol(
                                    program,
                                    *result_type,
                                    path.split('.').next().unwrap_or_default(),
                                )
                                .is_none_or(|field| {
                                    program
                                        .closed_data_member_field(
                                            *result_type,
                                            field,
                                            path.split('.').next().unwrap_or_default(),
                                        )
                                        .is_none_or(|field| {
                                            crate::reference_shell(
                                                program,
                                                field.type_reference,
                                            )
                                            .is_some()
                                        })
                                })
                        )
                }
                StructuralTerm::ScalarBinary {
                    references,
                    left,
                    right,
                    ..
                } => {
                    !scalar_operand_is_observed(program, references[0], left)
                        || !scalar_operand_is_observed(program, references[1], right)
                }
                StructuralTerm::IntegerEmbedding { reference, value } => {
                    !scalar_operand_is_observed(program, *reference, value)
                }
                StructuralTerm::MathematicalBinary { left, right, .. } => {
                    term_is_unobserved_descriptor(program, left)
                        || term_is_unobserved_descriptor(program, right)
                }
                _ => false,
            }
        }

        pub(crate) fn completed_owned_carrier(
            program: &dyn crate::CheckingInput,
            term: &StructuralTerm,
        ) -> Option<TypeReferenceHandle> {
            let reference = match term {
                StructuralTerm::Constructor {
                    identity:
                        super::super::structural_judgment::ConstructorIdentity::Nominal {
                            reference,
                            ..
                        },
                    ..
                } => *reference,
                StructuralTerm::Application { result_type, .. }
                | StructuralTerm::CapturedValue { result_type, .. } => *result_type,
                StructuralTerm::IndexedValue { element_type, .. } => *element_type,
                StructuralTerm::Projection { subject, path } => {
                    let mut reference = completed_owned_carrier(program, subject)?;
                    for name in path.split('.') {
                        let definition = program.closed_data_definition(reference)?;
                        let mut fields =
                            program
                                .data_members(definition)
                                .iter()
                                .filter_map(|member| {
                                    let typed_trees::data::DataMember::Field(field) = member else {
                                        return None;
                                    };
                                    (field.name.as_str() == name).then_some(field)
                                });
                        let field = fields.next()?;
                        if fields.next().is_some() {
                            return None;
                        }
                        reference = program
                            .closed_data_member_field(reference, field.symbol, name)?
                            .type_reference;
                        if crate::reference_shell(program, reference).is_some() {
                            return None;
                        }
                    }
                    reference
                }
                _ => return None,
            };
            (reference.is_valid() && crate::reference_shell(program, reference).is_none())
                .then_some(reference)
        }

        fn has_produced_subject(term: &StructuralTerm) -> bool {
            match term {
                StructuralTerm::Application { .. } | StructuralTerm::CapturedValue { .. } => true,
                StructuralTerm::Projection { subject, .. } => has_produced_subject(subject),
                StructuralTerm::IndexedValue { collection, .. } => has_produced_subject(collection),
                _ => false,
            }
        }
    }
    pub(crate) mod scalar_representation {
        use super::StructuralTerm;
        use typed_trees::types::{PrimitiveType, TypeReferenceHandle};

        pub(crate) fn scalar_representation_term(
            program: &dyn crate::CheckingInput,
            cast: &typed_trees::expression::TableCastExpression,
            source: TypeReferenceHandle,
            value: StructuralTerm,
        ) -> Option<StructuralTerm> {
            if cast.form.recast_access() != Some(language_semantics::ReferenceAccess::Shared) {
                return None;
            }
            // A shared recast reads the place it borrows, so its operand term
            // can arrive as the borrow's shared observation (`&f32` over the
            // scalar) while `source` names the borrowed carrier (`f32`). That
            // observation holds exactly the scalar, so it is observed for the
            // recast; the representation below normalizes through the shell.
            let borrowed_observation = crate::reference_shell(program, source).is_none()
                && super::shared_inline_observation_type(program, &value).is_some_and(|observed| {
                    crate::reference_shell(program, observed).is_some_and(|shell| {
                        shell.access == language_semantics::ReferenceAccess::Shared
                            && crate::declared_carriers_match(program, source, shell.referee)
                    })
                });
            if !borrowed_observation && !super::scalar_operand_is_observed(program, source, &value)
            {
                return None;
            }
            let source_carrier = match crate::reference_shell(program, source) {
                Some(shell) if shell.access == language_semantics::ReferenceAccess::Shared => {
                    shell.referee
                }
                Some(_) => return None,
                None => source,
            };
            let source = program.primitive_type_reference(source_carrier)?;
            let target = program.primitive_type_reference(cast.target_type)?;
            let scalar = |primitive: PrimitiveType| {
                primitive.is_fixed_integer()
                    || matches!(primitive, PrimitiveType::F32 | PrimitiveType::F64)
            };
            if !scalar(source)
                || !scalar(target)
                || source.scalar_byte_size() != target.scalar_byte_size()
            {
                return None;
            }
            Some(normalize_scalar_representation(source, target, value))
        }

        pub(crate) fn normalize_scalar_representation(
            source: PrimitiveType,
            target: PrimitiveType,
            value: StructuralTerm,
        ) -> StructuralTerm {
            if source == target {
                return value;
            }
            if let StructuralTerm::ScalarRepresentation {
                source: original,
                target: intermediate,
                value: original_value,
            } = value.semantic_value()
                && *intermediate == source
            {
                return normalize_scalar_representation(*original, target, *original_value.clone());
            }
            if let Some(value) = represented_literal(source, target, &value) {
                return value;
            }
            StructuralTerm::ScalarRepresentation {
                source,
                target,
                value: Box::new(value),
            }
        }

        fn represented_literal(
            source: PrimitiveType,
            target: PrimitiveType,
            value: &StructuralTerm,
        ) -> Option<StructuralTerm> {
            use numerics::bignum::BigInt;
            use numerics::literals::{FloatFormat, FloatLiteral};
            let width = u32::try_from(source.scalar_byte_size()?).ok()? * 8;
            if source.scalar_byte_size() != target.scalar_byte_size() || width > 64 || width == 0 {
                return None;
            }
            let bits = match value.semantic_value() {
                StructuralTerm::Integer(value) if source.is_fixed_integer() => {
                    if source.is_signed_integer() {
                        value.to_i64()? as u64
                    } else {
                        value.to_u64()?
                    }
                }
                StructuralTerm::Float(value) => {
                    let format = match source {
                        PrimitiveType::F32 => FloatFormat::F32,
                        PrimitiveType::F64 => FloatFormat::F64,
                        _ => return None,
                    };
                    if value.landing().is_some_and(|landing| landing != format) {
                        return None;
                    }
                    if let Some((presented_format, bits)) = value.presented_bits() {
                        if presented_format != format {
                            return None;
                        }
                        bits
                    } else {
                        match format {
                            FloatFormat::F32 if !value.value_f32().is_nan() => {
                                u64::from(value.value_f32().to_bits())
                            }
                            FloatFormat::F64 if !value.value_f64().is_nan() => {
                                value.value_f64().to_bits()
                            }
                            _ => return None,
                        }
                    }
                }
                _ => return None,
            } & (u64::MAX >> (64 - width));
            Some(match target {
                PrimitiveType::F32 => {
                    StructuralTerm::Float(FloatLiteral::from_bits(FloatFormat::F32, bits)?)
                }
                PrimitiveType::F64 => {
                    StructuralTerm::Float(FloatLiteral::from_bits(FloatFormat::F64, bits)?)
                }
                primitive if primitive.is_fixed_integer() => {
                    StructuralTerm::Integer(if primitive.is_signed_integer() {
                        let shift = 64 - width;
                        BigInt::from_i64(((bits << shift) as i64) >> shift)
                    } else {
                        BigInt::from_u64(bits)
                    })
                }
                _ => return None,
            })
        }
    }
    pub(crate) use binary::{
        binary_term_in_scope, sealed_primitive_float_operator, unary_term_in_scope,
    };
    pub(crate) use constructors::{
        admitted_const_value_term, captured_constructor_term, case_classifier,
        case_guard_classifier, case_value_term, constructor_literal_term, is_case_observation,
        zero_constructor_operands, zero_value_structural_term,
    };
    pub(crate) use equality::{builtin_identity_operand_references, has_identity_equality_meaning};
    pub(crate) use scalar_operands::{
        completed_owned_carrier, scalar_operand_is_observed, scalar_operand_meaning,
        term_is_unobserved_descriptor,
    };
    pub(crate) use scalar_representation::{
        normalize_scalar_representation, scalar_representation_term,
    };

    pub(crate) fn denotation_preserving_conversion(
        program: &dyn crate::CheckingInput,
        cast: &typed_trees::expression::TableCastExpression,
        source: typed_trees::types::TypeReferenceHandle,
    ) -> bool {
        let integer = |reference| {
            program
                .primitive_type_reference(reference)
                .is_some_and(|primitive| {
                    primitive.is_fixed_integer()
                        || primitive == typed_trees::types::PrimitiveType::Addr
                })
        };
        !cast.form.is_recast()
            && ((integer(source) && integer(cast.target_type))
                || (crate::reference_shell(program, source).is_none()
                    && crate::reference_shell(program, cast.target_type).is_none()
                    && crate::declared_carriers_match(program, source, cast.target_type)
                    && program.arithmetic_domain_for_type_reference(source)
                        == program.arithmetic_domain_for_type_reference(cast.target_type)))
    }

    pub(crate) fn conversion_term(
        program: &dyn crate::CheckingInput,
        cast: &typed_trees::expression::TableCastExpression,
        source: Option<typed_trees::types::TypeReferenceHandle>,
        value: StructuralTerm,
    ) -> Option<StructuralTerm> {
        let Some(source) = source else {
            if cast.form.is_recast()
                || !crate::value_custody::literals::has_anonymous_numeric_results(
                    program, cast.value,
                )
            {
                return None;
            }
            let primitive = program
                .primitive_type_reference(cast.target_type)
                .filter(|primitive| primitive.is_fixed_integer())?;
            let StructuralTerm::Integer(integer) = value.semantic_value() else {
                return None;
            };
            crate::value_custody::literals::land_integer_value(integer, primitive)?;
            return Some(StructuralTerm::ObservedValue {
                observed_type: crate::value_custody::expression_types::cast_result_type_reference(
                    program, cast,
                )?,
                descriptor: None,
                value: Box::new(value),
            });
        };
        let source = if !cast.form.is_recast()
            && crate::reference_shell(program, source).is_some()
            && scalar_operand_is_observed(program, source, &value)
        {
            crate::value_custody::expression_types::readable_observation_type_reference(
                program, source,
            )?
        } else {
            source
        };
        if !denotation_preserving_conversion(program, cast, source) {
            return scalar_representation_term(program, cast, source, value);
        }
        let integer = |reference| {
            program
                .primitive_type_reference(reference)
                .is_some_and(|primitive| {
                    primitive.is_fixed_integer()
                        || primitive == typed_trees::types::PrimitiveType::Addr
                })
        };
        if integer(source) && integer(cast.target_type) {
            if !scalar_operand_is_observed(program, source, &value) {
                return None;
            }
            // A cast to its own carrier and policy (`buckets.len as u64` with a
            // `u64` length) denotes the same scalar. Wrapping it in an embedding
            // gave `width == buckets.len as u64` a different term from the
            // `buckets.len` in its sibling premises, so the equation never met
            // them. Keep it the plain value, as the uncast spelling is.
            let result =
                crate::value_custody::expression_types::cast_result_type_reference(program, cast)?;
            if program.primitive_type_reference(result) == program.primitive_type_reference(source)
                && program.arithmetic_domain_for_type_reference(result)
                    == program.arithmetic_domain_for_type_reference(source)
            {
                return Some(value);
            }
            return Some(StructuralTerm::ObservedValue {
                observed_type: crate::value_custody::expression_types::cast_result_type_reference(
                    program, cast,
                )?,
                descriptor: None,
                value: Box::new(StructuralTerm::IntegerEmbedding {
                    reference: source,
                    value: Box::new(value),
                }),
            });
        }
        Some(value)
    }

    pub(crate) fn integer_embedding_term(
        program: &dyn crate::CheckingInput,
        expression: ExpressionHandle,
        reference: typed_trees::types::TypeReferenceHandle,
        value: StructuralTerm,
    ) -> Option<StructuralTerm> {
        let (_, _argument) = crate::proof_contracts::proof_embeddings::integer_embedding_argument(
            program, expression,
        )?;
        Some(StructuralTerm::IntegerEmbedding {
            reference,
            value: Box::new(value),
        })
    }

    pub(crate) fn builtin_anonymous_comparison_term(
        program: &dyn crate::CheckingInput,
        expression: ExpressionHandle,
    ) -> Option<StructuralTerm> {
        crate::value_custody::literals::evaluate_anonymous_numeric_comparison(
            program,
            expression,
            &[],
            |source| {
                source == expression
                    || crate::value_custody::literals::has_anonymous_operator_meaning(
                        program, source,
                    )
            },
        )
        .map(StructuralTerm::boolean)
    }

    pub(crate) fn term_contains(haystack: &StructuralTerm, needle: &StructuralTerm) -> bool {
        haystack == needle
            || haystack
                .semantic_value()
                .any_child(|child| term_contains(child, needle))
    }

    pub(crate) fn unfold_constant_applications(
        program: &dyn crate::CheckingInput,
        term: StructuralTerm,
    ) -> StructuralTerm {
        let unfold = |value: StructuralTerm| unfold_constant_applications(program, value);
        match term {
            StructuralTerm::Application {
                result_type,
                target,
                selections,
                machine,
                arguments,
            } => {
                let arguments: Vec<_> = arguments
                    .into_iter()
                    .map(|argument| unfold_constant_applications(program, argument))
                    .collect();
                super::StructuralJudge::closed_application_value(
                    program,
                    result_type,
                    target,
                    &selections,
                    &arguments,
                    None,
                )
                .unwrap_or(StructuralTerm::Application {
                    result_type,
                    target,
                    selections,
                    machine,
                    arguments,
                })
            }
            StructuralTerm::Projection { subject, path } => {
                let mut value = unfold(*subject);
                for field_name in path.split('.') {
                    value = match value {
                        application @ StructuralTerm::Application { .. } => {
                            let StructuralTerm::Application {
                                result_type,
                                target,
                                selections,
                                arguments,
                                ..
                            } = &application
                            else {
                                unreachable!()
                            };
                            call_projection_field_symbol(program, *result_type, field_name)
                                .and_then(|field| {
                                    super::StructuralJudge::closed_application_value(
                                        program,
                                        *result_type,
                                        *target,
                                        selections,
                                        arguments,
                                        Some(field),
                                    )
                                })
                                .unwrap_or_else(|| {
                                    super::observed_projections::project_field(
                                        application,
                                        field_name,
                                    )
                                    .expect("application subjects always project")
                                })
                        }
                        value => {
                            super::observed_projections::project_field(value.clone(), field_name)
                                .unwrap_or_else(|| StructuralTerm::Projection {
                                    subject: Box::new(value),
                                    path: field_name.to_owned(),
                                })
                        }
                    };
                }
                value
            }
            other => other.map_children(unfold),
        }
    }

    pub(crate) fn term_spelling(
        program: &dyn crate::CheckingInput,
        term: &StructuralTerm,
    ) -> String {
        let arguments = |arguments: &[StructuralTerm]| {
            arguments
                .iter()
                .map(|argument| term_spelling(program, argument))
                .collect::<Vec<_>>()
                .join(", ")
        };
        match term {
            StructuralTerm::RepeatedArray { length, element } => match element {
                Some(element) => format!("[{}; {length}]", term_spelling(program, element)),
                None => "[]".to_owned(),
            },
            StructuralTerm::Variable(name) => name.clone(),
            StructuralTerm::ObservedValue { value, .. } => term_spelling(program, value),
            StructuralTerm::BoundValue(symbol) => program.symbols.name(*symbol).to_owned(),
            StructuralTerm::CapturedValue { expression, .. } => {
                expression_table(program).display_name(*expression)
            }
            StructuralTerm::BoundProjection { subject, path } => {
                format!("{}.{path}", program.symbols.name(*subject))
            }
            StructuralTerm::ScalarRepresentation {
                source,
                target,
                value,
            } => format!(
                "representation<{}, {}>({})",
                source.name(),
                target.name(),
                term_spelling(program, value)
            ),
            StructuralTerm::Integer(value) => value.to_string(),
            StructuralTerm::Float(value) => value.to_string(),
            StructuralTerm::Constructor {
                data, case, fields, ..
            } => {
                let head = if case.is_empty() || data == "bool" {
                    if data == "bool" {
                        case.clone()
                    } else {
                        data.clone()
                    }
                } else {
                    format!("{data}::{case}")
                };
                if fields.is_empty() {
                    return head;
                }
                let fields = fields
                    .iter()
                    .map(|(name, value)| format!("{name}: {}", term_spelling(program, value)))
                    .collect::<Vec<_>>()
                    .join(", ");
                format!("{head} {{ {fields} }}")
            }
            StructuralTerm::Application {
                machine,
                arguments: values,
                ..
            } => format!("{machine}({})", arguments(values)),
            StructuralTerm::CollectionMeasure {
                measure,
                collection,
            } => format!(
                "{}.{}",
                term_spelling(program, collection),
                measure.authored_spelling(),
            ),
            StructuralTerm::Projection { subject, path } => {
                format!("{}.{path}", term_spelling(program, subject))
            }
            StructuralTerm::IndexedValue {
                collection, index, ..
            } => format!(
                "{}[{}]",
                term_spelling(program, collection),
                term_spelling(program, index)
            ),
            StructuralTerm::IntegerEmbedding { value, .. } => {
                format!("embed({})", term_spelling(program, value))
            }
            StructuralTerm::MathematicalBinary {
                operator,
                left,
                right,
            }
            | StructuralTerm::ScalarBinary {
                operator,
                left,
                right,
                ..
            } => format!(
                "{} {} {}",
                term_spelling(program, left),
                operator.display_name(),
                term_spelling(program, right)
            ),
            StructuralTerm::LogicalNot { operand } => {
                format!("!({})", term_spelling(program, operand))
            }
            StructuralTerm::Identity {
                carrier,
                left,
                right,
            } => format!(
                "core::Identity<{}>({}, {})",
                program.type_identity_text(*carrier).unwrap_or_default(),
                term_spelling(program, left),
                term_spelling(program, right)
            ),
            StructuralTerm::ContentValue { algebra, value } => {
                format!("canonical {algebra:?}({})", term_spelling(program, value))
            }
            StructuralTerm::Opaque(display) => display.clone(),
        }
    }

    pub(crate) const SELECTED_OPERATION_IDENTITY_PREFIX: &str = "\0selected-operation:";

    pub(crate) fn structural_call_machine_name(
        target: &str,
        machine_arguments: &[StaticMachineArgument],
        machine_environment: &[(symbols::SymbolHandle, String, StaticMachineArgument)],
    ) -> String {
        let substitute = |name: String| {
            machine_environment
                .iter()
                .find(|(_, parameter, _)| parameter == &name)
                .map(|(_, _, selected)| selected.path.joined_path())
                .unwrap_or(name)
        };
        let target = substitute(target.to_owned());
        // Typed operation keys are complete. Their member arguments remain in
        // StructuralTerm::selections, independently of this identity string.
        if machine_arguments.is_empty() || target.starts_with(SELECTED_OPERATION_IDENTITY_PREFIX) {
            return target;
        }
        let selected: Vec<String> = machine_arguments
            .iter()
            .map(|argument| {
                let name = argument.path.joined_path();
                substitute(name)
            })
            .collect();
        format!("{target}<{}>", selected.join(","))
    }

    pub(crate) fn structural_predicate_call_selections(
        program: &dyn crate::CheckingInput,
        call: &typed_trees::expression::TableCallExpression,
    ) -> Vec<StaticMachineArgument> {
        call.static_requirement_dispatch
            .as_ref()
            .and_then(|dispatch| program.closed_requirement_application(dispatch.contract_symbol()))
            .map(|application| {
                expression_table(program)
                    .static_machine_application_arguments(application.application)
                    .to_vec()
            })
            .unwrap_or_else(|| call.machine_arguments.to_vec())
    }

    pub(crate) fn structural_predicate_call_machine_name(
        program: &dyn crate::CheckingInput,
        owner: symbols::SymbolHandle,
        call: &typed_trees::expression::TableCallExpression,
        machine_environment: &[(symbols::SymbolHandle, String, StaticMachineArgument)],
    ) -> Option<String> {
        // Selected predicates keep the complete typed map identity, including
        // its supplying regions, rather than a flattened namespace spelling.
        super::specification_calls::applied_bindings::operations::selected_call_operation_identity(
            program, owner, call,
        )
        .ok()
        .map(|selected| {
            structural_call_machine_name(
                selected.as_deref().unwrap_or(call.target.as_str()),
                &structural_predicate_call_selections(program, call),
                machine_environment,
            )
        })
    }

    pub(crate) fn structural_call_target(
        program: &dyn crate::CheckingInput,
        caller: symbols::SymbolHandle,
        call: &typed_trees::expression::TableCallExpression,
    ) -> symbols::SymbolHandle {
        if call.static_requirement_dispatch.is_none()
            && let Some(receiver) = expression_table(program).name_path_node(call.receiver)
            && receiver.symbol.is_valid()
            && program.symbols.get(receiver.symbol).kind
                == symbols::SymbolKind::ConformanceParameter
            && program
                .evidence_bound_requirement(
                    program.symbols.get(receiver.symbol).parent,
                    receiver.symbol,
                    call.target_symbol,
                )
                .ok()
                .flatten()
                .is_some()
        {
            let original = if call.authored_machine_application.is_valid() {
                expression_table(program)
                    .static_machine_application(call.authored_machine_application)
                    .registration_operation
            } else {
                symbols::SymbolHandle::invalid()
            };
            for target in [call.target_symbol, original] {
                if target.is_valid() && program.symbols.get(target).parent == receiver.symbol {
                    return target;
                }
            }
        }
        super::specification_calls::selected_call_contract(program, caller, call)
            .map(|owner| super::specification_calls::owner_symbol(&owner))
            .unwrap_or(call.target_symbol)
    }

    pub(crate) fn structural_term_pair(
        program: &dyn crate::CheckingInput,
        binary: &typed_trees::expression::TableBinaryExpression,
    ) -> Option<(StructuralTerm, StructuralTerm)> {
        let left = structural_term(program, None, None, binary.left, None)?;
        let right = structural_term(program, None, None, binary.right, None)?;
        let references = [binary.left, binary.right].map(|expression| {
            crate::proof_contracts::proof_embeddings::expression_type_reference(program, expression)
                .unwrap_or_default()
        });
        (scalar_operand_is_observed(program, references[0], &left)
            && scalar_operand_is_observed(program, references[1], &right))
        .then_some((left, right))
    }

    /// Read a formed declaration predicate without erasing its relation. Core Id
    /// retains its carrier/subjects; a selected Boolean call retains the complete
    /// application. An unsupported value or display-only term proves nothing.
    pub(crate) fn structural_predicate_for_parameters(
        program: &dyn crate::CheckingInput,
        scope: symbols::SymbolHandle,
        parameters: &[typed_trees::signature::StateParameter],
        expression: ExpressionHandle,
    ) -> Option<StructuralTerm> {
        structural_term(program, None, Some((scope, parameters)), expression, None).filter(
            |predicate| {
                predicate.is_checked_predicate()
                    || (!matches!(predicate.semantic_value(), StructuralTerm::Opaque(_))
                        && crate::parameter_expression_result_type_reference(
                            program, scope, parameters, expression,
                        )
                        .and_then(|reference| program.primitive_type_reference(reference))
                            == Some(typed_trees::types::PrimitiveType::Bool))
            },
        )
    }

    /// Bind both sides in the declaration's own telescope before substituting
    /// actual values. Applications retain the selected result carrier and policy.
    pub(crate) fn structural_term_pair_for_parameters(
        program: &dyn crate::CheckingInput,
        owner: symbols::SymbolHandle,
        parameters: &[typed_trees::signature::StateParameter],
        binary: &typed_trees::expression::TableBinaryExpression,
    ) -> Option<(StructuralTerm, StructuralTerm)> {
        let left = structural_term(program, None, Some((owner, parameters)), binary.left, None)?;
        let right = structural_term(program, None, Some((owner, parameters)), binary.right, None)?;
        let references = [binary.left, binary.right].map(|expression| {
            crate::parameter_expression_result_type_reference(
                program, owner, parameters, expression,
            )
            .unwrap_or_default()
        });
        (scalar_operand_is_observed(program, references[0], &left)
            && scalar_operand_is_observed(program, references[1], &right))
        .then_some((left, right))
    }

    pub(crate) fn source_operations_have_same_meaning(
        program: &dyn crate::CheckingInput,
        owner: symbols::SymbolHandle,
        parameters: &[typed_trees::signature::StateParameter],
        left: ExpressionHandle,
        right: ExpressionHandle,
    ) -> bool {
        let bindings = |expression| {
            let ExpressionNode::Name(path) = expression_table(program).expression(expression)
            else {
                return None;
            };
            if path.symbol.is_valid()
                && ((expression_table(program)
                    .name_path_members(path.members)
                    .len()
                    == 1
                    && parameters
                        .iter()
                        .any(|parameter| parameter.symbol == path.symbol))
                    || program.symbols.get(path.symbol).kind == symbols::SymbolKind::Const)
            {
                Some(StructuralTerm::BoundValue(path.symbol))
            } else {
                None
            }
        };
        fn complete(term: &StructuralTerm) -> bool {
            match term {
                StructuralTerm::BoundValue(symbol) => symbol.is_valid(),
                StructuralTerm::Integer(_) | StructuralTerm::Float(_) => true,
                StructuralTerm::ScalarBinary { left, right, .. }
                | StructuralTerm::MathematicalBinary { left, right, .. } => {
                    complete(left) && complete(right)
                }
                StructuralTerm::IntegerEmbedding { value, .. } => complete(value),
                _ => false,
            }
        }
        let form = |expression| {
            structural_term(
                program,
                None,
                Some((owner, parameters)),
                expression,
                Some(&bindings),
            )
        };
        match (form(left), form(right)) {
            (Some(left), Some(right)) => complete(&left) && complete(&right) && left == right,
            _ => false,
        }
    }

    pub(crate) fn static_type_predicate_term(
        program: &dyn crate::CheckingInput,
        expression: ExpressionHandle,
        substitutions: &[(
            symbols::SymbolHandle,
            typed_trees::types::TypeReferenceHandle,
        )],
    ) -> Option<StructuralTerm> {
        let (left, right, negate) = program.static_type_predicate_operands(expression)?;
        let value = if substitutions.is_empty() {
            program.static_type_predicate_value(expression)
        } else {
            program.applied_static_type_predicate_value(expression, substitutions)
        };
        if let Some(value) = value {
            return Some(StructuralTerm::boolean(value));
        }
        static_type_equation_term(program, left, right, negate, substitutions)
    }

    pub(crate) fn static_type_equation_term(
        program: &dyn crate::CheckingInput,
        left: typed_trees::types::TypeReferenceHandle,
        right: typed_trees::types::TypeReferenceHandle,
        negate: bool,
        substitutions: &[(
            symbols::SymbolHandle,
            typed_trees::types::TypeReferenceHandle,
        )],
    ) -> Option<StructuralTerm> {
        let identity = |reference| {
            program.type_identity_text(program.type_identity_with_simultaneous_substitutions(
                typed_trees::type_identity::TypeIdentityRequest {
                    substitutions,
                    ..typed_trees::type_identity::TypeIdentityRequest::package_qualified(reference)
                },
            ))
        };
        let closed = |reference| {
            typed_trees::domain::index_argument_is_closed_with_substitutions(
                program.typed_program(),
                reference,
                substitutions,
            )
        };
        let mut operands = [
            (identity(left)?, closed(left)),
            (identity(right)?, closed(right)),
        ];
        operands.sort_unstable();
        Some(StructuralTerm::Variable(format!(
            "$static-type-predicate:{}:{}:{}:{}:{negate}:{}{}",
            operands[0].0.len(),
            operands[0].0,
            operands[1].0.len(),
            operands[1].0,
            u8::from(operands[0].1),
            u8::from(operands[1].1),
        )))
    }

    pub(crate) fn open_closed_type_atom(name: &str) -> Option<(&str, &str)> {
        let rest = name.strip_prefix("$static-type-predicate:")?;
        let (first_length, rest) = rest.split_once(':')?;
        let first_length: usize = first_length.parse().ok()?;
        let first = rest.get(..first_length)?;
        let rest = rest.get(first_length..)?.strip_prefix(':')?;
        let (second_length, rest) = rest.split_once(':')?;
        let second_length: usize = second_length.parse().ok()?;
        let second = rest.get(..second_length)?;
        let rest = rest.get(second_length..)?.strip_prefix(':')?;
        let (negate, flags) = rest.split_once(':')?;
        match (negate, flags) {
            ("false", "01") => Some((first, second)),
            ("false", "10") => Some((second, first)),
            _ => None,
        }
    }

    pub(crate) fn structural_term(
        program: &dyn crate::CheckingInput,
        scope: Option<(
            &typed_trees::machine::Machine,
            &typed_trees::state::State,
            typed_trees::types::TypeReferenceHandle,
        )>,
        frame: Option<(
            symbols::SymbolHandle,
            &[typed_trees::signature::StateParameter],
        )>,
        expression: ExpressionHandle,
        bindings: Option<&dyn Fn(ExpressionHandle) -> Option<StructuralTerm>>,
    ) -> Option<StructuralTerm> {
        if program.static_type_predicate_operands(expression).is_some() {
            return static_type_predicate_term(program, expression, &[]);
        }
        if let Some(term) = bindings.and_then(|bindings| bindings(expression)) {
            return Some(term);
        }
        if let Some((_, argument)) =
            crate::proof_contracts::proof_embeddings::integer_embedding_argument(
                program, expression,
            )
        {
            let reference = if let Some((owner, parameters)) = frame {
                crate::parameter_expression_result_type_reference(
                    program, owner, parameters, argument,
                )
            } else {
                scope.and_then(|(machine, state, _)| {
                    crate::expression_result_type_reference(program, machine, state, argument)
                })
            }
            .or_else(|| {
                crate::proof_contracts::proof_embeddings::expression_type_reference(
                    program, argument,
                )
            })?;
            return integer_embedding_term(
                program,
                expression,
                reference,
                structural_term(program, scope, frame, argument, bindings)?,
            );
        }
        if let Some(value) = super::proof_integer::anonymous_integer_value(program, expression) {
            return Some(StructuralTerm::Integer(value));
        }
        match expression_table(program).expression(expression) {
            ExpressionNode::Name(path) => {
                if program.symbols.builtin_type_member(path.symbol)
                    == Some(symbols::BuiltinTypeMember::AddressBound)
                {
                    return Some(StructuralTerm::BoundValue(path.symbol));
                }
                let members = expression_table(program).name_path_members(path.members);
                if let Some((owner, parameters)) = frame {
                    if let Some(parameter) = parameters
                        .iter()
                        .find(|parameter| path.symbol.is_valid() && parameter.symbol == path.symbol)
                    {
                        return Some(StructuralTerm::Variable(parameter.name.to_string()));
                    }
                    if crate::reserved_result_owner(program, expression)
                        .is_some_and(|result_owner| result_owner.0 == owner)
                    {
                        return Some(StructuralTerm::Variable("result".to_owned()));
                    }
                    if case_classifier(program, expression).is_some() {
                        return case_value_term(program, expression);
                    }
                    if path.symbol.is_valid()
                        && program.symbols.get(path.symbol).kind == symbols::SymbolKind::Field
                    {
                        return None;
                    }
                    return path
                        .symbol
                        .is_valid()
                        .then_some(StructuralTerm::BoundValue(path.symbol));
                }
                match members {
                    [single] => Some(StructuralTerm::Variable(single.as_str().to_owned())),
                    [_, _, ..] if case_classifier(program, expression).is_some() => {
                        case_value_term(program, expression)
                    }
                    _ if path.symbol.is_valid()
                        && program.symbols.get(path.symbol).kind == symbols::SymbolKind::Const =>
                    {
                        Some(StructuralTerm::BoundValue(path.symbol))
                    }
                    _ => Some(StructuralTerm::Opaque(
                        expression_table(program).display_name(expression),
                    )),
                }
            }
            ExpressionNode::StructLiteral(literal) => {
                constructor_literal_term(program, expression, literal, |_, field| {
                    let field = field?;
                    structural_term(program, scope, frame, field.value, bindings)
                })
            }
            ExpressionNode::Binary(binary) => binary_term_in_scope(
                program,
                scope,
                frame,
                expression,
                structural_term(program, scope, frame, binary.left, bindings)?,
                structural_term(program, scope, frame, binary.right, bindings)?,
            ),
            ExpressionNode::Unary(unary) => unary_term_in_scope(
                program,
                scope,
                frame,
                expression,
                structural_term(program, scope, frame, unary.operand, bindings)?,
            ),
            ExpressionNode::Integer(value) => value.value_bignum().map(StructuralTerm::Integer),
            ExpressionNode::Cast(cast) => {
                let source = if let Some((owner, parameters)) = frame {
                    crate::parameter_expression_result_type_reference(
                        program, owner, parameters, cast.value,
                    )
                } else {
                    scope.and_then(|(machine, state, _)| {
                        crate::expression_result_type_reference(program, machine, state, cast.value)
                    })
                };
                let value = structural_term(program, scope, frame, cast.value, bindings)?;
                conversion_term(program, cast, source, value)
            }
            ExpressionNode::Float(value) => Some(StructuralTerm::Float(value.clone())),
            ExpressionNode::Call(call) => {
                if crate::mathematical_applications::is_mathematical_call(program, call) {
                    return mathematical_application_term(program, expression, |capture| {
                        structural_term(program, scope, frame, capture.expression, bindings)
                    });
                }
                let target = structural_call_target_in_frame(program, call, frame);
                let realization = realized_requirement_state(call);
                if (!call.receiver.is_valid()
                    || static_call_receiver_for_target(program, call, target))
                    && call.evidence_arguments.is_empty()
                    && (call.static_requirement_dispatch.is_none() || realization.is_some())
                {
                    let target = realization.unwrap_or(target);
                    let handles = expression_table(program).expression_handles(call.arguments);
                    let arguments: Vec<StructuralTerm> = handles
                        .iter()
                        .filter_map(|argument| {
                            structural_term(program, scope, frame, *argument, bindings)
                        })
                        .collect();
                    if arguments.len() == handles.len() {
                        let result_type = frame
                            .and_then(|(owner, parameters)| {
                                crate::parameter_expression_result_type_reference(
                                    program, owner, parameters, expression,
                                )
                            })
                            .or_else(|| {
                                scope.and_then(|(machine, state, _)| {
                                    crate::expression_result_type_reference(
                                        program, machine, state, expression,
                                    )
                                })
                            })
                            .unwrap_or_default();
                        return Some(StructuralTerm::Application {
                            result_type,
                            target,
                            selections: structural_predicate_call_selections(program, call),
                            machine: structural_predicate_call_machine_name(
                                program,
                                frame.map_or_else(
                                    || {
                                        scope.map_or(
                                            symbols::SymbolHandle::invalid(),
                                            |(machine, _, _)| machine.symbol,
                                        )
                                    },
                                    |(owner, _)| owner,
                                ),
                                call,
                                &[],
                            )?,
                            arguments,
                        });
                    }
                }
                Some(StructuralTerm::Opaque(
                    expression_table(program).display_name(expression),
                ))
            }
            ExpressionNode::Boolean(value) => Some(StructuralTerm::boolean(*value)),
            ExpressionNode::Member(member) => {
                let receiver_type = if let Some((owner, parameters)) = frame {
                    crate::parameter_expression_result_type_reference(
                        program,
                        owner,
                        parameters,
                        member.receiver,
                    )
                } else {
                    scope.and_then(|(machine, state, _)| {
                        crate::expression_result_type_reference(
                            program,
                            machine,
                            state,
                            member.receiver,
                        )
                    })
                }
                .or_else(|| {
                    crate::reserved_result_place(program, member.receiver)
                        .map(|place| place.type_reference)
                });
                if let Some(reference) = receiver_type
                    && let Some(measure) =
                        collection_measure_term(program, member, reference, || {
                            structural_term(program, scope, frame, member.receiver, bindings)
                        })
                {
                    return Some(measure);
                }
                if let Some(call) = expression_table(program).call_node(member.receiver)
                    && (!call.receiver.is_valid()
                        || static_call_receiver_for_target(
                            program,
                            call,
                            structural_call_target_in_frame(program, call, frame),
                        ))
                    && call.evidence_arguments.is_empty()
                    && call.static_requirement_dispatch.is_none()
                    && program.state_by_symbol(call.target_symbol).is_some()
                {
                    let handles = expression_table(program).expression_handles(call.arguments);
                    let arguments = handles
                        .iter()
                        .filter_map(|argument| {
                            structural_term(program, scope, frame, *argument, bindings)
                        })
                        .collect::<Vec<_>>();
                    if arguments.len() == handles.len() {
                        let result_type = program
                            .state_by_symbol(call.target_symbol)
                            .map(|state| state.return_type)?;
                        call_projection_field_symbol(program, result_type, member.member.as_str())?;
                        return Some(StructuralTerm::Projection {
                            subject: Box::new(StructuralTerm::Application {
                                result_type,
                                target: structural_call_target_in_frame(program, call, frame),
                                selections: call.machine_arguments.to_vec(),
                                machine: structural_call_machine_name(
                                    call.target.as_str(),
                                    &call.machine_arguments,
                                    &[],
                                ),
                                arguments,
                            }),
                            path: member.member.as_str().to_owned(),
                        });
                    }
                }
                let declared_field = receiver_type
                    .and_then(|reference| {
                        crate::value_custody::places::applied_data_member_field(
                            program, reference, member,
                        )
                    })
                    .is_some();
                match structural_term(program, scope, frame, member.receiver, bindings) {
                    Some(StructuralTerm::Constructor { fields, .. }) => fields
                        .into_iter()
                        .find(|(name, _)| name == member.member.as_str())
                        .map(|(_, term)| term)
                        .or_else(|| {
                            Some(StructuralTerm::Opaque(
                                expression_table(program).display_name(expression),
                            ))
                        }),
                    Some(
                        subject @ (StructuralTerm::Variable(_)
                        | StructuralTerm::Projection { .. }
                        | StructuralTerm::Application { .. }
                        | StructuralTerm::CapturedValue { .. }
                        | StructuralTerm::IndexedValue { .. }),
                    ) if declared_field && !term_is_unobserved_descriptor(program, &subject) => {
                        super::observed_projections::project_field(subject, member.member.as_str())
                    }
                    _ => Some(StructuralTerm::Opaque(
                        expression_table(program).display_name(expression),
                    )),
                }
            }
            ExpressionNode::Indexed(indexed) => {
                // Indexing an array literal at a constant index denotes the
                // selected element itself, as with a constant substituted from
                // `const SOURCE: [u64; 1] = [3]`. Formation has already proved
                // the index in range; any other index stays unformed.
                if let ExpressionNode::ArrayLiteral(elements) =
                    expression_table(program).expression(indexed.collection)
                {
                    let StructuralTerm::Integer(position) =
                        structural_term(program, scope, frame, indexed.index, bindings)?
                    else {
                        return None;
                    };
                    let element = position
                        .to_u64()
                        .and_then(|position| usize::try_from(position).ok())
                        .and_then(|position| {
                            expression_table(program)
                                .expression_handles(*elements)
                                .get(position)
                                .copied()
                        })?;
                    return structural_term(program, scope, frame, element, bindings);
                }
                indexed_term_in_scope(
                    program,
                    scope,
                    frame,
                    expression,
                    structural_term(program, scope, frame, indexed.collection, bindings)?,
                    structural_term(program, scope, frame, indexed.index, bindings)?,
                )
            }
            ExpressionNode::ZeroValue(type_reference) => {
                zero_value_structural_term(program, *type_reference)
            }
            ExpressionNode::Borrow(borrow) => borrow_term_in_scope(
                program,
                scope,
                frame,
                expression,
                structural_term(program, scope, frame, borrow.target, bindings)?,
            ),
            _ => None,
        }
    }

    pub(crate) fn static_call_receiver(
        program: &dyn crate::CheckingInput,
        caller: symbols::SymbolHandle,
        call: &typed_trees::expression::TableCallExpression,
    ) -> bool {
        static_call_receiver_for_target(
            program,
            call,
            structural_call_target(program, caller, call),
        )
    }

    pub(crate) fn realized_requirement_state(
        call: &typed_trees::expression::TableCallExpression,
    ) -> Option<symbols::SymbolHandle> {
        call.static_requirement_dispatch
            .as_ref()
            .filter(|dispatch| dispatch.realization_state.is_valid())
            .map(|dispatch| dispatch.realization_state)
    }

    fn static_call_receiver_for_target(
        program: &dyn crate::CheckingInput,
        call: &typed_trees::expression::TableCallExpression,
        target: symbols::SymbolHandle,
    ) -> bool {
        if program.call_has_no_runtime_receiver_for_target(call) {
            return true;
        }
        if call.target_symbol.is_valid()
            && let Some(receiver) = expression_table(program).name_path_node(call.receiver)
            && crate::machine_calls::calls::requirement_namespace_member(
                program,
                receiver.symbol,
                call.target_symbol,
            )
        {
            return true;
        }
        let mut selected = call.clone();
        selected.target_symbol = target;
        program.call_has_no_runtime_receiver_for_target(&selected)
    }

    pub(crate) fn structural_call_target_in_frame(
        program: &dyn crate::CheckingInput,
        call: &typed_trees::expression::TableCallExpression,
        frame: Option<(
            symbols::SymbolHandle,
            &[typed_trees::signature::StateParameter],
        )>,
    ) -> symbols::SymbolHandle {
        let target = structural_call_target(
            program,
            frame.map_or(symbols::SymbolHandle::invalid(), |(owner, _)| owner),
            call,
        );
        if target.is_valid()
            && let Some(receiver) = expression_table(program).name_path_node(call.receiver)
            && receiver.symbol.is_valid()
            && program.symbols.get(receiver.symbol).kind
                == symbols::SymbolKind::ConformanceParameter
            && program.symbols.get(target).parent == receiver.symbol
        {
            return target;
        }
        frame
            .and_then(|(owner, parameters)| {
                super::specification_calls::selected_call_contract_for_parameters(
                    program, call, owner, parameters,
                )
            })
            .map(|owner| super::specification_calls::owner_symbol(&owner))
            .unwrap_or(target)
    }

    pub(crate) fn call_projection_field_symbol(
        program: &dyn crate::CheckingInput,
        result_type: typed_trees::types::TypeReferenceHandle,
        field_name: &str,
    ) -> Option<symbols::SymbolHandle> {
        let data = crate::value_custody::places::data_definition_for_type(program, result_type)?;
        program
            .data_field_named(data, field_name)
            .map(|field| field.symbol)
    }

    pub(crate) fn selected_application_machine(
        program: &dyn crate::CheckingInput,
        target: symbols::SymbolHandle,
    ) -> Option<&typed_trees::machine::Machine> {
        if !target.is_valid() {
            return None;
        }
        // The state index answers "the only machine entered at `target`" from the
        // same table-order rows a scan of every machine would visit.
        program
            .unique_machine_by_entry_state_symbol(target)
            .map(|(machine, _)| machine)
    }
}
pub(crate) mod transparent_applications {
    /*
    Entailment of transparent proposition applications.

    A transparent proposition is its body: unfolding an application binds the
    declaration's parameters to the actual argument terms and yields one
    checked predicate per conjunct, following `= other(..)` definitions to
    their own bodies. The same unfolding serves both directions -- a `requires`
    application installs its predicates as hypotheses, an `ensures` application
    must prove every one -- so a defined premise means exactly what the
    defined goal means.
    */

    use crate::frozen_program::expression_table;
    use crate::proof_contracts::contract_entailment::structural_judgment::{
        StructuralJudge, StructuralJudgment, StructuralTerm,
    };
    use crate::proof_contracts::contract_entailment::structural_terms::structural_term;
    use typed_trees::domain::ProofFact;
    use typed_trees::expression::{BinaryOperator, ExpressionHandle};
    use typed_trees::machine::Machine;
    use typed_trees::proposition::PropositionBody;
    use typed_trees::signature::SignatureContractKind;

    /// The checked predicates one transparent application denotes, one per
    /// conjunct of its unfolded body. `None` when the application is not
    /// transparent. A `None` conjunct lies outside the structural language: a
    /// hypothesis drops it (only weakening), a goal cannot be proven. A literal
    /// `true` conjunct contributes no obligation. Explicit Id retains its carrier
    /// and subjects; a Boolean comparison retains its selected operation.
    pub(crate) fn transparent_application_conjuncts(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: &typed_trees::state::State,
        application: &typed_trees::proposition::PropositionApplication,
    ) -> Option<Vec<Option<StructuralTerm>>> {
        let declaration = program.proposition_definition_by_symbol(application.proposition)?;
        if !matches!(declaration.body, PropositionBody::Transparent { .. }) {
            return None;
        }
        let parameters = program.proposition_parameters(declaration);
        let arguments = expression_table(program).expression_handles(application.arguments);
        if parameters.len() != arguments.len() {
            return None;
        }
        let environment = parameters
            .iter()
            .zip(arguments)
            .map(|(parameter, argument)| {
                Some((
                    parameter.name.as_str().to_owned(),
                    argument_term(program, machine, state, *argument)?,
                ))
            })
            .collect::<Option<Vec<_>>>()?;
        let mut conjuncts = Vec::new();
        unfold_definition(
            program,
            declaration.symbol,
            &environment,
            &mut Vec::new(),
            &mut conjuncts,
        );
        Some(conjuncts)
    }

    fn unfold_definition(
        program: &dyn crate::CheckingInput,
        proposition: symbols::SymbolHandle,
        environment: &[(String, StructuralTerm)],
        visiting: &mut Vec<symbols::SymbolHandle>,
        conjuncts: &mut Vec<Option<StructuralTerm>>,
    ) {
        let Some(declaration) = program.proposition_definition_by_symbol(proposition) else {
            conjuncts.push(None);
            return;
        };
        let PropositionBody::Transparent {
            proposition: formula,
        } = &declaration.body
        else {
            conjuncts.push(None);
            return;
        };
        if visiting.contains(&proposition) {
            conjuncts.push(None);
            return;
        }
        let parameters = program.proposition_parameters(declaration);
        visiting.push(proposition);
        match formula {
            typed_trees::proposition::PropositionFormula::BooleanExpression(expression) => {
                unfold_boolean(
                    program,
                    declaration.symbol,
                    parameters,
                    *expression,
                    environment,
                    conjuncts,
                );
            }
            typed_trees::proposition::PropositionFormula::Application(expansion) => {
                let inner = program
                    .proposition_definition_by_symbol(expansion.proposition)
                    .map(|inner| program.proposition_parameters(inner));
                let arguments = expression_table(program).expression_handles(expansion.arguments);
                let inner_environment = inner
                    .filter(|inner| inner.len() == arguments.len())
                    .and_then(|inner| {
                        inner
                            .iter()
                            .zip(arguments)
                            .map(|(parameter, argument)| {
                                let term = structural_term(
                                    program,
                                    None,
                                    Some((declaration.symbol, parameters)),
                                    *argument,
                                    None,
                                )?;
                                Some((
                                    parameter.name.as_str().to_owned(),
                                    StructuralJudge::substitute_term(&term, environment),
                                ))
                            })
                            .collect::<Option<Vec<_>>>()
                    });
                match inner_environment {
                    Some(inner_environment) => unfold_definition(
                        program,
                        expansion.proposition,
                        &inner_environment,
                        visiting,
                        conjuncts,
                    ),
                    None => conjuncts.push(None),
                }
            }
        }
        visiting.pop();
    }

    fn unfold_boolean(
        program: &dyn crate::CheckingInput,
        scope: symbols::SymbolHandle,
        parameters: &[typed_trees::signature::StateParameter],
        expression: ExpressionHandle,
        environment: &[(String, StructuralTerm)],
        conjuncts: &mut Vec<Option<StructuralTerm>>,
    ) {
        if let Some(binary) = expression_table(program).binary_node(expression)
            && binary.operator == BinaryOperator::And
        {
            unfold_boolean(
                program,
                scope,
                parameters,
                binary.left,
                environment,
                conjuncts,
            );
            unfold_boolean(
                program,
                scope,
                parameters,
                binary.right,
                environment,
                conjuncts,
            );
            return;
        }
        // `true` is the unit of conjunction: it owes a goal nothing and grants a
        // premise nothing. A total relation (`= true`) therefore unfolds to no
        // obligations rather than one unreadable conjunct.
        if expression_table(program).boolean_node(expression) == Some(&true) {
            return;
        }
        conjuncts.push(
            super::structural_terms::structural_predicate_for_parameters(
                program, scope, parameters, expression,
            )
            .map(|predicate| StructuralJudge::substitute_term(&predicate, environment)),
        );
    }

    pub(crate) fn intake_transparent_requires(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: &typed_trees::state::State,
        contracts: &[typed_trees::signature::SignatureContract],
        judge: &mut StructuralJudge<'_>,
    ) {
        for application in contracts
            .iter()
            .filter(|contract| contract.kind == SignatureContractKind::Requires)
            .flat_map(|contract| program.proof_facts.span_or_empty(contract.facts))
            .filter_map(ProofFact::as_proposition)
        {
            for predicate in transparent_application_conjuncts(program, machine, state, application)
                .into_iter()
                .flatten()
                .flatten()
            {
                judge.intake_observed_predicate(predicate, 0);
            }
        }
    }

    pub struct InheritedRequirementEdge<'edge> {
        pub trait_definition: &'edge typed_trees::trait_definition::TraitDefinition,
        pub requirement: &'edge typed_trees::signature::StateSignature,
        pub trait_arguments: &'edge [typed_trees::types::TypeReferenceHandle],
    }

    /// Prove one transparent proposition application through the same
    /// structural entailment engine used for ordinary Boolean contracts. Named
    /// propositions remain the public fact identity; transparency is only the
    /// proof-side expansion. Every conjunct of the unfolded body must be an
    /// checked predicate the hypotheses prove; a primitive or witness-bearing
    /// proposition is never transparent. A requirement-authored `goal` first
    /// moves through its `inherited` edge: the selected family replaces the
    /// proposition parameter and the requirement's parameters rename
    /// positionally onto the satisfier's.
    pub fn transparent_proposition_application_entailed(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: &typed_trees::state::State,
        goal: &typed_trees::proposition::PropositionApplication,
        inherited: Option<InheritedRequirementEdge<'_>>,
    ) -> bool {
        let (conjuncts, renames) = match inherited {
            None => (
                transparent_application_conjuncts(program, machine, state, goal),
                Vec::new(),
            ),
            Some(edge) => {
                let Some(endpoint) = crate::inherited_requirement_proposition_application(
                    program,
                    edge.trait_definition,
                    edge.requirement,
                    state,
                    edge.trait_arguments,
                    goal,
                ) else {
                    return false;
                };
                let Some(satisfier_parameters) = crate::inherited_satisfier_parameters(
                    program,
                    edge.trait_definition,
                    edge.requirement,
                    state,
                ) else {
                    return false;
                };
                let renames = program
                    .state_signature_parameters(edge.requirement)
                    .iter()
                    .zip(satisfier_parameters)
                    .map(|(required, actual)| {
                        (
                            required.name.as_str().to_owned(),
                            StructuralTerm::Variable(actual.name.as_str().to_owned()),
                        )
                    })
                    .collect::<Vec<_>>();
                (
                    transparent_application_conjuncts(
                        program,
                        machine,
                        state,
                        &endpoint.application,
                    ),
                    renames,
                )
            }
        };
        premises_prove(program, machine, state, conjuncts, &renames)
    }

    pub fn transparent_call_requirement_entailed(
        program: &dyn crate::CheckingInput,
        caller: &Machine,
        caller_state: &typed_trees::state::State,
        callee: &Machine,
        callee_state: &typed_trees::state::State,
        arguments: &[ExpressionHandle],
        requirement: &typed_trees::proposition::PropositionApplication,
    ) -> bool {
        let parameters = program.state_parameters(callee_state);
        if parameters.len() != arguments.len() {
            return false;
        }
        let Some(bindings) = parameters
            .iter()
            .zip(arguments)
            .map(|(parameter, argument)| {
                Some((
                    parameter.name.as_str().to_owned(),
                    argument_term(program, caller, caller_state, *argument)?,
                ))
            })
            .collect::<Option<Vec<_>>>()
        else {
            return false;
        };
        premises_prove(
            program,
            caller,
            caller_state,
            transparent_application_conjuncts(program, callee, callee_state, requirement),
            &bindings,
        )
    }

    fn premises_prove(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: &typed_trees::state::State,
        conjuncts: Option<Vec<Option<StructuralTerm>>>,
        renames: &[(String, StructuralTerm)],
    ) -> bool {
        let Some(predicates) =
            conjuncts.and_then(|conjuncts| conjuncts.into_iter().collect::<Option<Vec<_>>>())
        else {
            return false;
        };
        let expression_requires = program
            .contract_expressions(
                program
                    .machine_contracts(machine)
                    .iter()
                    .chain(program.state_contracts(state)),
                SignatureContractKind::Requires,
            )
            .collect::<Vec<_>>();
        let mut judge =
            StructuralJudge::from_requires(program, machine, &expression_requires, true);
        for contracts in [
            program.machine_contracts(machine),
            program.state_contracts(state),
        ] {
            intake_transparent_requires(program, machine, state, contracts, &mut judge);
        }
        judge.hypotheses_contradictory
            || predicates.into_iter().all(|predicate| {
                let predicate = StructuralJudge::substitute_term(&predicate, renames);
                matches!(
                    judge.judge_observed_predicate(predicate, 0),
                    StructuralJudgment::Proven
                )
            })
    }

    fn argument_term(
        program: &dyn crate::CheckingInput,
        caller_machine: &Machine,
        caller_state: &typed_trees::state::State,
        expression: ExpressionHandle,
    ) -> Option<StructuralTerm> {
        // Keep the whole typed application. Identity correspondence can consume
        // its exact call/argument identity; synthetic field projections would lose
        // that admitted value before the predicate receives it.
        structural_term(
            program,
            Some((caller_machine, caller_state, Default::default())),
            None,
            expression,
            None,
        )
    }
}

